// Pre-generated, era-aware historical summaries for the major
// territories/empires in the dataset. Keys match the GeoJSON
// NAME/SUBJECTO exactly (same convention as curatedTerritories.ts).
//
// Each entry is a list of periods; the side panel picks the period that
// contains the year currently shown on the slider, so clicking "Roman
// Empire" in 100 BC vs 400 AD gives era-appropriate text. Territories
// not listed here fall back to a generic message.
//
// This is a curated subset (the historically prominent states), not the
// full ~1700-name dataset — see README.
export type EraSummary = { from: number; to: number; text: string };

export const TERRITORY_SUMMARIES: Record<string, EraSummary[]> = {
  // === Ancient Near East / Mediterranean / classical world ===
  Ur: [{ from: -2900, to: -500, text: "Ur foi uma das mais importantes cidades-estado da Suméria, situada no sul da Mesopotâmia, perto do antigo curso do rio Eufrates, no atual Iraque. Alcançou seu apogeu durante a Terceira Dinastia de Ur, por volta de 2112 a.C., quando governou um vasto império e produziu grandes zigurates dedicados ao deus-lua Nanna. Foi também célebre por seus túmulos reais e por sua ligação tradicional ao patriarca bíblico Abraão." }],
  Elam: [{ from: -2700, to: -539, text: "Elam foi uma antiga civilização localizada no sudoeste do atual Irã, tendo como principais centros as cidades de Susa e Anshan. Rival e vizinha da Mesopotâmia, desenvolveu uma escrita própria e alternou períodos de guerra e comércio com sumérios, acádios e babilônios. Seu poder declinou após conquistas assírias e persas, sendo finalmente absorvida pelo Império Aquemênida." }],
  Babylonia: [
    { from: -1894, to: -1595, text: "A Babilônia foi um reino da baixa Mesopotâmia centrado na cidade de Babilônia, às margens do Eufrates. Sob o rei Hamurábi, no século XVIII a.C., unificou a região e ficou célebre por seu código de leis, um dos mais antigos conjuntos jurídicos conhecidos." },
    { from: -626, to: -539, text: "No período neobabilônico, a Babilônia renasceu como grande potência sob Nabopolassar e Nabucodonosor II, que reconstruíram a cidade com esplendor. Deste período datam os famosos jardins suspensos e a Porta de Ishtar, além do exílio dos judeus. O reino caiu diante de Ciro, o Grande, da Pérsia, em 539 a.C." },
  ],
  Assyria: [
    { from: -1350, to: -1050, text: "A Assíria foi um reino do norte da Mesopotâmia centrado na cidade de Assur, às margens do rio Tigre. No período médio-assírio afirmou-se como potência militar, expandindo-se sobre os territórios vizinhos e desenvolvendo uma poderosa tradição guerreira e administrativa." },
    { from: -911, to: -609, text: "No período neoassírio, a Assíria tornou-se o maior império do Oriente Próximo, dominando da Mesopotâmia ao Egito a partir de capitais como Nínive e Nimrud. Era temida por seu exército profissional e por sua administração implacável. Enfraquecida por revoltas, sucumbiu à aliança de medos e babilônios com a queda de Nínive em 612 a.C." },
  ],
  Egypt: [
    { from: -3100, to: -30, text: "O Egito Antigo foi uma das mais duradouras civilizações da história, desenvolvida ao longo do vale do rio Nilo, no nordeste da África. Governado por faraós considerados divinos, ergueu monumentos como as pirâmides de Gizé e a Esfinge, e legou uma rica escrita hieroglífica, religião e arte. Depois de milênios de esplendor, foi conquistado por persas, gregos e, por fim, incorporado a Roma após a morte de Cleópatra em 30 a.C." },
    { from: 641, to: 1798, text: "Após séculos de domínio romano e bizantino, o Egito foi conquistado pelos árabes muçulmanos no século VII, tornando-se um importante centro islâmico. Sob dinastias como os fatímidas, aiúbidas e mamelucos, o Cairo floresceu como polo de comércio, religião e cultura, antes de ser integrado ao Império Otomano em 1517." },
    { from: 1801, to: 2025, text: "No período moderno, o Egito passou pela modernização iniciada por Maomé Ali, pela ocupação britânica e, em 1922, pela independência. Tornou-se república em 1953 e figura central do mundo árabe, palco de eventos como a nacionalização do Canal de Suez e a Primavera Árabe de 2011." },
  ],
  Canaan: [{ from: -3000, to: -1200, text: "Canaã era a região do Levante meridional que corresponde aproximadamente ao atual Israel, Palestina, Líbano e partes da Síria e Jordânia. Habitada por povos cananeus organizados em cidades-estado, foi um vibrante entreposto comercial entre o Egito, a Mesopotâmia e o Mediterrâneo. É amplamente mencionada em textos egípcios e na tradição bíblica como a Terra Prometida." }],
  Minoan: [{ from: -3000, to: -1100, text: "A civilização minoica floresceu na ilha de Creta, no mar Egeu, sendo considerada a primeira grande civilização da Europa. Ficou célebre por seus palácios como o de Cnossos, por seus afrescos coloridos e por uma cultura marítima próspera. Seu declínio está associado à erupção vulcânica de Thera e à posterior ascensão dos micênicos." }],
  Cycladic: [{ from: -3200, to: -2000, text: "A civilização cicládica desenvolveu-se nas ilhas Cíclades, no mar Egeu, durante a Idade do Bronze. É especialmente conhecida por suas enigmáticas figuras de mármore de linhas geométricas e minimalistas, hoje admiradas como obras-primas da arte antiga. Sua sociedade marítima comerciava obsidiana e metais por todo o Egeu antes de ser eclipsada pelas culturas minoica e micênica." }],
  Hittites: [{ from: -1650, to: -1178, text: "Os hititas formaram um poderoso império na Anatólia central, com capital em Hattusa, no atual território da Turquia. Foram pioneiros no uso do ferro e rivais do Egito, com quem travaram a batalha de Cadesh e assinaram um dos primeiros tratados de paz conhecidos. Seu império entrou em colapso durante o grande desmoronamento da Idade do Bronze." }],
  Urartu: [{ from: -860, to: -590, text: "Urartu foi um reino da Idade do Ferro situado em torno do lago Van, no planalto armênio, entre a atual Turquia, Armênia e Irã. Rival da Assíria, destacou-se pela engenharia hidráulica, pela metalurgia e por suas fortalezas montanhosas. Enfraquecido por invasões, desapareceu diante do avanço dos medos e citas." }],
  Phrygians: [{ from: -1200, to: -700, text: "Os frígios foram um povo que se estabeleceu na Anatólia centro-ocidental após a queda do império hitita, com capital em Górdio. São lembrados na tradição pelos lendários reis Midas, do toque de ouro, e Górdio, do célebre nó górdio. Seu reino foi devastado por invasões cimérias e depois absorvido por lídios e persas." }],
  "Indus valley civilization": [{ from: -3300, to: -1300, text: "A civilização do vale do Indo foi uma das primeiras grandes civilizações urbanas do mundo, estendendo-se pelo atual Paquistão e noroeste da Índia. Suas cidades, como Harappa e Mohenjo-Daro, impressionam pelo planejamento urbano, sistemas de esgoto e uma escrita ainda não decifrada. Seu declínio, por volta de 1300 a.C., é atribuído a mudanças climáticas e ao deslocamento de rios." }],
  "Achaemenid Empire": [{ from: -550, to: -330, text: "O Império Aquemênida, fundado por Ciro, o Grande, foi o primeiro grande império persa e o maior do mundo antigo até então, estendendo-se do vale do Indo à Ásia Menor e ao Egito. Notável por sua tolerância cultural, sua rede de estradas e o sistema administrativo de satrapias, teve capitais como Persépolis e Susa. Foi conquistado por Alexandre, o Grande, em 330 a.C." }],
  "Empire of Alexander": [{ from: -336, to: -323, text: "O império de Alexandre, o Grande, foi forjado em pouco mais de uma década de campanhas militares que levaram o rei macedônio da Grécia ao Egito e até a Índia. Derrotando o Império Persa, criou o maior domínio já visto até então e difundiu a cultura grega pelo Oriente. Com sua morte precoce em 323 a.C., o império fragmentou-se entre seus generais, os diádocos, inaugurando o período helenístico." }],
  "Greek city-states": [{ from: -800, to: -146, text: "As cidades-estado gregas, ou póleis, como Atenas, Esparta, Corinto e Tebas, foram comunidades políticas independentes que definiram a civilização grega antiga. Berço da democracia, da filosofia, do teatro e dos Jogos Olímpicos, alternaram cooperação e rivalidade, como nas Guerras Médicas contra a Pérsia e na Guerra do Peloponeso. Perderam a independência para a Macedônia e, por fim, para Roma." }],
  Macedonia: [{ from: -808, to: -146, text: "A Macedônia foi um reino do norte da Grécia que ascendeu de potência periférica a hegemônica sob Filipe II, que unificou as cidades gregas. Seu filho, Alexandre, o Grande, transformou-a no centro de um vasto império que espalhou a cultura helênica pelo mundo antigo. Após as guerras contra Roma, o reino foi dissolvido e tornou-se província romana em 146 a.C." }],
  "Macedon and Hellenic League": [{ from: -338, to: -322, text: "A Liga Helênica, também chamada Liga de Corinto, foi uma federação de cidades gregas organizada por Filipe II da Macedônia após sua vitória em Queroneia em 338 a.C. Sob a liderança macedônia, uniu os gregos, exceto Esparta, com o objetivo declarado de invadir a Pérsia. Serviu de base política para as campanhas de Alexandre, mas desintegrou-se após sua morte." }],
  Carthage: [{ from: -814, to: -146, text: "Cartago foi uma cidade fundada por colonos fenícios de Tiro na costa do atual norte da Tunísia. Tornou-se a maior potência comercial e marítima do Mediterrâneo ocidental, com uma poderosa marinha e uma rede de colônias. Após as três Guerras Púnicas contra Roma, foi arrasada em 146 a.C., encerrando sua história como cidade independente." }],
  "Carthaginian Empire": [{ from: -575, to: -146, text: "O Império Cartaginês foi a rede de territórios, colônias e rotas comerciais dominada por Cartago no Mediterrâneo ocidental, abrangendo o norte da África, a Ibéria, a Sardenha e a Sicília. Baseava sua força no comércio e em exércitos de mercenários, e teve em Aníbal seu maior general durante a Segunda Guerra Púnica. Foi definitivamente destruído por Roma em 146 a.C." }],
  Rome: [
    { from: -753, to: -509, text: "Roma teve início, segundo a tradição, com sua fundação em 753 a.C. às margens do rio Tibre, na península Itálica. Em seus primeiros séculos foi governada por reis, período em que absorveu influências etruscas, latinas e sabinas e lançou as bases de suas instituições. A expulsão do último rei em 509 a.C. deu origem à República." },
    { from: -509, to: 476, text: "Ao longo de mais de um milênio, Roma cresceu de uma cidade-estado do Lácio até o maior império da Antiguidade, dominando todo o Mediterrâneo, a Europa ocidental e o Oriente Próximo. Legou ao mundo o direito, a engenharia, a língua latina e formas de organização política que moldaram a civilização ocidental. Sua história abrange a Monarquia, a República e o Império, até a queda do Ocidente em 476 d.C." },
  ],
  "Roman Empire": [{ from: -27, to: 476, text: "O Império Romano surgiu quando Otávio, sob o título de Augusto, tornou-se o primeiro imperador em 27 a.C., encerrando a República. No seu apogeu, estendeu-se da Britânia ao Egito e da Ibéria à Mesopotâmia, unido por estradas, legiões e uma administração comum. Após séculos de esplendor e a longa Pax Romana, o Império do Ocidente ruiu em 476 d.C. diante das invasões germânicas." }],
  "Roman Republic": [{ from: -509, to: -27, text: "A República Romana foi o regime instaurado em 509 a.C. após a expulsão dos reis, caracterizado por magistrados eleitos, pelo Senado e pela divisão de poderes entre patrícios e plebeus. Durante esse período, Roma conquistou toda a Itália e expandiu-se pelo Mediterrâneo, derrotando Cartago nas Guerras Púnicas. Abalada por guerras civis e pela ambição de generais como César, a República deu lugar ao Império em 27 a.C." }],
  "Rome (Diocletianus)": [{ from: 284, to: 305, text: "Sob o imperador Diocleciano, que reinou de 284 a 305 d.C., Roma passou por profundas reformas destinadas a conter a crise do século III. Ele instituiu a Tetrarquia, dividindo o governo entre quatro co-imperadores, reorganizou as províncias e a economia, e reforçou o caráter absolutista do poder imperial. Seu reinado também ficou marcado pela última grande perseguição aos cristãos." }],
  "Byzantine Empire": [{ from: 330, to: 1453, text: "O Império Bizantino foi a continuação do Império Romano no Oriente, com capital em Constantinopla, fundada por Constantino em 330 d.C. De língua grega e fé cristã ortodoxa, preservou o legado romano e helênico por mil anos, com auge sob Justiniano e seu código de leis. Após séculos de declínio, caiu diante dos turcos otomanos com a tomada de Constantinopla em 1453." }],
  "Eastern Roman Empire": [{ from: 395, to: 1453, text: "O Império Romano do Oriente originou-se da divisão definitiva do Império Romano em 395 d.C., com capital em Constantinopla. Mais rico e urbanizado que o Ocidente, sobreviveu à queda deste e evoluiu para o que os historiadores chamam de Império Bizantino. Perdurou até 1453, quando Constantinopla foi conquistada pelos otomanos." }],
  "Western Roman Empire": [{ from: 395, to: 476, text: "O Império Romano do Ocidente resultou da partilha do Império Romano em 395 d.C., reunindo os territórios de língua latina da Europa ocidental e do norte da África. Fragilizado por crises econômicas, pressões nas fronteiras e sucessivas invasões germânicas, teve capitais como Roma e Ravena. Deixou de existir em 476 d.C., quando o general Odoacro depôs o último imperador, Rômulo Augústulo." }],
  "Seleucid Kingdom": [{ from: -312, to: -63, text: "O Reino Selêucida foi um dos grandes Estados helenísticos surgidos da fragmentação do império de Alexandre, fundado pelo general Seleuco I Nicátor em 312 a.C. Em seu apogeu, estendeu-se da Anatólia e Síria até a Pérsia e as fronteiras da Índia, difundindo a cultura grega pelo Oriente. Enfraquecido por revoltas e pela pressão de Roma e dos partos, foi por fim anexado por Pompeu em 63 a.C." }],
  "Ptolemaic Kingdom": [{ from: -305, to: -30, text: "O Reino Ptolomaico foi um Estado helenístico fundado por Ptolomeu I Sóter, general de Alexandre, o Grande, após a morte deste. Com capital em Alexandria, os Ptolomeus governaram o Egito por quase três séculos, promovendo a cultura grega e ao mesmo tempo adotando tradições faraônicas. O reino terminou com a morte de Cleópatra VII e a anexação do Egito por Roma." }],
  "Parthian Empire": [{ from: -247, to: 224, text: "O Império Parta, fundado pela dinastia arsácida, dominou o planalto iraniano e a Mesopotâmia, tornando-se rival de Roma no Oriente. Sua cavalaria e táticas de arqueiros montados garantiram vitórias importantes, como a de Carras contra os romanos. O império declinou por conflitos internos até ser substituído pelos sassânidas." }],
  "Sasanian Empire": [{ from: 224, to: 651, text: "O Império Sassânida, fundado por Ardashir I, foi a última grande potência persa antiga antes do Islã. Rival duradouro do Império Romano e depois Bizantino, revitalizou o zoroastrismo como religião oficial e alcançou notável desenvolvimento cultural e artístico. Enfraquecido por guerras, sucumbiu à expansão árabe-muçulmana no século VII." }],
  Scythians: [{ from: -700, to: -300, text: "Os citas eram povos nômades de língua irânica que dominaram as estepes ao norte do Mar Negro e da Ásia Central. Exímios cavaleiros e arqueiros, ficaram famosos por sua arte em ouro e por seus túmulos monumentais chamados kurgans. Sua confederação acabou absorvida por outros povos das estepes, como os sármatas." }],
  Sabines: [{ from: -750, to: -290, text: "Os sabinos eram um povo itálico que habitava as colinas a nordeste de Roma. A lenda do rapto das sabinas descreve a fusão inicial entre eles e os primeiros romanos, e vários costumes romanos teriam origem sabina. Foram gradualmente conquistados e integrados à República Romana." }],
  Celts: [{ from: -800, to: 100, text: "Os celtas foram um conjunto de povos que compartilhavam línguas e cultura, espalhados por grande parte da Europa, da Ibéria às Ilhas Britânicas. Organizados em tribos, destacaram-se na metalurgia do ferro e na arte decorativa de estilo La Tène. Foram progressivamente submetidos pela expansão romana e por migrações germânicas." }],

  // === South / East / Central Asia ===
  "Mauryan Empire": [{ from: -322, to: -185, text: "O Império Máuria, fundado por Chandragupta Máuria, foi o primeiro Estado a unificar a maior parte do subcontinente indiano. Sob o imperador Ashoka, alcançou seu apogeu e adotou o budismo, promovendo edifícios e éditos que difundiram princípios de não violência. Após a morte de Ashoka, o império fragmentou-se rapidamente." }],
  "Gupta Empire": [{ from: 320, to: 550, text: "O Império Gupta é frequentemente lembrado como uma era de ouro da Índia clássica, marcada por avanços em matemática, astronomia, literatura e artes. Governantes como Chandragupta II presidiram um período de prosperidade e florescimento do hinduísmo. As invasões dos hunos brancos e as pressões internas levaram ao seu declínio." }],
  Han: [{ from: -206, to: 220, text: "A dinastia Han foi uma das mais duradouras e influentes da história chinesa, consolidando o modelo imperial iniciado pelos Qin. Adotou o confucionismo como base do Estado, expandiu o território e abriu a Rota da Seda ao comércio com o Ocidente. O período Han é tão fundamental que o principal grupo étnico chinês ainda se autodenomina 'han'." }],
  "Han Empire": [{ from: -206, to: 220, text: "O Império Han governou a China por mais de quatro séculos, estabelecendo instituições burocráticas e um serviço civil baseado no mérito e no confucionismo. Sob imperadores como Wu, o território expandiu-se enormemente e a Rota da Seda ligou a China ao mundo mediterrâneo. Após um período de esplendor cultural e tecnológico, o império desintegrou-se em meio a revoltas e disputas entre senhores da guerra." }],
  Qin: [{ from: -221, to: -206, text: "A dinastia Qin, sob Qin Shi Huang, unificou pela primeira vez a China em um único império centralizado. Impôs padronização de escrita, moeda, pesos e medidas, além de iniciar a construção de partes da Grande Muralha e do famoso Exército de Terracota. Seu governo rígido e legalista provocou revoltas, e a dinastia ruiu poucos anos após a morte do primeiro imperador." }],
  "Zhow states": [{ from: -1046, to: -256, text: "Os Estados Zhou correspondem ao período em que a dinastia Zhou governou a China, o mais longo de sua história dinástica. Sob o conceito do Mandato do Céu, o poder central foi se fragmentando em numerosos Estados semi-independentes. As fases das Primaveras e Outonos e dos Reinos Combatentes trouxeram guerras constantes, mas também o florescimento filosófico de Confúcio, Laozi e outros pensadores." }],
  "Zhou states": [{ from: -1046, to: -256, text: "Os Estados Zhou referem-se à China sob a dinastia Zhou, marcada pela descentralização do poder em múltiplos principados. O ideal do Mandato do Céu legitimava o governante, enquanto rivalidades entre Estados levaram aos períodos das Primaveras e Outonos e dos Reinos Combatentes. Foi uma era de intensa efervescência intelectual, berço das grandes escolas filosóficas chinesas." }],
  "Sui Empire": [{ from: 581, to: 618, text: "O Império Sui reunificou a China após séculos de divisão que se seguiram à queda dos Han. Empreendeu obras monumentais, como o Grande Canal, que ligou o norte ao sul e impulsionou o comércio e a integração. O esgotamento provocado por guerras e projetos custosos levou à rápida queda da dinastia, sucedida pelos Tang." }],
  "Tang Empire": [{ from: 618, to: 907, text: "O Império Tang é considerado uma era de ouro da civilização chinesa, marcada por grande esplendor cultural, cosmopolitismo e expansão territorial. A capital Chang'an tornou-se uma das maiores cidades do mundo, e a poesia, a arte e o budismo floresceram. Revoltas internas, como a de An Lushan, enfraqueceram gradualmente o poder imperial até a fragmentação final." }],
  "Song Empire": [{ from: 960, to: 1279, text: "O Império Song destacou-se por notáveis avanços econômicos, tecnológicos e culturais, incluindo a pólvora, a imprensa por tipos móveis e o uso do papel-moeda. Apesar da prosperidade e do refinamento artístico, enfrentou pressão militar constante de povos do norte. Acabou conquistado pelos mongóis, que fundaram a dinastia Yuan." }],
  "Ming Chinese Empire": [{ from: 1368, to: 1644, text: "O Império Ming restaurou o governo chinês nativo após o domínio mongol dos Yuan. Foi um período de grande vitalidade, com as viagens marítimas do almirante Zheng He, a reconstrução da Grande Muralha e a construção da Cidade Proibida. Crises econômicas, rebeliões e pressões externas levaram ao seu colapso e à ascensão dos manchus." }],
  "Manchu Empire": [{ from: 1636, to: 1912, text: "O Império Manchu, mais conhecido como dinastia Qing, foi fundado pelos manchus, que conquistaram a China após a queda dos Ming. Governou o maior território da história imperial chinesa, incorporando a Mongólia, o Tibete e o Turquestão Oriental. No século XIX, o declínio, as pressões coloniais e revoltas internas culminaram no fim do sistema imperial em 1912." }],
  "Qing Empire": [{ from: 1636, to: 1912, text: "O Império Qing foi a última dinastia imperial da China, estabelecida pelos manchus. Sob imperadores como Kangxi e Qianlong, alcançou grande expansão territorial e prosperidade, mas enfrentou depois a decadência marcada pelas Guerras do Ópio e por rebeliões devastadoras. Sua queda em 1912 encerrou mais de dois milênios de governo imperial na China." }],
  Xiongnu: [{ from: -209, to: 155, text: "Os xiongnu formaram uma poderosa confederação nômade das estepes ao norte da China, considerados por muitos os grandes rivais da dinastia Han. Sob líderes como Modu Chanyu, ameaçaram constantemente as fronteiras chinesas, forçando tributos e acordos matrimoniais. Divisões internas e a pressão chinesa acabaram fragmentando e dispersando sua confederação." }],
  "Kushan Empire": [{ from: 30, to: 375, text: "O Império Kushan, de origem nômade iuechi, dominou a Ásia Central e o norte do subcontinente indiano, controlando rotas cruciais da Rota da Seda. Sob soberanos como Kanishka, tornou-se um grande difusor do budismo e berço da arte greco-budista de Gandara, mesclando influências helenísticas, persas e indianas." }],
  Bactria: [{ from: -256, to: -125, text: "O Reino Greco-Báctrio surgiu quando governantes helenísticos da Ásia Central se separaram do Império Selêucida. Situada no atual Afeganistão, a Báctria foi um vibrante ponto de encontro entre as culturas grega, persa e indiana, antes de cair diante de invasores nômades." }],
  Magadha: [{ from: -600, to: -300, text: "Magadha foi um dos grandes reinos da Índia antiga, no vale do Ganges, e berço de impérios como o Máuria. Foi um importante centro do surgimento do budismo e do jainismo, além de núcleo do primeiro grande império pan-indiano." }],
  Satavahanihara: [{ from: -100, to: 220, text: "O império Satavahana dominou o Decã, servindo de ponte cultural e comercial entre o norte e o sul da Índia. Foram protetores do budismo e do comércio, cunhando moedas próprias e patrocinando monumentos como os de Amaravati." }],
  Pallavas: [{ from: 275, to: 897, text: "A dinastia Pallava governou o sudeste da Índia a partir de Kanchipuram, exercendo notável influência cultural sobre o sul da Ásia. Pioneiros da arquitetura dravídica em pedra, deixaram os célebres monumentos de Mamallapuram." }],
  Rashtrakuta: [{ from: 753, to: 982, text: "A dinastia Rashtrakuta dominou grande parte do Decã, na Índia, tornando-se uma das maiores potências do subcontinente. Foram grandes mecenas das artes, patrocinando os templos rupestres de Ellora, incluindo o monumental templo de Kailasa." }],
  "Chola state": [{ from: 848, to: 1279, text: "O Império Chola, do sul da Índia, tornou-se uma das maiores potências marítimas de seu tempo sob Rajaraja I e Rajendra I, projetando poder até o Sudeste Asiático. Destacou-se pela administração eficiente, pelos grandes templos dedicados a Xiva e pela refinada escultura em bronze." }],
  Cholas: [{ from: 848, to: 1279, text: "A dinastia Chola foi um dos mais duradouros e poderosos impérios do sul da Índia, com expedições navais que alcançaram o Sudeste Asiático. Destacou-se pela administração eficiente, pela arte em bronze e por grandiosos templos como o de Brihadeeswara." }],
  Vijayanagara: [{ from: 1336, to: 1646, text: "O Império de Vijayanagara ergueu-se no sul da Índia como baluarte hindu diante dos sultanatos islâmicos do Decã. Sob dinastias como a Tuluva e o reinado de Krishnadevaraya, alcançou grande prosperidade comercial e esplendor arquitetônico, até ser abalado pela derrota de Talikota em 1565." }],
  "Sultanate of Delhi": [{ from: 1206, to: 1526, text: "O Sultanato de Delhi foi uma sucessão de dinastias muçulmanas que dominaram o norte da Índia a partir de 1206, começando com a dinastia Mameluca. Ao longo de séculos, sultões como Alauddin Khalji e a dinastia Tughlaq expandiram e defenderam o território contra invasões mongóis. O sultanato introduziu a arquitetura indo-islâmica e novas estruturas administrativas antes de ser suplantado pelos mogóis." }],
  "Maratha Confederacy": [{ from: 1674, to: 1818, text: "A Confederação Marata surgiu na Índia central e ocidental a partir do reino fundado por Shivaji, desafiando o domínio mogol. Organizada como uma aliança de chefes militares sob os peshwas, tornou-se a principal potência do subcontinente antes de ser derrotada pelos britânicos." }],
  "Mughal Empire": [{ from: 1526, to: 1857, text: "O Império Mogol foi fundado por Babur em 1526 após a vitória em Panipat, unificando grande parte do subcontinente indiano sob domínio muçulmano. Sob Akbar, Jahangir e Shah Jahan, floresceu uma cultura sincrética célebre por monumentos como o Taj Mahal e por uma administração sofisticada. A partir do século XVIII, o império fragmentou-se e sucumbiu à expansão britânica, sendo formalmente extinto em 1857." }],
  "Ghaznavid Emirate": [{ from: 977, to: 1186, text: "O Emirado Gaznévida foi uma dinastia de origem turca centrada em Gásni, no atual Afeganistão. Sob Mahmud de Gásni, realizou numerosas campanhas na Índia e tornou-se um importante mecenas da cultura persa-islâmica." }],

  // === Steppe / Central Asian / Islamic empires ===
  "Mongol Empire": [{ from: 1206, to: 1368, text: "O Império Mongol, fundado por Gêngis Khan, tornou-se o maior império terrestre contíguo da história, estendendo-se da Coreia à Europa Oriental. Sua cavalaria e organização militar permitiram conquistas rápidas e a integração de rotas comerciais euroasiáticas sob a chamada Pax Mongolica. Após a morte de Gêngis, o império dividiu-se em canatos que gradualmente se desintegraram." }],
  "Great Khanate": [{ from: 1260, to: 1368, text: "O Grande Canato foi a porção central do Império Mongol liderada pelo Grande Cã, especialmente sob Kublai Khan, que estabeleceu a dinastia Yuan na China. Nominalmente supremo sobre os demais canatos, na prática concentrou-se no domínio do Leste Asiático. Sua autoridade declinou com revoltas e com a expulsão dos mongóis da China pelos Ming." }],
  "Golden Horde": [{ from: 1242, to: 1502, text: "A Horda de Ouro foi o canato mongol-turco surgido da divisão do império de Gêngis Khan, dominando as estepes russas e a Ásia central ocidental. Impôs tributo aos principados russos por mais de dois séculos, antes de fragmentar-se em canatos menores e ser extinta por rivais tártaros e russos." }],
  "Crimean Khanate": [{ from: 1441, to: 1783, text: "O Canato da Crimeia, herdeiro da Horda de Ouro e governado pela dinastia Girai, tornou-se vassalo do Império Otomano no fim do século XV. Sustentado em grande parte por incursões e pelo comércio de escravos nas terras eslavas, foi por fim anexado pela Rússia de Catarina II." }],
  "Timurid Empire": [{ from: 1370, to: 1507, text: "O Império Timúrida foi fundado por Tamerlão (Timur), conquistador turco-mongol que ergueu um vasto domínio a partir da Ásia Central. Samarcanda, sua capital, tornou-se um centro brilhante de arte, ciência e arquitetura islâmica. Após a morte de Timur, disputas sucessórias fragmentaram o império, embora seu legado cultural tenha inspirado o posterior Império Mogol." }],
  "Samanid Empire": [{ from: 819, to: 999, text: "O Império Samânida, de origem persa, governou a Transoxiana e o Grande Coração a partir de centros como Bucara e Samarcanda. Foi um brilhante foco de renascimento cultural persa e do saber islâmico, patrocinando poetas e sábios, até cair diante de dinastias turcas emergentes." }],
  "Seljuk Empire": [{ from: 1037, to: 1194, text: "O Império Seljúcida, fundado por turcos oguzes, dominou a Pérsia, a Mesopotâmia e a Anatólia, tornando-se protetor do califado abássida. Sua vitória em Manziquerta, em 1071, abriu a Anatólia à colonização turca e ajudou a desencadear as Cruzadas, antes da fragmentação em Estados sucessores." }],
  "Abbasid Caliphate": [{ from: 750, to: 1258, text: "O Califado Abássida derrubou os Omíadas e transferiu o centro do mundo islâmico para Bagdá. Presidiu a uma era de ouro da ciência, filosofia, medicina e tradução do saber grego, com instituições como a Casa da Sabedoria. Enfraquecido politicamente ao longo dos séculos, foi encerrado pela conquista mongol de Bagdá em 1258." }],
  "Umayyad Caliphate": [{ from: 661, to: 750, text: "O Califado Omíada, com capital em Damasco, foi a primeira grande dinastia hereditária do Islã e presidiu à maior expansão territorial árabe. Seu domínio estendeu-se da Península Ibérica à Ásia Central, difundindo a língua árabe e a administração islâmica. Foi derrubado pela revolução abássida, embora um ramo sobrevivente tenha fundado o emirado de Córdoba na Espanha." }],
  "Fatimid Caliphate": [{ from: 909, to: 1171, text: "O Califado Fatímida foi um Estado xiita ismaelita que dominou o norte da África e depois o Egito, onde fundou a cidade do Cairo. Rival dos califados abássida e omíada, promoveu comércio próspero e criou a célebre universidade de Al-Azhar. Seu poder declinou por crises internas até ser suprimido por Saladino, que restaurou o sunismo no Egito." }],
  "Ottoman Empire": [{ from: 1299, to: 1922, text: "O Império Otomano surgiu na Anatólia e cresceu até se tornar uma das maiores potências do mundo, controlando territórios na Europa, Ásia e África. A conquista de Constantinopla em 1453 marcou o fim do Império Bizantino e consolidou seu poder, atingindo o auge sob Solimão, o Magnífico. Após séculos de declínio gradual, o império desmoronou depois da Primeira Guerra Mundial, dando lugar à República da Turquia." }],
  "Safavid Empire": [{ from: 1501, to: 1736, text: "O Império Safávida governou a Pérsia a partir de 1501, quando o xá Ismail I fundou a dinastia e estabeleceu o islamismo xiita como religião oficial, moldando a identidade religiosa do Irã até hoje. Sob o xá Abbas I, o império alcançou seu apogeu cultural e militar, com Isfahan tornando-se um centro esplendoroso de arte e arquitetura. Rivalizou constantemente com o Império Otomano antes de entrar em declínio e ruir diante de invasores afegãos." }],

  // === Persia / Caucasus / Arabia (long-lived) ===
  Persia: [
    { from: -550, to: -330, text: "O Império Aquemênida, primeira grande manifestação da Pérsia antiga, foi fundado por Ciro, o Grande, e estendeu-se do Egito ao vale do Indo. Célebre por sua administração descentralizada em satrapias, estradas reais e tolerância cultural, foi conquistado por Alexandre, o Grande." },
    { from: 224, to: 651, text: "O Império Sassânida restaurou o poder persa, promovendo o zoroastrismo como religião oficial e rivalizando com Roma e Bizâncio por séculos. Foi um centro de arte, arquitetura e ciência antes de sucumbir à expansão árabe-islâmica no século VII." },
    { from: 1501, to: 1979, text: "A Pérsia moderna, sob dinastias como os Safávidas, os Cajares e os Pahlavi, consolidou o xiismo como identidade nacional e disputou influência com potências vizinhas e europeias. O país foi oficialmente renomeado Irã em 1935 e tornou-se república após a Revolução de 1979." },
  ],
  Georgia: [
    { from: -300, to: 580, text: "Os antigos reinos georgianos da Ibéria e da Cólquida ocupavam o Cáucaso Sul, região disputada entre Roma e a Pérsia. A adoção do cristianismo no início do século IV moldou profundamente sua cultura e identidade." },
    { from: 1008, to: 1490, text: "O Reino da Geórgia unificado alcançou sua Idade de Ouro sob monarcas como David IV e a rainha Tamar, expandindo territórios e florescendo nas artes e nas letras. As invasões mongóis e timúridas enfraqueceram o reino, que acabou fragmentado." },
    { from: 1991, to: 2024, text: "A Geórgia moderna reconquistou a independência com o colapso da União Soviética em 1991. Desde então, o país busca aproximação com o Ocidente, enfrentando conflitos territoriais e tensões com a Rússia." },
  ],
  Armenia: [
    { from: 301, to: 1045, text: "Na Antiguidade tardia e no período medieval, a Armênia destacou-se por ter sido o primeiro Estado a adotar oficialmente o cristianismo, em 301. Governada por dinastias como os Arsácidas e os Bagrátidas, oscilou entre a independência e a submissão a impérios vizinhos como Roma, Pérsia e Bizâncio. O reino Bagrátida floresceu com sua capital em Ani antes de cair sob domínio bizantino e seljúcida." },
    { from: 1918, to: 2024, text: "No período moderno, os armênios sofreram o genocídio perpetrado pelo Império Otomano durante a Primeira Guerra Mundial, um dos maiores traumas de sua história. Uma breve república independente surgiu em 1918, logo absorvida pela União Soviética. A Armênia recuperou plena independência em 1991, após a dissolução da URSS." },
  ],
  "Nabatean Kingdom": [{ from: -312, to: 106, text: "Reino de comerciantes árabes centrado na cidade rupestre de Petra, os nabateus prosperaram controlando as rotas de caravanas de incenso e especiarias entre a Arábia, o Levante e o Mediterrâneo. Dominavam sofisticadas técnicas de gestão da água no deserto antes de serem anexados pelo Império Romano em 106 d.C." }],
  Saba: [{ from: -800, to: 275, text: "Reino situado no sul da Arábia, no atual Iêmen, Sabá enriqueceu com o comércio de incenso e mirra e com a agricultura irrigada pela grande represa de Marib. Associada na tradição à lendária rainha de Sabá, foi uma das mais influentes civilizações da Arábia antiga." }],
  "Himyarite Kingdom": [{ from: -110, to: 525, text: "Sucedendo Sabá como potência dominante do sul da Arábia, o Reino Himiarita unificou a região e controlou lucrativas rotas comerciais. Notabilizou-se por adotar o monoteísmo, incluindo o judaísmo entre suas elites, antes de cair sob invasões aksumitas e persas." }],

  // === Europe ===
  "Frankish Kingdom": [{ from: 481, to: 751, text: "O Reino Franco foi consolidado por Clóvis I, da dinastia merovíngia, que unificou as tribos francas e converteu-se ao cristianismo católico. Sucessor do poder romano na Gália, lançou as bases políticas e religiosas da futura Europa ocidental, apesar das repetidas divisões dinásticas do território." }],
  "Carolingian Empire": [{ from: 800, to: 888, text: "O Império Carolíngio atingiu seu ápice com Carlos Magno, coroado imperador em 800, reunindo grande parte da Europa ocidental sob domínio franco. Promoveu o chamado Renascimento Carolíngio nas letras e nas artes, mas fragmentou-se após o Tratado de Verdun, dando origem a França e Alemanha." }],
  "Holy Roman Empire": [{ from: 800, to: 1806, text: "O Sacro Império Romano-Germânico teve origem na coroação de Carlos Magno em 800 e consolidou-se como uma entidade política da Europa Central, especialmente sob Otão I. Foi uma confederação descentralizada de reinos, ducados e cidades livres, unidos sob um imperador eleito, frequentemente em tensão com o papado. Enfraquecido por guerras religiosas e fragmentação, foi dissolvido em 1806 durante as guerras napoleônicas." }],
  Visigoths: [{ from: 418, to: 711, text: "Os visigodos foram um povo germânico que, após saquear Roma em 410, estabeleceu um reino na Gália e depois na Península Ibérica, com capital em Toledo. Convertidos do arianismo ao catolicismo, elaboraram códigos legais influentes até serem varridos pela conquista muçulmana de 711." }],
  Ostrogoths: [{ from: 493, to: 553, text: "Os ostrogodos, liderados por Teodorico, o Grande, fundaram um reino na Itália após derrotar Odoacro, preservando boa parte das instituições romanas. Esse Estado, marcado por relativa tolerância entre godos e romanos, foi destruído pela reconquista bizantina de Justiniano nas Guerras Góticas." }],
  Vandals: [{ from: 435, to: 534, text: "Os vândalos, povo germânico, migraram pela Europa até estabelecer um reino no norte da África, com capital em Cartago. Dotados de forte poder naval, saquearam Roma em 455 e dominaram o Mediterrâneo ocidental, até serem conquistados pelo general bizantino Belisário." }],
  Huns: [{ from: 370, to: 469, text: "Os hunos foram um povo nômade das estepes que irrompeu na Europa, pressionando as tribos germânicas e abalando o Império Romano. Sob Átila, o \"Flagelo de Deus\", formaram um vasto império de tributos que ameaçou tanto Roma quanto Constantinopla, mas ruiu logo após a morte de seu líder." }],
  Avars: [{ from: 567, to: 822, text: "Os ávaros foram um povo nômade de origem centro-asiática que fundou um poderoso canato na planície da Panônia, na Europa central. Aliados e rivais de Bizâncio, dominaram povos eslavos vizinhos por mais de dois séculos, até serem esmagados pelas campanhas de Carlos Magno." }],
  Khazars: [{ from: 650, to: 969, text: "Os cazares construíram um extenso canato entre o mar Cáspio e o mar Negro, controlando rotas comerciais entre a Europa, a Ásia e o mundo islâmico. Célebres pela conversão de sua elite ao judaísmo, serviram de barreira à expansão árabe rumo ao norte, até serem derrotados pela Rus de Kiev." }],
  "Kievan Rus": [{ from: 882, to: 1240, text: "A Rus de Kiev foi uma federação de tribos eslavas orientais liderada por príncipes varegues, consolidada em torno de Kiev a partir do fim do século IX. Sob Vladimir I e Iaroslav, o Sábio, adotou o cristianismo ortodoxo em 988 e floresceu cultural e comercialmente. Fragmentada por disputas dinásticas, foi destruída pela invasão mongol em 1240." }],
  "Russian Empire": [{ from: 1721, to: 1917, text: "O Império Russo foi proclamado em 1721 por Pedro, o Grande, após vitórias na Grande Guerra do Norte, iniciando uma era de modernização e expansão. Sob czares como Catarina, a Grande, tornou-se uma das maiores potências da Europa, estendendo-se da Polônia ao Pacífico. Marcado por autocracia e servidão, ruiu em 1917 com a Revolução Russa e a abdicação de Nicolau II." }],
  USSR: [{ from: 1922, to: 1991, text: "A União Soviética foi fundada em 1922 após a Revolução Bolchevique e a guerra civil, estabelecendo o primeiro Estado socialista sob o Partido Comunista. Industrializou-se rapidamente sob Stalin, teve papel decisivo na derrota do nazismo e emergiu como superpotência durante a Guerra Fria. Reformas e tensões internas levaram à sua dissolução em 1991." }],
  Portugal: [
    { from: 1139, to: 1415, text: "Portugal surgiu como reino independente quando Afonso Henriques afirmou sua soberania e avançou na Reconquista contra os muçulmanos. Ao longo dos séculos seguintes, consolidou suas fronteiras, praticamente definitivas já no século XIII, e firmou alianças duradouras, como a que manteve com a Inglaterra." },
    { from: 1415, to: 1822, text: "Com a tomada de Ceuta e as viagens de exploração patrocinadas pelo Infante Dom Henrique, Portugal inaugurou a era dos Descobrimentos. Construiu um vasto império marítimo e comercial que se estendia do Brasil à Índia e à China, tornando-se pioneiro da expansão europeia ultramarina." },
    { from: 1822, to: 2000, text: "Com a independência do Brasil e as revoluções liberais, Portugal entrou na era moderna em meio a instabilidade política. Passou pela monarquia constitucional, pela Primeira República, pela longa ditadura do Estado Novo e, após a Revolução dos Cravos de 1974, consolidou-se como democracia europeia." },
  ],
  Castile: [
    { from: 1065, to: 1230, text: "Castela emergiu como reino no centro-norte da Península Ibérica, protagonizando a Reconquista contra os reinos muçulmanos do sul. Suas conquistas e o vigor de figuras como o Cid marcaram sua ascensão, culminando na união definitiva com o vizinho reino de León." },
    { from: 1230, to: 1516, text: "Unida a León, a Coroa de Castela tornou-se a maior potência ibérica, avançando pela Andaluzia e desenvolvendo instituições como as Cortes. O casamento de Isabel I com Fernando de Aragão uniu as duas coroas, lançando as bases da monarquia espanhola e patrocinando a viagem de Colombo." },
  ],
  "Aragón": [{ from: 1035, to: 1516, text: "O Reino de Aragão, no nordeste da Península Ibérica, expandiu-se ao unir-se ao condado de Barcelona, formando a Coroa de Aragão. Tornou-se uma potência mediterrânea, dominando Valência, Baleares, Sardenha, Sicília e Nápoles, até a união dinástica com Castela sob os Reis Católicos." }],
  France: [
    { from: 843, to: 1453, text: "Nascida da partilha do Império Carolíngio, a França medieval foi governada pela dinastia capetiana, que gradualmente ampliou o poder real sobre os grandes senhores feudais. O período foi marcado pela consolidação territorial e pela longa Guerra dos Cem Anos contra a Inglaterra, na qual Joana d'Arc se tornou símbolo nacional." },
    { from: 1453, to: 1789, text: "Sob dinastias como Valois e Bourbon, a França caminhou para a monarquia absolutista, cujo ápice foi o reinado de Luís XIV em Versalhes. Tornou-se potência dominante na Europa, apesar das guerras religiosas e das crescentes tensões sociais e financeiras que antecederam a Revolução." },
    { from: 1789, to: 2000, text: "A Revolução Francesa de 1789 derrubou o Antigo Regime e difundiu os ideais de liberdade, igualdade e fraternidade por todo o continente. Após o império napoleônico, a França alternou monarquias, repúblicas e impérios, atravessou duas guerras mundiais e afirmou-se como república democrática e pilar da integração europeia." },
  ],
  England: [
    { from: 927, to: 1485, text: "Unificada por volta do século X sob os reis de Wessex, a Inglaterra medieval foi moldada pela conquista normanda de 1066 e pela gradual formação de instituições como o Parlamento e a Magna Carta. O período foi marcado por guerras dinásticas, incluindo a Guerra dos Cem Anos contra a França e a Guerra das Rosas entre casas nobres rivais." },
    { from: 1485, to: 1707, text: "Sob as dinastias Tudor e Stuart, a Inglaterra consolidou o poder monárquico, rompeu com Roma na Reforma e iniciou sua expansão marítima e colonial. Foi um período de intensa efervescência cultural e de conflitos religiosos e constitucionais que culminaram na Guerra Civil e na Revolução Gloriosa." },
    { from: 1707, to: 1900, text: "Com a união com a Escócia em 1707, a Inglaterra tornou-se o núcleo da Grã-Bretanha e de um vasto império global. Berço da Revolução Industrial, transformou-se em potência econômica e naval dominante ao longo dos séculos XVIII e XIX." },
  ],
  "Poland-Lithuania": [{ from: 1569, to: 1795, text: "A União de Lublin de 1569 fundiu o Reino da Polônia e o Grão-Ducado da Lituânia em uma vasta comunidade política conhecida como a República das Duas Nações. Notável por sua monarquia eletiva e pela nobreza politicamente poderosa, foi um dos maiores Estados da Europa antes de ser dividida entre potências vizinhas no fim do século XVIII." }],
  Sweden: [
    { from: 1000, to: 1523, text: "Emergindo da era viking, a Suécia medieval consolidou-se gradualmente como reino cristão e ingressou na União de Kalmar com a Dinamarca e a Noruega em 1397. Tensões com o domínio dinamarquês marcaram os séculos seguintes." },
    { from: 1523, to: 1721, text: "Sob Gustavo Vasa, a Suécia rompeu com a União de Kalmar e afirmou sua independência, adotando a Reforma Protestante. No século XVII tornou-se uma grande potência do Báltico, com forte atuação na Guerra dos Trinta Anos." },
    { from: 1721, to: 1900, text: "Após o declínio de seu império báltico na Grande Guerra do Norte, a Suécia perdeu influência militar mas desenvolveu instituições parlamentares e reformas internas. Uniu-se à Noruega em 1814 e manteve uma política de neutralidade ao longo do século XIX." },
  ],
  "Kalmar Union": [{ from: 1397, to: 1523, text: "Formada em 1397, a União de Kalmar reuniu sob uma única monarquia os reinos da Dinamarca, da Suécia e da Noruega. Apesar de unir a Escandinávia por mais de um século, foi marcada por tensões internas e pela resistência sueca ao domínio dinamarquês, dissolvendo-se com a ascensão de Gustavo Vasa." }],
  Prussia: [
    { from: 1525, to: 1701, text: "Surgida da secularização do Estado da Ordem Teutônica, a Prússia começou como ducado ligado ao Brandemburgo sob a dinastia Hohenzollern. Ao longo do século XVII consolidou seus territórios dispersos e fortaleceu o poder centralizado." },
    { from: 1701, to: 1871, text: "Elevada a reino em 1701, a Prússia tornou-se uma grande potência militar europeia sob Frederico, o Grande. Sua disciplina administrativa e força militar fizeram dela o Estado que lideraria a unificação da Alemanha em 1871." },
  ],
  Austria: [
    { from: 1156, to: 1526, text: "Estabelecida como ducado em 1156, a Áustria tornou-se o centro do poder da dinastia Habsburgo a partir do século XIII. Sua posição estratégica no coração da Europa Central fez dela um núcleo político e dinástico de crescente importância." },
    { from: 1526, to: 1804, text: "Sob os Habsburgos, a Áustria reuniu vastos territórios e assumiu papel central no Sacro Império Romano-Germânico. Defendeu a Europa Central contra a expansão otomana e tornou-se baluarte da Contrarreforma católica." },
    { from: 1804, to: 1918, text: "Proclamada Império Austríaco em 1804 e reorganizada como Áustria-Hungria em 1867, tornou-se um Estado multinacional que abrigava numerosos povos. As tensões nacionalistas internas contribuíram para seu colapso ao fim da Primeira Guerra Mundial." },
  ],
  "Austro-Hungarian Empire": [{ from: 1867, to: 1918, text: "Criado pelo Compromisso de 1867, o Império Austro-Húngaro foi uma monarquia dual que unia a Áustria e a Hungria sob o soberano Habsburgo. Vasto e multiétnico, enfrentou crescentes tensões nacionalistas e desintegrou-se ao término da Primeira Guerra Mundial." }],
  Pergamon: [{ from: -281, to: -133, text: "O Reino de Pérgamo, na Anatólia ocidental, ascendeu sob a dinastia atálida após a fragmentação do império de Alexandre. Famoso por sua monumental biblioteca, seu altar de Zeus e o mecenato às artes, foi legado a Roma pelo último rei, Átalo III." }],
  "Odrysian Kingdom": [{ from: -480, to: -46, text: "O Reino Odrísio foi a mais poderosa entidade política dos trácios, unificando tribos nos Bálcãs orientais. Prosperou pelo comércio e pela metalurgia, oscilando entre a independência e a submissão a persas, macedônios e, por fim, a Roma." }],

  // === Africa ===
  Kush: [{ from: -1070, to: -300, text: "O Reino de Cuxe emergiu na Núbia, ao sul do Egito, tornando-se uma potência que chegou a conquistar o próprio Egito e a governá-lo como a XXV dinastia. Centrado inicialmente em Napata, absorveu e adaptou tradições egípcias, incluindo a construção de pirâmides e o culto a Amón. Posteriormente transferiu seu centro para Meroé, prolongando a civilização núbia por séculos." }],
  Meroe: [{ from: -300, to: 350, text: "Meroé foi a capital do reino de Cuxe em seu período tardio, situada na atual Sudão, ao sul do Egito. Tornou-se um importante centro de produção de ferro e comércio, com pirâmides próprias e uma escrita meroítica ainda pouco decifrada. O reino declinou por volta do século IV, sofrendo pressão de Axum." }],
  Axum: [{ from: 100, to: 940, text: "O Reino de Axum foi uma potência comercial no norte da atual Etiópia e Eritreia, conectando África, Arábia e o mundo mediterrâneo pelo mar Vermelho. Cunhou sua própria moeda, ergueu grandes estelas e adotou o cristianismo no século IV sob o rei Ezana. Declinou a partir do século VII com a ascensão do comércio islâmico e mudanças ambientais." }],
  Numidia: [{ from: -202, to: -46, text: "A Numídia foi um reino berbere no norte da África, correspondente a partes da atual Argélia, unificado por Masinissa como aliado de Roma contra Cartago. Após um período de prosperidade e conflitos internos, foi anexada pela República Romana como província no rescaldo das guerras civis." }],
  Nobatia: [{ from: 350, to: 650, text: "Nobátia foi o mais setentrional dos reinos cristãos núbios, estabelecido após a queda de Méroe entre a primeira e a terceira catarata do Nilo. Cristianizada no século VI, acabou incorporada ao reino vizinho de Makúria, com o qual passou a formar uma única entidade política." }],
  Makkura: [{ from: 340, to: 1317, text: "Makúria foi um dos reinos cristãos da Núbia medieval, situado no vale do Nilo, com capital em Dongola. Convertida ao cristianismo no século VI, resistiu por séculos à expansão islâmica graças a um pacto com o Egito, antes de declinar sob pressão árabe e mameluca." }],
  Alwa: [{ from: 500, to: 1504, text: "Álua (Alódia) foi o mais meridional dos três reinos cristãos da Núbia, com capital em Soba, próxima à atual Cartum. Rica e populosa segundo relatos medievais, manteve o cristianismo por quase um milênio até sucumbir à migração árabe e ao avanço do sultanato de Sennar." }],
  Ethiopia: [
    { from: -100, to: 940, text: "Na Antiguidade, a região da Etiópia foi dominada pelo poderoso Reino de Axum, uma potência comercial e uma das primeiras a adotar o cristianismo. Ligava a África ao mundo mediterrâneo e árabe por meio do mar Vermelho, cunhando moeda e erguendo monumentos. Seu declínio abriu caminho para os reinos cristãos medievais do planalto etíope." },
    { from: 1137, to: 1974, text: "A Etiópia medieval e moderna consolidou-se sob dinastias cristãs como a Zagué, construtora das igrejas rupestres de Lalibela, e a Salomônica, que reivindicava descendência do rei Salomão. Resistiu de forma singular à colonização europeia, derrotando a Itália em Adwa em 1896. A milenar monarquia terminou em 1974 com a deposição do imperador Hailé Selassié." },
  ],
  "Empire of Ghana": [{ from: 300, to: 1240, text: "O Império de Gana, também chamado Wagadu, foi um dos primeiros grandes Estados da África Ocidental, situado entre os atuais Mali e Mauritânia. Enriqueceu controlando o comércio transsaariano de ouro e sal, tornando-se lendário por sua prosperidade. Enfraquecido por conflitos e pela seca, foi absorvido pelo emergente Império do Mali no século XIII." }],
  Mali: [{ from: 1235, to: 1670, text: "O Império do Mali foi fundado por Sundiata Keita por volta de 1235 e tornou-se a potência dominante da África Ocidental. Sob Mansa Musa, célebre por sua fabulosa riqueza em ouro, o império controlou o comércio transsaariano e fez de Timbuktu um centro de aprendizado islâmico. Declinou a partir do século XV diante de revoltas e da ascensão de Songhai." }],
  Songhai: [{ from: 1464, to: 1591, text: "O Império Songhai foi o maior dos impérios da África Ocidental, dominando a curva do rio Níger a partir de meados do século XV sob Sonni Ali e Askia Muhammad. Controlou o comércio transsaariano de ouro e sal e transformou Gao e Timbuktu em centros de riqueza e erudição islâmica. Foi derrotado por uma invasão marroquina armada com pólvora em 1591." }],
  Kanem: [{ from: 700, to: 1380, text: "Império situado a nordeste do lago Chade, Kanem ergueu-se sobre o comércio transaariano de sal, cobre e escravizados. Sob a dinastia Sefawa adotou o islã no século XI, antes de transferir seu núcleo de poder para Bornu diante de pressões internas e externas." }],
  "Bornu-Kanem": [{ from: 1380, to: 1893, text: "Após o deslocamento do centro de poder do antigo Kanem para a região de Bornu, o império Kanem-Bornu renasceu a oeste do lago Chade sob a dinastia Sefawa. Islâmico e mercantil, controlou as rotas transaarianas por séculos, atingindo seu apogeu sob Idris Alooma no fim do século XVI." }],
  Oyo: [{ from: 1400, to: 1836, text: "Poderoso reino iorubá no atual sudoeste da Nigéria, Oyo destacou-se por sua eficiente cavalaria e por uma estrutura política que limitava o poder do rei, o Alafin, por meio de conselhos. Prosperou com o comércio, incluindo o tráfico atlântico, antes de entrar em declínio no início do século XIX." }],
  Benin: [{ from: 1180, to: 1897, text: "O Reino de Benin, do povo edo, floresceu no atual sul da Nigéria e ficou célebre por sua corte sofisticada e por suas notáveis placas e esculturas de bronze e marfim. Estado centralizado e militarmente forte, manteve intenso comércio com europeus até ser destruído por uma expedição britânica em 1897." }],
  Dahomey: [{ from: 1600, to: 1904, text: "Reino do povo fon no atual Benim, Daomé caracterizou-se por um Estado altamente centralizado e militarizado, célebre por seu corpo de guerreiras conhecidas como as amazonas. Sua economia esteve fortemente ligada ao tráfico atlântico de escravizados antes da conquista francesa no início do século XX." }],
  Asante: [{ from: 1701, to: 1901, text: "Confederação do povo akan no atual Gana, o Império Asante foi fundado em torno do símbolo unificador do Banco de Ouro. Enriqueceu com o comércio de ouro e a expansão militar, resistindo por décadas à colonização britânica antes de ser anexado no início do século XX." }],
  "Sokoto Caliphate": [{ from: 1804, to: 1903, text: "O Califado de Sokoto foi um vasto Estado islâmico da África Ocidental, fundado por Usman dan Fodio após uma jihad de renovação religiosa. Tornou-se um dos maiores impérios da região, com forte organização política e intelectual, até ser conquistado pelos britânicos." }],
  Buganda: [{ from: 1300, to: 1900, text: "Reino situado às margens do lago Vitória, no atual Uganda, Buganda desenvolveu uma administração centralizada sob o soberano conhecido como Kabaka. Tornou-se um dos Estados mais poderosos da região dos Grandes Lagos africanos antes de integrar-se ao protetorado britânico." }],
  Congo: [{ from: 1390, to: 1857, text: "O Reino do Congo (Kongo) foi um poderoso Estado da África Centro-Ocidental, na região do atual norte de Angola e da República Democrática do Congo. Seus reis converteram-se ao cristianismo após o contato com Portugal no fim do século XV, e o reino foi profundamente afetado pelo comércio e pelo tráfico atlântico de escravizados." }],
  Ndongo: [{ from: 1500, to: 1671, text: "Reino do povo mbundu situado no atual Angola, Ndongo era governado por um soberano chamado Ngola, termo que originou o nome do país. Notabilizou-se pela resistência à expansão portuguesa, sobretudo sob a liderança da rainha Nzinga, antes de sucumbir ao domínio colonial." }],
  Mwenemutapa: [{ from: 1430, to: 1760, text: "O Reino do Monomotapa (Mwenemutapa) estendeu-se pelo planalto entre os rios Zambeze e Limpopo, no atual Zimbábue e Moçambique. Herdeiro da tradição do Grande Zimbábue, prosperou com o comércio de ouro e marfim com mercadores swahili e portugueses antes de fragmentar-se." }],
  "Great Zimbabwe": [{ from: 1100, to: 1450, text: "Grande Zimbábue foi a capital de um próspero reino da África Austral, célebre por suas imponentes muralhas de pedra erguidas sem argamassa. Prosperou entre os séculos XII e XV graças à criação de gado e ao comércio de ouro e marfim com a costa do Índico. A cidade foi gradualmente abandonada, possivelmente devido ao esgotamento de recursos e a mudanças nas rotas comerciais." }],
  Zulu: [{ from: 1816, to: 1897, text: "O Reino Zulu emergiu no sudeste da África sob a liderança de Shaka, que unificou clãs de língua nguni e reorganizou o exército com táticas e armas inovadoras. No auge, tornou-se uma potência militar regional, resistindo à expansão colonial até a Guerra Anglo-Zulu de 1879, quando foi por fim incorporado ao domínio britânico." }],
  "Almohad Caliphate": [{ from: 1121, to: 1269, text: "O Califado Almóada foi um império berbere reformista que dominou o noroeste da África e a Península Ibérica muçulmana. Impôs uma interpretação rigorosa do islã e legou obras notáveis, mas ruiu após a derrota de Las Navas de Tolosa." }],
  "Almoravid dynasty": [{ from: 1040, to: 1147, text: "A dinastia Almorávida foi um movimento berbere que unificou o Magrebe e o Alandalus sob uma vertente austera do islã. Deteve o avanço cristão na Ibéria por um tempo antes de ser suplantada pelos almóadas." }],
  "Hafsid Caliphate": [{ from: 1229, to: 1574, text: "O Califado Háfsida governou a Ifríquia, correspondente à atual Tunísia e regiões vizinhas, a partir de Túnis. Prosperou com o comércio mediterrâneo e o corso, mantendo-se até ser absorvido pelo Império Otomano." }],

  // === East / Southeast Asia ===
  Korea: [
    { from: -2333, to: 668, text: "A tradição situa nas origens da Coreia o reino lendário de Gojoseon, seguido pelo período dos Três Reinos, quando Goguryeo, Baekje e Silla disputaram a península. Foi uma era de formação da cultura coreana, com forte influência budista e chinesa e intensa rivalidade militar entre os reinos." },
    { from: 668, to: 1392, text: "Após a unificação promovida por Silla e, depois, pela dinastia Goryeo, a Coreia consolidou-se como um Estado centralizado e budista. Floresceram as artes, a impressão com tipos móveis e a cerâmica celadon, apesar das invasões mongóis que marcaram os séculos finais desse período." },
    { from: 1392, to: 1948, text: "A dinastia Joseon adotou o confucionismo como ideologia de Estado e criou o alfabeto hangul, moldando a identidade coreana moderna. O reino sofreu invasões e, no início do século XX, foi colonizado pelo Japão, até a libertação e a divisão da península após 1945." },
  ],
  Goryeo: [{ from: 918, to: 1392, text: "Fundada por Wang Geon, a dinastia Goryeo reunificou a península coreana e deu origem ao nome ocidental \"Coreia\". Notabilizou-se pela cerâmica celadon, pela impressão em tipos móveis metálicos e pelo budismo de Estado, resistindo a repetidas invasões mongóis que a tornaram vassala do império de Kublai Khan." }],
  Silla: [{ from: -57, to: 935, text: "Um dos Três Reinos da Coreia, Silla expandiu-se a partir do sudeste da península e, aliada à China Tang, derrotou Baekje e Goguryeo, unificando grande parte da Coreia em 668. A chamada Silla Unificada viveu um apogeu cultural budista antes de declinar em meio a revoltas aristocráticas." }],
  Balhae: [{ from: 698, to: 926, text: "Balhae foi um reino multiétnico que se estendeu pela Manchúria, pelo norte da Coreia e por partes do Extremo Oriente russo, fundado por remanescentes de Goguryeo. Chamado de \"país próspero do leste\", combinou influências coreanas e chinesas antes de ser destruído pelos quitanes." }],
  Japan: [
    { from: -660, to: 1185, text: "Nas eras antiga e clássica, o Japão emergiu de sociedades como a Yayoi e desenvolveu-se sob a corte imperial de Yamato, que consolidou o poder e adotou influências chinesas e coreanas. Nara e depois Heian tornaram-se centros de uma refinada cultura aristocrática, budista e literária. Esse período lançou as bases da identidade cultural, religiosa e política japonesa." },
    { from: 1185, to: 1868, text: "Durante a era feudal, o poder real deslocou-se do imperador para os xoguns e a classe guerreira samurai, iniciando-se com o xogunato Kamakura. Séculos de guerras civis foram seguidos pela unificação e por um longo período de paz e isolamento sob o xogunato Tokugawa. Uma sociedade rigidamente hierárquica floresceu culturalmente enquanto o país permanecia fechado ao exterior." },
    { from: 1868, to: 2024, text: "A partir da Restauração Meiji, em 1868, o Japão modernizou-se rapidamente, industrializando-se e tornando-se uma potência mundial. Após a expansão imperialista e a derrota na Segunda Guerra Mundial, reconstruiu-se como uma democracia pacífica e uma das maiores economias do planeta. Combina hoje tradição milenar com liderança tecnológica global." },
  ],
  Yamato: [{ from: 250, to: 710, text: "O período Yamato marca a formação do Estado japonês antigo em torno da região de Nara, sob uma linhagem imperial em consolidação. Foi uma era de crescente influência chinesa e coreana, com a introdução do budismo e de modelos administrativos continentais." }],
  "Empire of Japan": [{ from: 1868, to: 1947, text: "O Império do Japão nasceu com a Restauração Meiji de 1868, que restaurou o poder imperial e impulsionou rápida modernização e industrialização. Movido por ambições expansionistas, anexou territórios na Ásia e no Pacífico, culminando em sua participação na Segunda Guerra Mundial. A derrota em 1945 pôs fim ao império militarista, seguido por uma nova constituição pacifista em 1947." }],
  "Tokugawa Shogunate": [{ from: 1603, to: 1868, text: "O Xogunato Tokugawa foi estabelecido por Tokugawa Ieyasu em 1603, inaugurando mais de dois séculos de paz e estabilidade conhecidos como período Edo. Adotou uma política de isolamento (sakoku), restringindo severamente o contato com o exterior, enquanto sustentava uma rígida ordem social. Enfraquecido por pressões internas e externas, entregou o poder ao imperador em 1868, encerrando a era feudal." }],
  "Khmer Empire": [{ from: 802, to: 1431, text: "O Império Khmer dominou grande parte do Sudeste Asiático continental a partir de 802, com seu centro na região de Angkor, no atual Camboja. Construiu vastos complexos de templos, como Angkor Wat, e desenvolveu engenhosos sistemas hidráulicos que sustentavam uma população numerosa. Após séculos de esplendor, enfraqueceu diante de pressões regionais e do reino de Ayutthaya, abandonando Angkor em 1431." }],
  "Srivijaya Empire": [{ from: 650, to: 1288, text: "Srivijaya foi um poderoso império marítimo budista centrado em Sumatra, que controlou rotas comerciais estratégicas pelos estreitos de Malaca e Sunda. Prosperou como centro de aprendizado budista e polo do comércio entre a Índia e a China. Seu domínio declinou a partir do século XI diante de rivais como Chola e reinos javaneses." }],
  Champa: [{ from: 192, to: 1832, text: "Champa foi um conjunto de principados hinduístas e depois islamizados do povo cham, ao longo da costa do atual Vietnã central. Prosperou com o comércio marítimo e deixou notável arquitetura em tijolo, mas foi gradualmente absorvido pela expansão vietnamita rumo ao sul." }],
  Funan: [{ from: 68, to: 550, text: "Funan foi um dos mais antigos Estados do Sudeste Asiático, situado no delta do Mekong. Enriquecido pelo comércio entre a Índia e a China, adotou influências indianas na religião e na administração antes de declinar diante do reino sucessor de Chenla." }],
  Dvaravati: [{ from: 550, to: 1100, text: "Dvaravati foi uma cultura mon de orientação budista que floresceu na bacia do rio Chao Phraya, na atual Tailândia. Notável pela arte e pela difusão do budismo Theravada, foi mais uma rede de cidades-Estado do que um império centralizado." }],
  Mataram: [{ from: 716, to: 1016, text: "O Reino de Mataram, em Java central, foi um poderoso Estado hindu-budista responsável por monumentos como Borobudur e Prambanan. A rivalidade entre as dinastias Sailendra e Sanjaya marcou sua história antes de o poder deslocar-se para o leste de Java." }],
  Ayutthaya: [{ from: 1351, to: 1767, text: "O Reino de Ayutthaya foi um poderoso Estado siamês que dominou boa parte do atual território tailandês. Rico centro de comércio internacional e refinada cultura budista, foi destruído por um exército birmanês em 1767." }],
  Sukhothai: [{ from: 1238, to: 1438, text: "Sukhothai é considerado o primeiro reino tailandês, celebrado como uma era de ouro da cultura e da identidade siamesa. Sob o rei Ramkhamhaeng, teria surgido a escrita tailandesa; mais tarde foi absorvido pelo crescente reino de Ayutthaya." }],

  // === The Americas ===
  Olmec: [{ from: -1200, to: -400, text: "Considerada a cultura-mãe da Mesoamérica, a civilização olmeca floresceu nas terras baixas tropicais do golfo do atual México. É famosa pelas colossais cabeças esculpidas em pedra e por lançar bases culturais, religiosas e artísticas herdadas por civilizações posteriores." }],
  "Zapotec Empire": [{ from: -500, to: 900, text: "A civilização zapoteca floresceu no vale de Oaxaca, no México, tendo Monte Albán como seu grande centro urbano a partir de cerca de 500 a.C. Os zapotecas desenvolveram um dos primeiros sistemas de escrita da Mesoamérica, além de calendários e monumentais construções. Monte Albán declinou por volta do ano 900, embora cidades zapotecas persistissem até a chegada dos espanhóis." }],
  "Teotihuacán": [{ from: -100, to: 650, text: "Grande metrópole do centro do atual México, Teotihuacán foi uma das maiores cidades do mundo antigo, com suas imponentes Pirâmides do Sol e da Lua e a ampla Avenida dos Mortos. Exerceu profunda influência comercial e cultural sobre a Mesoamérica antes de seu misterioso declínio." }],
  "Maya chiefdoms and states": [{ from: -2000, to: 250, text: "Nas eras Pré-Clássica, as comunidades maias evoluíram de aldeias agrícolas para cacicados e estados incipientes ao longo de milênios. Surgiram centros como El Mirador e Nakbé, com arquitetura monumental precoce e as bases da escrita e do calendário. Esse longo desenvolvimento preparou o terreno para o esplendor das cidades-estado do período Clássico." }],
  "Maya city-states": [{ from: 250, to: 900, text: "Durante o período Clássico, as cidades-estado maias, como Tikal, Palenque e Calakmul, floresceram nas terras baixas da América Central. Cada cidade era governada por dinastias reais que competiam por prestígio e poder, deixando avanços notáveis em escrita, astronomia e matemática. Um colapso generalizado no século IX levou ao abandono de muitos desses centros nas terras baixas do sul." }],
  "Toltec Empire": [{ from: 900, to: 1168, text: "Os toltecas dominaram o centro do México a partir de sua capital Tula por volta do século X, sucedendo Teotihuacan como potência regional. Reverenciados por civilizações posteriores, como os astecas, tornaram-se sinônimo de refinamento artístico e sabedoria, associados à figura de Quetzalcóatl. Seu domínio ruiu no século XII em meio a conflitos e pressões de povos do norte." }],
  "Aztec Empire": [{ from: 1428, to: 1521, text: "O Império Asteca, ou Tríplice Aliança, dominou o centro do México a partir de 1428, com Tenochtitlan como capital em uma ilha do lago Texcoco. Desenvolveu uma sociedade complexa marcada por tributos, comércio, religião e sacrifícios rituais. Foi conquistado por Hernán Cortés e seus aliados indígenas em 1521, marcando o fim da era pré-colombiana no México central." }],
  Moche: [{ from: 100, to: 700, text: "Cultura que floresceu na costa norte do atual Peru, os moches destacaram-se pela cerâmica realista, pela metalurgia e pela construção de grandes pirâmides de adobe, como as Huacas do Sol e da Lua. Sua sociedade era organizada em torno de senhores guerreiros e de complexos rituais religiosos." }],
  Nazca: [{ from: -100, to: 800, text: "Desenvolvida na costa sul do atual Peru, a cultura Nazca é célebre pelas enigmáticas geoglifos traçadas no deserto, as Linhas de Nazca. Dominava técnicas avançadas de irrigação subterrânea e produziu cerâmica e tecidos de grande refinamento." }],
  "Tiahuanaco Empire": [{ from: 500, to: 1000, text: "Centrado nas margens do lago Titicaca, no altiplano andino, o Estado de Tiwanaku foi um importante centro religioso e político. Sua monumental arquitetura de pedra, como a Porta do Sol, e sua influência cultural irradiaram-se por vasta região dos Andes centro-sul." }],
  "Huari Empire": [{ from: 600, to: 1000, text: "O Império Wari expandiu-se pelos Andes centrais do atual Peru a partir de sua capital homônima, criando uma das primeiras grandes organizações estatais da região. Notabilizou-se pela construção de centros administrativos, extensas redes de estradas e sistemas de terraços agrícolas." }],
  "Chimú Empire": [{ from: 900, to: 1470, text: "Desenvolvido na costa norte do atual Peru, o Império Chimú teve como capital a monumental cidade de barro de Chan Chan. Foi a maior civilização andina antes dos incas, destacando-se pela engenharia hidráulica e pela fina metalurgia, até ser conquistado pelo Império Inca." }],
  "Inca Empire": [{ from: 1438, to: 1533, text: "O Império Inca, chamado Tawantinsuyu, foi o maior império da América pré-colombiana, estendendo-se pelos Andes a partir de 1438. Notável por sua engenharia, terraços agrícolas, estradas e administração centralizada em Cusco, integrou diversos povos sob o domínio do Sapa Inca. Enfraquecido por guerra civil e epidemias, foi conquistado por Francisco Pizarro em 1533." }],

  // === Modern nation-states (shown in recent snapshots) ===
  China: [{ from: 1912, to: 2025, text: "A China moderna emergiu com o fim do império em 1912 e a proclamação da República. Após décadas de guerra civil, invasão japonesa e a vitória comunista de 1949, a República Popular da China tornou-se, sobretudo a partir das reformas econômicas de 1978, uma superpotência e a nação mais populosa do mundo, herdeira de uma das mais antigas civilizações da história." }],
  India: [{ from: 1947, to: 2025, text: "A Índia moderna nasceu como nação independente em 1947, após séculos de domínio britânico e o movimento liderado por Mahatma Gandhi. Tornou-se a maior democracia do mundo e, no século XXI, uma das nações mais populosas e uma economia de crescente peso global, marcada por enorme diversidade cultural, linguística e religiosa." }],
  "United States": [{ from: 1776, to: 2025, text: "Os Estados Unidos surgiram da independência das treze colônias britânicas em 1776 e expandiram-se por todo o continente norte-americano ao longo do século XIX. Após a Guerra Civil, a industrialização e duas guerras mundiais, tornaram-se a principal potência econômica e militar do mundo e um centro de inovação tecnológica e cultural." }],
  "United States of America": [{ from: 1776, to: 2025, text: "Os Estados Unidos da América formaram-se com a independência de 1776 e cresceram de uma república agrária a superpotência global. Sua história inclui a expansão para o oeste, a Guerra Civil e a abolição da escravidão, a ascensão industrial e a liderança econômica, militar e cultural consolidada no século XX." }],
  Brazil: [{ from: 1822, to: 2025, text: "O Brasil tornou-se independente de Portugal em 1822, primeiro como império e, a partir de 1889, como república. Maior país da América do Sul e herdeiro de uma formação marcada por povos indígenas, colonização portuguesa e a diáspora africana, consolidou-se como uma das maiores economias e democracias do mundo, célebre por sua diversidade cultural e natural." }],
  Mexico: [{ from: 1821, to: 2025, text: "O México conquistou a independência da Espanha em 1821, herdando um território que abrigara grandes civilizações como astecas e maias. Após revoluções, perdas territoriais e a Revolução Mexicana de 1910, firmou-se como uma república populosa e uma das principais economias da América Latina, com forte identidade cultural mestiça." }],
  Canada: [{ from: 1867, to: 2025, text: "O Canadá formou-se como confederação em 1867, reunindo colônias britânicas da América do Norte, e alcançou plena soberania ao longo do século XX. Segundo maior país do mundo em área, é uma democracia parlamentar bilíngue, próspera e multicultural, com vastos recursos naturais." }],
  Australia: [{ from: 1901, to: 2025, text: "A Austrália tornou-se uma federação em 1901, unindo as colônias britânicas do continente. Habitada por povos aborígenes há dezenas de milhares de anos antes da colonização europeia, desenvolveu-se como uma democracia estável e economia desenvolvida, ocupando sozinha um continente inteiro." }],
  Russia: [{ from: 1991, to: 2025, text: "A Federação Russa emergiu como Estado independente com a dissolução da União Soviética em 1991, herdeira do Império Russo e da URSS. Maior país do mundo em território, estendendo-se por dois continentes, mantém grande influência geopolítica, vastos recursos naturais e um papel central na política internacional." }],
  Germany: [{ from: 1871, to: 2025, text: "A Alemanha unificou-se como Estado-nação em 1871 sob a liderança da Prússia. Depois de protagonizar as duas guerras mundiais e de ser dividida durante a Guerra Fria, reunificou-se em 1990 e consolidou-se como a maior economia da Europa e um dos pilares da União Europeia." }],
  Italy: [{ from: 1861, to: 2025, text: "A Itália unificou-se como reino em 1861, reunindo os diversos Estados da península após séculos de fragmentação. Berço do Império Romano e do Renascimento, passou pelo período fascista e pelas guerras mundiais antes de tornar-se, em 1946, uma república democrática e uma das maiores economias europeias." }],
  Spain: [{ from: 1516, to: 2025, text: "A Espanha unificou-se sob os Reis Católicos e, no século XVI, construiu um vasto império global que se estendia pelas Américas, Ásia e Europa. Após a perda de suas colônias, a guerra civil e a ditadura de Franco, tornou-se, a partir de 1978, uma democracia parlamentar e um membro ativo da União Europeia." }],
  Denmark: [{ from: 936, to: 2025, text: "Unificada por volta do século X sob reis como Haroldo Dente-Azul, a Dinamarca tornou-se o centro do vasto império do Mar do Norte de Canuto, o Grande. Ao longo dos séculos formou uniões com a Noruega e a Suécia (União de Kalmar), consolidou-se como monarquia luterana após a Reforma e evoluiu para uma monarquia constitucional a partir de 1849. Hoje é um pequeno e próspero Estado nórdico, membro da União Europeia e uma das democracias mais estáveis do mundo." }],
  Norway: [{ from: 872, to: 2025, text: "Unificada tradicionalmente por Haroldo Cabelo Belo por volta de 872, a Noruega teve um vigoroso período viking antes de ser cristianizada e absorvida por uniões com a Dinamarca e depois a Suécia. Permaneceu sob domínio dano-norueguês até 1814 e unida à Suécia até 1905, quando conquistou plena independência. Enriquecida pelo petróleo do Mar do Norte no século XX, é hoje uma monarquia constitucional com um dos maiores padrões de vida do planeta." }],
  "Denmark-Norway": [{ from: 1524, to: 1814, text: "A união dano-norueguesa foi um Estado dinástico governado pelos reis da Dinamarca, que reunia a Dinamarca, a Noruega e territórios atlânticos como a Islândia, as Ilhas Faroé e a Groenlândia. Foi uma potência naval e comercial no Báltico e no Atlântico Norte, marcada por rivalidades com a Suécia. A união dissolveu-se em 1814 pelo Tratado de Kiel, quando a Noruega foi cedida à Suécia após as Guerras Napoleônicas." }],
  Hungary: [{ from: 1000, to: 2025, text: "O Reino da Hungria foi fundado por volta do ano 1000 com a coroação de Estêvão I, que cristianizou os magiares. Ao longo dos séculos enfrentou invasões mongóis e otomanas, integrou-se ao Império dos Habsburgos e formou a Áustria-Hungria até 1918. Após décadas sob regime comunista no bloco soviético, tornou-se uma república democrática em 1989 e hoje é membro da União Europeia." }],
  Novgorod: [{ from: 1136, to: 1478, text: "A República de Novgorod foi uma poderosa cidade-estado mercantil da Rus, governada por uma assembleia popular (veche) e por príncipes de poder limitado. Prosperou com o comércio de peles, cera e mel, ligando-se à Liga Hanseática e controlando vastos territórios no norte da Rússia. Sua independência terminou em 1478, quando foi anexada pelo Grão-Ducado de Moscou sob Ivã III." }],
  "Volga Bulgars": [{ from: 700, to: 1236, text: "O Estado dos Búlgaros do Volga floresceu na confluência dos rios Volga e Kama, no atual Tataristão, tornando-se um importante entreposto comercial entre a Europa e a Ásia. Adotou o Islã oficialmente no início do século X, sendo um dos primeiros Estados muçulmanos da região. Foi destruído pela invasão mongol em 1236, sendo incorporado à Horda Dourada." }],
  Greenland: [{ from: 985, to: 2025, text: "A Groenlândia foi colonizada por volta de 985 por nórdicos liderados por Erik, o Vermelho, cujos assentamentos duraram até o século XV antes de desaparecerem. Reintegrada ao domínio dinamarquês no século XVIII, tornou-se formalmente parte da Dinamarca. Hoje é um território autônomo do Reino da Dinamarca, habitado majoritariamente por inuítes e dotado de amplo autogoverno desde 2009." }],
  Netherlands: [{ from: 1581, to: 2025, text: "Os Países Baixos emergiram como república independente após a revolta contra o domínio espanhol dos Habsburgos, formalizada em 1581. No Século de Ouro tornaram-se uma potência marítima, comercial e colonial global, sede da Companhia das Índias Orientais. Após o período napoleônico transformaram-se em monarquia constitucional e são hoje um Estado próspero, membro fundador da União Europeia." }],
  Greece: [{ from: 1830, to: 2025, text: "A Grécia moderna nasceu da Guerra de Independência contra o Império Otomano, obtendo reconhecimento internacional em 1830 após séculos de domínio turco. Herdeira simbólica da civilização clássica e de Bizâncio, ampliou gradualmente seu território ao longo dos séculos XIX e XX. Após uma ditadura militar, restaurou a democracia em 1974 e ingressou na União Europeia, enfrentando grave crise da dívida nos anos 2010." }],
  Serbia: [{ from: 1217, to: 2025, text: "A Sérvia consolidou-se como reino medieval em 1217 sob a dinastia Nemânjida, atingindo seu apogeu com o Império de Estêvão Dušan no século XIV. Foi subjugada pelos otomanos após a Batalha de Kosovo (1389) e só recuperou plena independência no século XIX. Núcleo da Iugoslávia no século XX, tornou-se novamente um Estado independente em 2006, após a separação de Montenegro." }],
  Romania: [{ from: 1859, to: 2025, text: "A Romênia moderna formou-se em 1859 com a união dos principados da Valáquia e da Moldávia, conquistando plena independência do Império Otomano em 1878. Reino no início do século XX, expandiu-se após a Primeira Guerra Mundial com a incorporação da Transilvânia. Após décadas sob a ditadura comunista de Ceaușescu, derrubada em 1989, tornou-se uma república democrática e membro da União Europeia." }],
  Bulgaria: [{ from: 681, to: 2025, text: "O Primeiro Império Búlgaro foi fundado em 681 e converteu-se ao cristianismo ortodoxo no século IX, tornando-se um centro da cultura eslava. Após séculos de domínio bizantino e depois otomano, a Bulgária reconquistou a independência em 1878. Aliada da União Soviética durante a Guerra Fria, tornou-se uma república democrática após 1989 e ingressou na União Europeia em 2007." }],
  Ukraine: [{ from: 1991, to: 2025, text: "Herdeira histórica da Rus de Kiev medieval e do legado cossaco, a Ucrânia passou séculos sob domínio polonês, russo e soviético antes de proclamar sua independência em 1991 com o colapso da União Soviética. Enfrentou tensões entre orientações pró-ocidentais e pró-russas, culminando na Revolução de Maidan em 2014. Desde a invasão russa em grande escala de 2022, resiste em uma guerra devastadora por sua soberania." }],
  Finland: [{ from: 1809, to: 2025, text: "Durante séculos parte do Reino da Suécia, a Finlândia tornou-se um Grão-Ducado autônomo sob o Império Russo em 1809. Proclamou sua independência em 1917, em meio à Revolução Russa, e defendeu-a na Guerra de Inverno contra a União Soviética. Neutra durante a Guerra Fria, é hoje uma próspera república nórdica que ingressou na União Europeia em 1995 e na OTAN em 2023." }],
  Ireland: [{ from: 1922, to: 2025, text: "Após séculos de colonização e domínio britânico, marcados pela Grande Fome do século XIX e por lutas nacionalistas, a maior parte da Irlanda conquistou autonomia em 1922 com o Estado Livre Irlandês. Tornou-se plenamente república em 1949, permanecendo a Irlanda do Norte no Reino Unido. Membro da União Europeia desde 1973, transformou-se numa economia moderna e dinâmica." }],
  Scotland: [{ from: 843, to: 2025, text: "O Reino da Escócia consolidou-se por volta de 843 com a união dos pictos e escotos sob Kenneth MacAlpin, defendendo sua independência da Inglaterra em guerras lideradas por figuras como William Wallace e Robert Bruce. Uniu-se dinasticamente à Inglaterra em 1603 e formalmente no Reino da Grã-Bretanha em 1707. Hoje é uma nação constituinte do Reino Unido, com parlamento próprio desde 1999, onde persistem debates sobre a independência." }],
  Switzerland: [{ from: 1291, to: 2025, text: "A Confederação Suíça teve origem em 1291 com o pacto de aliança entre cantões alpinos contra o domínio dos Habsburgos. Consolidou sua neutralidade e independência ao longo dos séculos, reconhecida formalmente em 1648 pela Paz de Vestfália. Célebre por sua neutralidade permanente, democracia direta e prosperidade, é hoje uma federação multilíngue que permanece fora da União Europeia." }],
  Belgium: [{ from: 1830, to: 2025, text: "A Bélgica conquistou sua independência em 1830 ao separar-se do Reino Unido dos Países Baixos, tornando-se uma monarquia constitucional. Industrializou-se cedo e construiu um brutal império colonial no Congo. Palco de intensos combates nas duas guerras mundiais, é hoje um Estado federal dividido entre flamengos e valões, e sede das principais instituições da União Europeia e da OTAN em Bruxelas." }],
  Iceland: [{ from: 930, to: 2025, text: "Colonizada por nórdicos no século IX, a Islândia estabeleceu em 930 o Althing, considerado um dos parlamentos mais antigos do mundo. Passou ao domínio norueguês e depois dinamarquês por séculos, até proclamar sua independência plena em 1944. É hoje uma pequena e próspera república nórdica, conhecida por sua natureza vulcânica e por sua sociedade igualitária." }],
  Croatia: [{ from: 925, to: 2025, text: "O Reino da Croácia surgiu por volta de 925 sob o rei Tomislav, mas uniu-se à Hungria a partir de 1102 e mais tarde ao Império dos Habsburgos. Integrou a Iugoslávia durante o século XX, até declarar sua independência em 1991, o que desencadeou uma guerra sangrenta. Consolidada como república democrática, ingressou na União Europeia em 2013." }],

  // === South America / Central America (modern) + pre-Columbian ===
  Argentina: [{ from: 1816, to: 2025, text: "Antes da colonização, o território era habitado por povos como os diaguitas e guaranis, e as terras andinas chegaram a integrar o Império Inca. Após declarar sua independência da Espanha em 1816, a Argentina consolidou-se como república e recebeu grande imigração europeia nos séculos XIX e XX. Tornou-se uma das principais economias da América do Sul, marcada por ciclos de prosperidade agroexportadora, instabilidade política e retorno à democracia em 1983." }],
  Bolivia: [{ from: 1825, to: 2025, text: "A região abrigou a civilização de Tiwanaku e depois integrou o Império Inca, antes de tornar-se centro da mineração de prata colonial em Potosí. A Bolívia conquistou a independência em 1825, recebendo o nome em homenagem a Simón Bolívar. Ao longo de sua história perdeu territórios em guerras com vizinhos e mantém forte presença de povos indígenas quéchuas e aimarás." }],
  Colombia: [{ from: 1810, to: 2025, text: "Antes da chegada dos espanhóis, o território era habitado por povos como os muíscas, conhecidos por seu ouro e organização social. A Colômbia iniciou seu processo de independência em 1810 e integrou a Grã-Colômbia liderada por Simón Bolívar antes de tornar-se república autônoma. Sua história moderna combinou desenvolvimento econômico com longos períodos de conflito interno e esforços de pacificação." }],
  Venezuela: [{ from: 1811, to: 2025, text: "Habitada por povos caribenhos e aruaques antes da colonização, a região foi um importante ponto da colonização espanhola no Caribe. A Venezuela declarou independência em 1811 e foi berço de Simón Bolívar, líder da emancipação sul-americana. No século XX tornou-se grande produtora de petróleo, riqueza que moldou profundamente sua economia e política." }],
  Peru: [{ from: 1821, to: 2025, text: "O território foi o coração do Império Inca e antes abrigou culturas milenares como Chavín, Moche e Nazca, além de ter sido o centro do Vice-Reino do Peru colonial. O Peru proclamou sua independência em 1821, consolidada nas batalhas de Junín e Ayacucho. País de rica herança indígena e colonial, mantém o quéchua e o aimará entre suas línguas oficiais." }],
  Chile: [{ from: 1818, to: 2025, text: "Antes da colonização, o sul era habitado pelos mapuches, que resistiram longamente à conquista espanhola, enquanto o norte integrou o Império Inca. O Chile declarou sua independência em 1818, após a campanha libertadora de Bernardo O'Higgins e José de San Martín. Estendendo-se por uma longa faixa costeira, tornou-se importante produtor de cobre e viveu ciclos de democracia, ditadura e redemocratização no século XX." }],
  Ecuador: [{ from: 1822, to: 2025, text: "A região abrigou culturas antigas como a Valdivia e a Chorrera e depois integrou a porção norte do Império Inca, com Quito como centro importante. O Equador libertou-se do domínio espanhol em 1822 e separou-se da Grã-Colômbia em 1830, tornando-se república independente. Seu nome deriva da linha do equador, que cruza o país, e sua população mantém forte presença indígena andina e amazônica." }],
  Paraguay: [{ from: 1811, to: 2025, text: "Território tradicionalmente habitado pelos guaranis, cuja língua permanece oficial e amplamente falada, foi centro das missões jesuíticas na era colonial. O Paraguai conquistou a independência da Espanha em 1811, tornando-se uma das primeiras nações livres da região. Sua história foi marcada pela devastadora Guerra da Tríplice Aliança (1864-1870) e por longos períodos de governos autoritários no século XX." }],
  Uruguay: [{ from: 1825, to: 2025, text: "Habitado originalmente pelos charruas e outros povos, o território foi disputado por espanhóis e portugueses devido à sua posição estratégica no estuário do Prata. O Uruguai declarou independência em 1825 e consolidou-a em 1828, surgindo como estado-tampão entre Argentina e Brasil. No século XX destacou-se pela estabilidade democrática e por avançadas políticas sociais na região." }],
  Guyana: [{ from: 1966, to: 2025, text: "Habitada por povos aruaques e caribenhos, a região foi colonizada por holandeses e depois britânicos, que introduziram trabalhadores africanos e indianos nas plantações. A Guiana tornou-se independente do Reino Unido em 1966, sendo o único país sul-americano de língua oficial inglesa. Sua sociedade é marcada pela diversidade étnica e, mais recentemente, pela descoberta de importantes reservas de petróleo." }],
  Suriname: [{ from: 1975, to: 2025, text: "Originalmente habitado por povos indígenas amazônicos, o território foi colônia holandesa que dependeu do trabalho de africanos escravizados e depois de imigrantes asiáticos. O Suriname tornou-se independente dos Países Baixos em 1975, sendo o menor país da América do Sul. É o único da região onde o neerlandês é a língua oficial, refletindo uma sociedade multicultural." }],
  "Aymara kingdoms": [{ from: 1150, to: 1470, text: "Após o colapso da civilização de Tiwanaku, surgiram diversos senhorios aimarás na região do lago Titicaca, no altiplano andino. Reinos como os collas e lupacas dominaram o planalto, organizados em torno da pastorícia de camelídeos e do cultivo em terraços. Por volta de 1470 foram gradualmente conquistados e incorporados ao Império Inca." }],
  Chavin: [{ from: -900, to: -200, text: "A cultura Chavín de Huántar floresceu nos Andes centrais do Peru entre cerca de 900 e 200 a.C., sendo uma das mais antigas civilizações complexas da região. Seu principal centro cerimonial reunia templos de pedra e uma arte religiosa marcada por figuras felinas, serpentes e aves de rapina. Exerceu grande influência cultural e religiosa sobre vastas áreas dos Andes." }],
  Chorrera: [{ from: -1300, to: -300, text: "A cultura Chorrera desenvolveu-se no litoral e nas terras baixas do Equador entre cerca de 1300 e 300 a.C. Foi notável por sua cerâmica refinada, incluindo vasos em forma de animais e apitos, que revela grande domínio artístico. Sua influência estendeu-se por ampla área, ligando comunidades por redes de troca ao longo da costa." }],
  "Monte Albán": [{ from: -500, to: 850, text: "Monte Albán foi a grande capital da civilização zapoteca, erguida sobre um monte no vale de Oaxaca, no atual México. Fundada por volta de 500 a.C., tornou-se um poderoso centro político, religioso e urbano da Mesoamérica, com praças, templos e escrita hieroglífica. Entrou em declínio por volta de 850 d.C., sendo em grande parte abandonada." }],
  Cuba: [{ from: 1902, to: 2025, text: "Habitada pelos taínos antes da chegada de Colombo em 1492, Cuba tornou-se importante colônia espanhola baseada na produção de açúcar e no trabalho escravo. Conquistou a independência formal em 1902, após a guerra contra a Espanha e a intervenção dos Estados Unidos. A Revolução de 1959 liderada por Fidel Castro instaurou um regime socialista que marcou profundamente sua história contemporânea." }],
  Haiti: [{ from: 1804, to: 2025, text: "Colônia francesa conhecida como Saint-Domingue, foi uma das mais ricas do Caribe graças às plantações de açúcar movidas por africanos escravizados. Em 1804, o Haiti tornou-se a primeira república negra independente do mundo, após uma vitoriosa revolta de escravizados. Sua história posterior foi marcada por instabilidade política, dívidas impostas e desastres naturais." }],
  Nicaragua: [{ from: 1821, to: 2025, text: "Habitada por povos indígenas de tradições mesoamericanas e chibchas, a região foi colonizada pela Espanha a partir do século XVI. A Nicarágua tornou-se independente em 1821, integrando brevemente o México e depois as Províncias Unidas da América Central. Sua história moderna foi marcada por intervenções estrangeiras, pela ditadura dos Somoza e pela Revolução Sandinista de 1979." }],
  Panama: [{ from: 1821, to: 2025, text: "Habitada por povos indígenas como os cunas, a região foi ponto estratégico de passagem no Império Espanhol. O Panamá independizou-se da Espanha em 1821 unindo-se à Grã-Colômbia, e só se separou da Colômbia em 1903, com apoio dos Estados Unidos. A construção e o controle do Canal do Panamá, devolvido ao país em 1999, moldaram profundamente sua economia e identidade." }],
  Guatemala: [{ from: 1821, to: 2025, text: "Coração da civilização maia, cujas cidades floresceram por séculos, o território tornou-se sede da Capitania Geral da Guatemala durante o domínio espanhol. A Guatemala conquistou a independência em 1821 e depois integrou as Províncias Unidas da América Central antes de tornar-se república soberana. Mantém forte presença de povos indígenas maias e viveu um longo conflito armado interno no século XX." }],

  // === Africa (modern nations + peoples) ===
  Nigeria: [{ from: 1900, to: 2025, text: "Antes da colonização, a região abrigou reinos e impérios poderosos, como os Estados hauçás, o Império de Kanem-Bornu e o Reino do Benim. Sob domínio britânico a partir do início do século XX, a Nigéria tornou-se independente em 1960. Hoje é o país mais populoso da África e uma das maiores economias do continente." }],
  Sudan: [{ from: 1899, to: 2025, text: "Herdeiro dos antigos reinos núbios de Cuxe e, mais tarde, dos reinos cristãos e do Sultanato de Sennar, o território foi governado sob condomínio anglo-egípcio até a independência em 1956. Desde então, o Sudão enfrentou longas guerras civis, culminando na separação do Sudão do Sul em 2011 e em novos conflitos internos." }],
  Algeria: [{ from: 1830, to: 2025, text: "Habitada por povos berberes e marcada pela presença de Cartago, Roma e do domínio otomano, a Argélia foi colonizada pela França a partir de 1830. Após uma sangrenta guerra de independência, tornou-se soberana em 1962. É hoje o maior país da África em território, com economia baseada em petróleo e gás." }],
  Libya: [{ from: 1911, to: 2025, text: "Terra dos antigos berberes e de colônias fenícias e gregas, mais tarde integrada a Roma e ao Império Otomano, a Líbia foi colonizada pela Itália em 1911. Tornou-se independente em 1951 e viveu sob o longo regime de Muammar Gaddafi, derrubado em 2011, seguido por instabilidade política." }],
  Morocco: [{ from: 1912, to: 2025, text: "Berço de dinastias berberes e árabes como os Almorávidas e Almóadas, Marrocos manteve por séculos um sultanato independente antes de tornar-se protetorado francês e espanhol em 1912. Recuperou a independência em 1956 e permanece uma monarquia, sendo um dos mais antigos Estados do norte da África." }],
  "South Africa": [{ from: 1910, to: 2025, text: "Habitada originalmente por povos khoisan e bantos, a região foi colonizada por holandeses e britânicos a partir do século XVII. A União Sul-Africana formou-se em 1910 e, sob o regime do apartheid, praticou a segregação racial até 1994, quando eleições democráticas levaram Nelson Mandela à presidência." }],
  Angola: [{ from: 1575, to: 2025, text: "Antes da chegada dos portugueses, a região abrigava reinos como o do Congo, Ndongo e Matamba. Colonizada por Portugal a partir do século XVI, Angola tornou-se independente em 1975, seguindo-se uma longa guerra civil encerrada em 2002. É hoje um grande produtor de petróleo e diamantes." }],
  Mozambique: [{ from: 1505, to: 2025, text: "Ponto de encontro de rotas comerciais suaílis do Oceano Índico, o litoral foi ocupado por Portugal a partir do início do século XVI. Moçambique tornou-se independente em 1975 e enfrentou uma guerra civil até 1992. Hoje é um país voltado para o Índico, rico em recursos naturais e gás." }],
  "Tanzania, United Republic of": [{ from: 1885, to: 2025, text: "Centro do comércio suaíli e de cidades como Kilwa e Zanzibar, o território foi colonizado pela Alemanha e depois pelo Reino Unido. A Tanganica tornou-se independente em 1961 e uniu-se a Zanzibar em 1964, formando a República Unida da Tanzânia. Abriga o Kilimanjaro e importantes reservas naturais." }],
  Zambia: [{ from: 1911, to: 2025, text: "Habitada por povos bantos e integrada a redes comerciais do cobre e do marfim, a região tornou-se a colônia britânica da Rodésia do Norte. Conquistou a independência em 1964 como Zâmbia, sob liderança de Kenneth Kaunda. Sua economia depende fortemente da mineração de cobre." }],
  Zaire: [{ from: 1971, to: 1997, text: "Zaire foi o nome dado à República Democrática do Congo entre 1971 e 1997, durante o regime autoritário de Mobutu Sese Seko. O período foi marcado pela política de \"autenticidade\", corrupção e declínio econômico. O nome foi abolido após a queda de Mobutu, retornando à denominação República Democrática do Congo." }],
  Chad: [{ from: 1900, to: 2025, text: "Encruzilhada de rotas transaarianas e sede de reinos como Kanem-Bornu e Ouaddai, a região foi conquistada pela França por volta de 1900. O Chade tornou-se independente em 1960 e enfrentou décadas de conflitos internos e guerras com vizinhos. É um país sem litoral no coração da África." }],
  Niger: [{ from: 1900, to: 2025, text: "Atravessado por antigas rotas de comércio saarianas e ligado a impérios como o Songhai e a estados hauçás, o território foi colonizado pela França no início do século XX. O Níger tornou-se independente em 1960 e, apesar de ricas jazidas de urânio, figura entre os países mais pobres do mundo." }],
  Mauritania: [{ from: 1904, to: 2025, text: "Ponto de encontro entre povos berberes e africanos subsaarianos e parte de antigos impérios como Gana e Almorávida, a região foi colonizada pela França no início do século XX. A Mauritânia tornou-se independente em 1960 e é marcada pelo deserto do Saara e por uma sociedade de tradição nômade." }],
  Namibia: [{ from: 1884, to: 2025, text: "Habitada por povos khoisan, herero e ovambo, a região foi colonizada pela Alemanha como África do Sudoeste, cenário do genocídio herero e nama. Passou ao controle sul-africano até conquistar a independência em 1990. É conhecida pelo deserto do Namibe e por baixa densidade populacional." }],
  Madagascar: [{ from: 1896, to: 2025, text: "Povoada por migrantes austronésios e africanos, a ilha foi unificada sob o Reino de Madagascar antes de tornar-se colônia francesa em 1896. Conquistou a independência em 1960. Sua fauna e flora únicas, resultado do isolamento geográfico, fazem dela um dos maiores centros de biodiversidade do planeta." }],
  Blemmyes: [{ from: -600, to: 600, text: "Os blemmyes foram um povo nômade do deserto oriental da Núbia, entre o Nilo e o Mar Vermelho, mencionado por autores egípcios, gregos e romanos. Notórios como guerreiros e cavaleiros, hostilizaram as fronteiras do Egito romano. Costuma-se associá-los aos ancestrais dos atuais beja." }],
  Guanches: [{ from: -500, to: 1496, text: "Os guanches foram o povo indígena das ilhas Canárias, de origem berbere norte-africana, vivendo do pastoreio e da agricultura em comunidades isoladas. Resistiram por décadas antes de serem subjugados pelos castelhanos ao longo do século XV. Foram gradualmente assimilados e sua cultura original desapareceu." }],
  Berbers: [{ from: -3000, to: 2025, text: "Os berberes, ou amazigh, são os povos autóctones do norte da África, presentes desde a Antiguidade do Egito ao Atlântico. Deram origem a dinastias como Almorávidas e Almóadas e resistiram a fenícios, romanos e árabes, preservando línguas e tradições próprias. Continuam sendo comunidades vivas em países como Marrocos, Argélia e Líbia." }],
  Khoiasan: [{ from: -20000, to: 2025, text: "Os khoisan reúnem os povos khoi (pastores) e san (caçadores-coletores) da África Austral, entre os habitantes mais antigos da região. Falantes de línguas com sons de clique, sofreram forte deslocamento com a expansão banta e a colonização europeia. Suas comunidades sobrevivem sobretudo na Namíbia, Botsuana e África do Sul." }],

  // === Middle East / Central & South & SE Asia ===
  Tibet: [
    { from: 618, to: 842, text: "Entre os séculos VII e IX, o Império Tibetano unificou o planalto sob dinastias como a de Songtsen Gampo, expandindo-se pela Ásia Central e chegando a rivalizar com a China Tang. Nesse período o budismo foi introduzido e começou a se consolidar como força cultural e religiosa." },
    { from: 1642, to: 1912, text: "A partir de 1642, o Tibete organizou-se como uma teocracia budista sob a autoridade dos Dalai Lamas, tendo o palácio de Potala em Lhasa como centro político e espiritual. A região manteve relações complexas de suserania com os impérios mongol e manchu (Qing)." },
    { from: 1913, to: 2025, text: "Em 1950-1951, o Exército de Libertação Popular chinês entrou no Tibete, que foi incorporado à República Popular da China. Após a revolta de 1959, o 14º Dalai Lama exilou-se na Índia, e a região passou a ser administrada como a Região Autônoma do Tibete." },
  ],
  Mongolia: [
    { from: 1368, to: 1691, text: "Após o colapso do domínio mongol na China e a queda da dinastia Yuan, os mongóis retornaram às estepes, fragmentando-se em confederações rivais. Esse período pós-imperial foi marcado por lutas internas e pela crescente influência do budismo tibetano." },
    { from: 1691, to: 1911, text: "A Mongólia Exterior foi incorporada ao Império Qing manchu, permanecendo sob domínio chinês por mais de dois séculos. A autoridade religiosa budista e a administração Qing coexistiram nesse longo período." },
    { from: 1911, to: 2025, text: "Com a queda dos Qing em 1911, a Mongólia declarou independência e, em 1924, tornou-se a República Popular da Mongólia, um Estado socialista alinhado à União Soviética. Após 1990, o país adotou a democracia multipartidária e a economia de mercado." },
  ],
  Iran: [
    { from: 1925, to: 1979, text: "Em 1925, Reza Khan fundou a dinastia Pahlavi, dando início a um período de modernização, centralização e ocidentalização do Irã. Seu filho, Mohammad Reza Pahlavi, governou como xá até ser deposto, em meio a tensões sociais e à crescente oposição." },
    { from: 1979, to: 2025, text: "A Revolução Islâmica de 1979 derrubou a monarquia e estabeleceu a República Islâmica do Irã, sob a liderança do aiatolá Khomeini. O novo regime teocrático transformou profundamente a política, a sociedade e as relações internacionais do país." },
  ],
  "Saudi Arabia": [{ from: 1744, to: 2025, text: "A Arábia Saudita tem origem na aliança do século XVIII entre a família Al Saud e o movimento religioso wahhabita. O reino moderno foi unificado por Abdulaziz ibn Saud e proclamado em 1932, tornando-se, com a descoberta do petróleo, uma das maiores potências econômicas do mundo árabe e o guardião das cidades sagradas de Meca e Medina." }],
  Indonesia: [{ from: 1945, to: 2025, text: "A Indonésia declarou independência dos Países Baixos em 1945, consolidando-a após anos de conflito. Maior arquipélago do mundo e nação de maioria muçulmana mais populosa, tornou-se uma república democrática com enorme diversidade étnica, linguística e cultural." }],
  Pakistan: [{ from: 1947, to: 2025, text: "O Paquistão surgiu em 1947 com a Partição da Índia Britânica, como Estado destinado aos muçulmanos do subcontinente. Sua história foi marcada por rivalidade com a Índia, pela separação do Paquistão Oriental (que se tornou Bangladesh em 1971) e por alternâncias entre governos civis e militares." }],
  Afghanistan: [{ from: 1747, to: 2025, text: "O Afeganistão moderno tem raízes no império fundado por Ahmad Shah Durrani em 1747, e por sua posição estratégica foi disputado por impérios ao longo dos séculos. No período contemporâneo, o país enfrentou a invasão soviética, guerras civis e o domínio do Talibã, tornando-se palco de conflitos prolongados." }],
  Burma: [{ from: 1948, to: 2025, text: "Antiga sede de reinos budistas como o de Pagan, a Birmânia foi colônia britânica até conquistar a independência em 1948. Rebatizada Mianmar pela junta militar em 1989, o país alternou entre governos militares e tentativas de abertura democrática, em meio a conflitos étnicos persistentes." }],
  "British Raj": [{ from: 1858, to: 1947, text: "O Raj Britânico foi o domínio colonial direto da Coroa Britânica sobre o subcontinente indiano, estabelecido em 1858 após a dissolução da Companhia das Índias Orientais. Abrangendo os atuais Índia, Paquistão, Bangladesh e Mianmar, terminou com a independência e a Partição de 1947." }],
  "Dutch East Indies": [{ from: 1800, to: 1949, text: "As Índias Orientais Neerlandesas foram a colônia dos Países Baixos no arquipélago indonésio, sucedendo a administração da Companhia das Índias Orientais. Baseada na exploração de especiarias e culturas de plantação, a colônia perdurou até o reconhecimento da independência da Indonésia, em 1949." }],
  "Mamluke Sultanate": [{ from: 1250, to: 1517, text: "O Sultanato Mameluco foi um Estado governado por uma elite militar de escravos-soldados de origem turca e circassiana, com centro no Egito e no Levante. Notabilizou-se por deter o avanço mongol na batalha de Ain Jalut (1260) e por encerrar a presença cruzada, antes de ser conquistado pelos otomanos em 1517." }],
  Turkey: [
    { from: 1923, to: 1938, text: "A República da Turquia foi fundada em 1923 por Mustafá Kemal Atatürk, após o colapso do Império Otomano. Seu governo implementou reformas radicais de secularização, ocidentalização e modernização, redefinindo a identidade nacional turca." },
    { from: 1938, to: 2025, text: "Após Atatürk, a Turquia consolidou-se como república, aderindo à OTAN e alternando períodos democráticos com intervenções militares. Nas primeiras décadas do século XXI, passou por transformações políticas marcadas pela ascensão de lideranças de inspiração islâmica e por debates sobre seu papel entre o Ocidente e o Oriente Médio." },
  ],
  Kazakhstan: [{ from: 1991, to: 2025, text: "Terra de povos nômades das estepes e sede de canatos cazaques históricos, o Cazaquistão foi integrado ao Império Russo e depois à União Soviética. Declarou independência em 1991 e tornou-se a maior nação sem litoral do mundo, com economia impulsionada por vastas reservas de petróleo e minerais." }],
  Xinjiang: [{ from: 1759, to: 2025, text: "Conhecido historicamente como Turquestão Oriental, o Xinjiang é uma vasta região da Ásia Central habitada sobretudo por povos túrquicos, como os uigures. Conquistado pela dinastia Qing no século XVIII, tornou-se província chinesa e hoje é uma região autônoma da República Popular da China, marcada por tensões étnicas e culturais." }],
  "Kashmir and Ladakh": [{ from: 1846, to: 2025, text: "A Caxemira e o Ladaque formam uma região montanhosa do Himalaia de grande diversidade religiosa, unificada sob o principado de Jammu e Caxemira em 1846. Desde a Partição de 1947, a área é objeto de disputa territorial entre Índia, Paquistão e China, permanecendo uma das regiões mais militarizadas do mundo." }],
  Hadramaut: [{ from: -1000, to: 2025, text: "O Hadramaute é uma região histórica do sul da Península Arábica, na atual costa do Iêmen, célebre na Antiguidade pelo comércio do incenso e da mirra. Ao longo dos séculos abrigou sultanados próprios e uma diáspora influente pelo Oceano Índico, antes de ser integrada ao Iêmen moderno." }],
  "Chagatai Khanate": [{ from: 1226, to: 1687, text: "O Canato Chagatai foi uma das quatro divisões do Império Mongol, criada a partir das terras concedidas a Chagatai, segundo filho de Gêngis Khan, na Ásia Central. Abrangia regiões como a Transoxiana e o Tarim, e ao longo do tempo seus governantes converteram-se ao islã e se fragmentaram, sobrevivendo em partes até o fim do século XVII." }],
  Liao: [{ from: 907, to: 1125, text: "A dinastia Liao foi fundada pelo povo quitan (khitan) e dominou o norte da China, a Manchúria e a Mongólia. Administrava populações nômades e sedentárias por meio de um sistema dual e acabou destruída pela dinastia Jin dos jurchens, embora remanescentes tenham fundado o Kara-Khitai na Ásia Central." }],
  Xixia: [{ from: 1038, to: 1227, text: "O reino Xia Ocidental, ou Tangut, situava-se no noroeste da China, controlando trechos importantes da Rota da Seda. Desenvolveu uma escrita própria e uma cultura budista influente, sendo por fim conquistado e arrasado pelos mongóis de Gêngis Khan." }],
  "Nan Chao": [{ from: 738, to: 902, text: "O reino de Nanzhao surgiu na região de Yunnan, no sudoeste da atual China, unificando várias tribos locais. Tornou-se uma potência regional que resistiu tanto à dinastia Tang chinesa quanto ao Império Tibetano, antes de entrar em colapso e ser sucedido pelo reino de Dali." }],
  Pagan: [{ from: 849, to: 1297, text: "O reino de Pagan (Bagan) foi o primeiro grande Estado unificado do território birmanês, centrado na planície do rio Irauádi. Ficou célebre pela construção de milhares de templos e pagodes budistas e por consolidar o budismo teravada, entrando em declínio após as invasões mongóis." }],
  Kalinga: [{ from: -700, to: 350, text: "Kalinga foi um antigo reino situado na região da atual Odisha, no leste da Índia, conhecido por seu poder marítimo e comercial. Ficou historicamente marcado pela sangrenta conquista promovida pelo imperador Ashoka, cuja violência teria motivado sua conversão ao budismo." }],
  Koguryo: [{ from: -37, to: 668, text: "Goguryeo foi um dos Três Reinos da Coreia, ocupando o norte da península e parte da Manchúria. Destacou-se como potência militar que repeliu invasões das dinastias chinesas Sui e Tang, até ser finalmente derrotado por uma aliança entre Tang e o reino de Silla." }],
  Simhala: [{ from: -300, to: 1200, text: "Simhala designa o antigo Sri Lanka, sede do reino de Anuradhapura e de seus sucessores, berço da cultura cingalesa. Foi um dos grandes centros do budismo teravada, notável por seus sistemas de irrigação e por preservar textos budistas fundamentais." }],
  "Seljuk Caliphate": [{ from: 1037, to: 1194, text: "O domínio dos turcos seljúcidas expandiu-se pelo Oriente Médio a partir do século XI, estabelecendo um grande sultanato sob autoridade nominal do califa abássida. Controlou a Pérsia, a Mesopotâmia e a Anatólia, cuja conquista após a batalha de Manziquerta ajudou a desencadear as Cruzadas." }],
  Ainu: [{ from: 1200, to: 1900, text: "Os ainos são um povo indígena do norte do Japão, sobretudo de Hokkaido, e de ilhas vizinhas como Sacalina e as Curilas. Possuem língua, religião animista e cultura próprias, tendo sofrido intensa assimilação forçada durante a expansão do Estado japonês na era moderna." }],
  Thule: [{ from: 900, to: 1600, text: "A cultura Thule foi a ancestral direta dos inuítes atuais, expandindo-se pelo Ártico da América do Norte a partir do Alasca. Adaptados à caça de baleias e mamíferos marinhos, seus povos substituíram gradualmente a cultura Dorset ao longo de sua migração para leste." }],
  Dorset: [{ from: -500, to: 1500, text: "A cultura Dorset foi uma tradição paleo-esquimó que habitou o Ártico canadense e a Groenlândia antes da chegada dos Thule. Caracterizava-se por ferramentas de pedra e por notável arte em miniatura, desaparecendo após o contato e a substituição pelos ancestrais dos inuítes." }],
  Athabaskan: [{ from: -500, to: 1900, text: "Os povos de língua atabascana habitavam vastas áreas do subártico da América do Norte, do interior do Alasca e do Canadá. Eram caçadores-coletores adaptados às florestas boreais, e alguns grupos migraram para o sul, dando origem a povos como os apaches e navajos." }],

  // === Generic prehistoric/indigenous peoples (fill most of a
  // continent when the atlas has no formal state to show) ===
  "Pampas cultures": [{ from: -8000, to: 1500, text: "Povos indígenas que habitavam as vastas planícies dos pampas na Argentina, no Uruguai e no sul do Brasil, vivendo da caça de guanacos e ñandus, da coleta de plantas silvestres e da pesca em rios e lagoas. Organizavam-se em pequenos grupos móveis, sem agricultura intensiva, adaptados ao clima e à vegetação de campos abertos da região." }],
  "Savanna hunter-gatherers": [{ from: -20000, to: 1500, text: "Populações que ocupavam as savanas da África subsaariana, vivendo da caça de grandes mamíferos, da coleta de frutos, raízes e mel, e da pesca sazonal em rios e lagos. Organizavam-se em pequenos bandos nômades ou seminômades, adaptados à alternância entre estações secas e chuvosas." }],
  "Amazon hunter-gatherers": [{ from: -11000, to: 1500, text: "Povos indígenas da bacia amazônica que combinavam caça, pesca e coleta de frutos, castanhas e outros recursos da floresta tropical, muitas vezes complementando a subsistência com roças itinerantes de mandioca e milho. Viviam em pequenas aldeias dispersas ao longo dos rios, adaptadas à rica biodiversidade e à sazonalidade das cheias." }],
  "Subarctic forest hunter-gatherers": [{ from: -9000, to: 1500, text: "Povos que habitavam as florestas boreais subárticas da América do Norte e da Eurásia, dependendo da caça de alces, caribus e pequenos animais, além da pesca e da coleta sazonal de plantas. Viviam em grupos pequenos e móveis, adaptados aos invernos rigorosos e à escassez de recursos em boa parte do ano." }],
  "Australian aboriginal hunter-gatherers": [{ from: -50000, to: 1788, text: "Povos aborígenes que ocupavam praticamente todo o território da Austrália, subsistindo da caça, da pesca e da coleta de sementes, tubérculos e frutos silvestres, com técnicas como o manejo controlado do fogo para gerir a paisagem. Organizavam-se em centenas de grupos linguísticos e culturais distintos, com complexas redes de trocas, rituais e conhecimento territorial transmitido oralmente." }],
  "Plain bison hunters": [{ from: -9000, to: 1800, text: "Povos indígenas das grandes planícies norte-americanas cuja subsistência girava em torno da caça ao bisão, essencial para alimentação, vestuário e abrigo. Antes da chegada do cavalo, caçavam a pé, muitas vezes conduzindo manadas em direção a precipícios; após o contato europeu, desenvolveram uma cultura equestre nômade altamente móvel." }],
  "West African cereal farmers": [{ from: -3000, to: 1500, text: "Comunidades agrícolas da savana e do Sahel da África Ocidental que cultivavam cereais como sorgo, milheto e arroz africano, complementando a dieta com criação de gado e pesca. Formavam aldeias organizadas em linhagens e chefias locais, mantendo redes regionais de troca de produtos agrícolas e artesanais." }],
  "Paleo-Siberian hunter-gatherers": [{ from: -20000, to: 1500, text: "Populações antigas da Sibéria, anteriores à expansão de povos turcos e mongóis, que viviam da caça de renas e outros animais, da pesca em rios e lagos congelados e da coleta sazonal de plantas. Adaptaram-se a climas extremamente frios, desenvolvendo vestimentas, abrigos e meios de transporte próprios para neve e gelo." }],
  "Arctic marine mammal hunters": [{ from: -4000, to: 1800, text: "Povos do Ártico, ancestrais dos inuítes, iupiques e aleutas, especializados na caça de focas, morsas e baleias, essenciais para alimentação, combustível e materiais de construção. Viviam em pequenas comunidades costeiras adaptadas ao gelo marinho, usando caiaques, arpões e abrigos como iglus e casas semissubterrâneas." }],
  "Finno-Ugric taiga hunter-gatherers": [{ from: -6000, to: 1500, text: "Povos de língua fino-úgrica que habitavam as florestas de taiga do norte da Europa e da Rússia, subsistindo da caça, da pesca e, em muitos casos, da criação de renas. Viviam em pequenos grupos dispersos, adaptados aos invernos longos e às vastas extensões de floresta boreal." }],
  "Eastern North Amercian hunter-gatherers": [{ from: -10000, to: 1500, text: "Povos indígenas das florestas do leste da América do Norte que combinavam a caça de veados e outros animais, a pesca e a coleta de nozes, frutos e sementes silvestres. Com o tempo, muitos grupos passaram a complementar essa base com cultivo incipiente de plantas locais, mantendo aldeias sazonais ao longo de rios e lagos." }],
  "Plateau fichers and hunter gatherers": [{ from: -8000, to: 1500, text: "Povos indígenas do planalto entre as Montanhas Rochosas e a Cordilheira das Cascatas, na América do Norte, cuja subsistência dependia fortemente da pesca do salmão em rios como o Columbia e o Fraser, complementada pela caça e pela coleta de raízes e frutos. Viviam em aldeias semipermanentes próximas aos rios, com intensa atividade sazonal ligada à migração dos peixes." }],
  "Desert hunter-gatherers": [{ from: -20000, to: 1500, text: "Povos adaptados à vida em regiões desérticas e semiáridas de diferentes continentes, subsistindo da caça de pequenos animais, da coleta de plantas resistentes à seca e do uso eficiente de fontes de água escassas. Viviam em pequenos grupos móveis, com profundo conhecimento do território e dos ciclos sazonais de recursos." }],
  "Andean hunter-gatherers": [{ from: -10000, to: -3000, text: "Populações que habitavam as terras altas e os vales andinos antes do desenvolvimento da agricultura e das sociedades complexas da região. Subsistiam da caça de camelídeos selvagens, como a vicunha e o guanaco, e da coleta de plantas e tubérculos silvestres em diferentes andares ecológicos da cordilheira." }],
  Bantou: [{ from: -1000, to: 1500, text: "Povos de língua banto originários da região entre a atual Nigéria e Camarões, que a partir de cerca de 1000 a.C. se expandiram gradualmente por grande parte da África subsaariana. Levavam consigo agricultura, metalurgia do ferro e criação de gado, misturando-se e trocando conhecimentos com as populações locais ao longo de séculos de migração." }],
  "North American Pacifi foraging, hunting and fishing peoples": [{ from: -8000, to: 1500, text: "Povos indígenas da costa noroeste do Pacífico da América do Norte, ancestrais de grupos como os tlingit e os haida, cuja subsistência baseava-se fortemente na pesca do salmão, na caça marinha e na coleta de mariscos e recursos florestais. A abundância de recursos permitiu sociedades relativamente sedentárias e socialmente complexas, com grandes casas de madeira e tradições artísticas elaboradas, mesmo sem agricultura." }],
  "Caribbean hunter-gatherers": [{ from: -5000, to: 1500, text: "Primeiros povos a ocuparem as ilhas do Caribe, vivendo da pesca, da coleta de moluscos e frutos e da caça de pequenos animais nativos. Alguns grupos, como os ancestrais dos ciboney, mantiveram esse modo de vida por milênios, mesmo após a chegada de populações agrícolas, como os taínos, a partes da região." }],
  "Manioc farmers": [{ from: -4000, to: 1500, text: "Povos das terras baixas da América do Sul e do Caribe que desenvolveram o cultivo da mandioca, domesticada na Amazônia, como base alimentar, processando-a para remover toxinas naturais. Complementavam a dieta com caça, pesca e coleta, vivendo em aldeias organizadas ao longo de rios e áreas férteis." }],
  Austronesians: [{ from: -3000, to: 1500, text: "Povos de línguas austronésias originários de Taiwan que, a partir de cerca de 3000 a.C., migraram por mar através do Sudeste Asiático marítimo, alcançando ilhas do Pacífico, Madagascar e a Nova Zelândia. Eram navegadores habilidosos, levando consigo agricultura de plantas como taro e inhame, criação de animais e tecnologias de canoas de longa distância." }],
  "Hopewell Culture": [{ from: -200, to: 500, text: "Complexo cultural que floresceu no vale do rio Ohio e em regiões vizinhas da América do Norte, conhecido por suas extensas redes de troca e pela construção de grandes montes de terra cerimoniais e funerários. Subsistiam de caça, pesca, coleta e cultivo incipiente de plantas nativas, organizados em comunidades sem uma estrutura estatal centralizada." }],
  Dravidians: [{ from: -3000, to: 1500, text: "Povos falantes de línguas dravídicas do sul da Índia, entre os grupos linguísticos mais antigos do subcontinente, que desenvolveram agricultura, sistemas de irrigação e centros urbanos ao longo de milênios. Formaram a base cultural e linguística de regiões como Tâmil Nadu, Karnataka, Andhra Pradesh e Kerala, com tradições próprias de literatura, religião e organização social." }],
  Siberians: [{ from: -3000, to: 1600, text: "Diversos povos indígenas da vasta região da Sibéria, incluindo grupos de línguas turcas, mongólicas e tungúsicas, que viviam da caça, do pastoreio de renas, da pesca e do comércio de peles. Organizavam-se em clãs e confederações regionais, adaptando-se a ambientes que iam da taiga às estepes, até serem gradualmente incorporados ao domínio russo a partir do século XVI." }],
  "Maize farmers": [{ from: -3500, to: 1500, text: "Povos da Mesoamérica e de regiões adjacentes que desenvolveram e difundiram o cultivo do milho, domesticado a partir do teosinto, como base de suas economias agrícolas. O milho permitiu o surgimento de aldeias permanentes e, posteriormente, de sociedades mais complexas em partes da América do Norte, Central e do Sul." }],
  Bantu: [{ from: -1000, to: 1500, text: "Povos de língua banto que, a partir de cerca de 1000 a.C., se expandiram da região entre a atual Nigéria e Camarões para grande parte da África subsaariana. Difundiram a agricultura, a metalurgia do ferro e a criação de gado, formando ao longo dos séculos uma vasta família de línguas e culturas relacionadas em todo o continente." }],
  Khoisan: [{ from: -20000, to: 1700, text: "Povos khoi e san do sul da África, entre as populações com linhagens genéticas mais antigas da humanidade, tradicionalmente organizados em bandos de caçadores-coletores (san) e pastores de gado (khoikhoi). Viviam com profundo conhecimento do ambiente semiárido, caçando com arco e flecha e coletando plantas do deserto do Kalahari e regiões vizinhas." }],
  Semites: [{ from: -3500, to: -500, text: "Termo que designa os antigos povos falantes de línguas semíticas do Oriente Próximo, como acádios, cananeus, hebreus, arameus e árabes antigos, que habitaram a Mesopotâmia, o Levante e a Península Arábica. Suas atividades variavam da agricultura irrigada e do comércio urbano ao pastoreio nômade, e foram responsáveis por importantes inovações culturais e linguísticas da região." }],
  "Norte Chico": [{ from: -3500, to: -1800, text: "Civilização que floresceu na costa norte-central do atual Peru, considerada uma das mais antigas sociedades complexas das Américas, com centros como Caral. Baseava-se na agricultura irrigada de algodão e legumes combinada com a exploração de abundantes recursos marinhos, erguendo grandes estruturas piramidais sem uso conhecido de cerâmica e sem evidências claras de guerra." }],
  "city-states": [{ from: -3500, to: 1500, text: "Categoria que representa comunidades urbanas autônomas, cada uma governando a si mesma e o território ao redor sem se integrar a um império maior, um padrão político recorrente em diversas regiões e períodos da história antiga e medieval, como na Suméria, na Fenícia, na Grécia, na Itália, na costa suaíli e entre os iorubás. Combinavam comércio, artesanato e agricultura próxima, com governos locais monárquicos, oligárquicos ou assembleares." }],
  "Aboriginal tribes": [{ from: -20000, to: 1500, text: "Termo amplo usado para designar diversos povos indígenas organizados em tribos ou grupos etnolinguísticos, vivendo tradicionalmente da caça, da pesca, da coleta e, em muitos casos, de agricultura de subsistência, antes do contato com estados coloniais ou centralizados. Mantinham estruturas sociais próprias, baseadas em parentesco, liderança comunitária e forte ligação com o território ancestral." }],
  "Hunters-gatherers": [{ from: -50000, to: 1500, text: "Categoria genérica que reúne populações humanas cuja subsistência dependia da caça, da pesca e da coleta de plantas silvestres, sem agricultura ou pecuária desenvolvidas. Representam o modo de vida predominante da humanidade por dezenas de milhares de anos, organizado em pequenos grupos móveis adaptados a diferentes ambientes ao redor do mundo." }],
  "Aboriginal Tasmanians": [{ from: -10000, to: 1803, text: "Povos aborígenes que habitavam a ilha da Tasmânia, isolados do continente australiano após a elevação do nível do mar ao final da última era glacial, há cerca de 10 mil anos. Viviam da caça, da pesca costeira, da coleta de mariscos e plantas silvestres, desenvolvendo tecnologias e costumes distintos dos povos aborígenes do continente devido a esse longo isolamento." }],
  Thai: [{ from: -500, to: 1250, text: "Primeiros povos de língua tai, originários do sul da China, que migraram gradualmente para o Sudeste Asiático continental antes da formação dos reinos tais históricos, como Sukhothai e Ayutthaya. Viviam em comunidades agrícolas baseadas no cultivo de arroz em vales fluviais, organizadas em pequenos principados e redes de parentesco." }],
  "Ethiopian highland farmers": [{ from: -3000, to: 1500, text: "Comunidades agrícolas das terras altas da Etiópia que desenvolveram de forma independente o cultivo de plantas nativas como o teff e o enset (falsa-bananeira), além de cevada e outros cereais adaptados à altitude. Praticavam agricultura em terraços e encostas, combinada com a criação de gado, formando a base econômica de sociedades duradouras da região." }],
  "Austro-Asiatic rice farmers": [{ from: -3000, to: 500, text: "Povos falantes de línguas austroasiáticas, como os mon, os khmer e grupos munda, que desenvolveram o cultivo de arroz irrigado no Sudeste Asiático continental e em partes do leste da Índia. Viviam em aldeias organizadas ao redor de sistemas de irrigação e diques, com forte relação entre agricultura, calendário sazonal e práticas religiosas locais." }],
  "Saharan pastoral nomads": [{ from: -2000, to: 1500, text: "Povos pastores nômades do deserto do Saara, adaptados à criação de gado, cabras e, posteriormente, camelos em um ambiente de crescente aridez desde o fim do período úmido africano. Controlavam oásis e rotas de comércio transaarianas, servindo de elo entre a África subsaariana e o Mediterrâneo." }],
  "Saharan Pastoral Nomads": [{ from: -2000, to: 1500, text: "Povos pastores nômades do deserto do Saara, adaptados à criação de gado, cabras e, posteriormente, camelos em um ambiente de crescente aridez desde o fim do período úmido africano. Controlavam oásis e rotas de comércio transaarianas, servindo de elo entre a África subsaariana e o Mediterrâneo." }],
  "Islamic city-states": [{ from: 900, to: 1500, text: "Cidades-portuárias e entrepostos comerciais islamizados, como os da costa suaíli ou do Sudeste Asiático, que floresceram como centros autônomos de comércio marítimo sem se integrar a um império territorial maior. Ligavam redes comerciais do Oceano Índico, combinando mercadores locais, árabes, persas e indianos sob a fé muçulmana." }],
  "Tungusic Tribes": [{ from: -200, to: 1600, text: "Os povos de línguas tungúsicas, originários da Sibéria Oriental e da Manchúria, viviam tradicionalmente da caça, da pesca e da criação de renas nas florestas do nordeste asiático. Ancestrais dos manchus e de outros grupos como os evenques, tiveram papel relevante nas dinâmicas políticas da fronteira entre a China, a Coreia e a estepe mongol." }],

  // === Steppe khanates, Rus principalities, Central/South Asian states ===
  "Khanate of the Golden Horde": [{ from: 1242, to: 1502, text: "Fundada por Batu Khan, neto de Gêngis Khan, a Horda Dourada foi um canato mongol-turco que dominou as estepes russas, o Cáucaso e partes da Ásia Central, impondo tributo aos principados da Rus por mais de dois séculos. Progressivamente turquizada e islamizada, fragmentou-se a partir do século XV em canatos menores como Crimeia, Cazã e Astracã, e desapareceu de vez com a queda da Grande Horda em 1502." }],
  Ilkhanate: [{ from: 1256, to: 1335, text: "Fundado por Hulagu Khan, neto de Gêngis Khan, o Ilcanato governou a Pérsia, a Mesopotâmia e partes da Anatólia e do Cáucaso a partir de sua capital Tabriz. Responsável pela destruição do Califado Abássida em Bagdá em 1258, o canato converteu-se ao Islã no início do século XIV e se fragmentou em dinastias regionais após a morte do último ilcã em 1335." }],
  "White Horde": [{ from: 1226, to: 1378, text: "A Horda Branca foi a ala oriental do Ulus de Jochi, governada pelos descendentes de Orda Khan nas estepes a leste do rio Ural, no atual Cazaquistão. Politicamente subordinada mas administrativamente autônoma em relação ao ramo ocidental, foi unificada com a Horda Azul por Toctamis por volta de 1378-1380, restaurando temporariamente a unidade da Horda Dourada." }],
  "Blue Horde": [{ from: 1226, to: 1380, text: "A Horda Azul constituiu a ala ocidental do Ulus de Jochi, descendente da linhagem de Batu Khan, controlando a região do baixo Volga e as estepes pônticas com sede em Sarai. Era o núcleo político mais poderoso da Horda Dourada, até ser reunificada com a Horda Branca por Toctamis por volta de 1380." }],
  "Tsardom of Muscovy": [{ from: 1547, to: 1721, text: "Proclamado quando Ivã IV, o Terrível, assumiu o título de czar em 1547, o Czarado da Moscóvia consolidou o poder centralizado russo, expandiu-se sobre Cazã, Astracã e a Sibéria, e sobreviveu a crises como o Tempo das Perturbações. Deu lugar ao Império Russo em 1721, quando Pedro, o Grande, adotou o título imperial após a Grande Guerra do Norte." }],
  "Grand Duchy of Moscow": [{ from: 1263, to: 1547, text: "Surgido como um pequeno principado vassalo da Horda Dourada, o Grão-Ducado de Moscou cresceu sob príncipes como Ivã I e, sobretudo, Ivã III, que unificou grande parte das terras russas e rompeu o jugo mongol em 1480. Tornou-se a base do Estado russo moderno até ser transformado em Czarado em 1547." }],
  "Quazaq Khanate": [{ from: 1465, to: 1847, text: "Fundado por volta de 1465 pelos sultões Kerei e Janibek, dissidentes do Canato Uzbeque, o Canato Cazaque unificou as tribos nômades das estepes cazaques em uma confederação com três Jüz (hordes). Enfraquecido por disputas internas e pela pressão russa e junguar, foi gradualmente anexado pelo Império Russo entre o século XVIII e 1847." }],
  "Khiva Khanate": [{ from: 1511, to: 1920, text: "Estabelecido em 1511 por uma dinastia de origem xaibânida uzbeque na região histórica de Corásmia, o Canato de Khiva foi um dos principais Estados turco-mongóis da Ásia Central, vivendo do comércio de caravanas e do tráfico de escravos. Tornou-se protetorado russo em 1873 e foi extinto em 1920 com a criação da República Popular Soviética de Khorezm." }],
  "Kimek-Kipchak khaganate": [{ from: 750, to: 1050, text: "O Canato Kimek-Kipchak foi uma confederação turca que dominou as estepes da Sibéria ocidental e do rio Irtish entre os séculos VIII e XI. Sua desintegração deu origem às tribos Cumano-Kipchak, que passaram a controlar a vasta estepe eurasiática conhecida como Desht-i-Kipchak." }],
  "Cuman-Kipchak confederation": [{ from: 1050, to: 1241, text: "A confederação Cumano-Kipchak reuniu tribos turcas nômades que dominaram a estepe pôntico-cáspia, do Danúbio ao Cazaquistão, mantendo relações comerciais e militares com a Rus de Kiev, Bizâncio e a Hungria. Foi conquistada e absorvida pelas invasões mongóis entre 1220 e 1241, com muitos cumanos migrando para a Hungria e os Bálcãs." }],
  "Cuman Khanates": [{ from: 1050, to: 1241, text: "Os canatos cumanos formaram uma rede de chefias turcas nômades que controlaram a estepe pôntico-cáspia entre os séculos XI e XIII, rivalizando e comerciando com a Rus de Kiev e o Império Bizantino. Desapareceram como potência independente com a invasão mongol, que dispersou os cumanos e absorveu suas terras na Horda Dourada." }],
  "Kara Khitai Khaganate": [{ from: 1124, to: 1218, text: "Fundado por Yelü Dashi, príncipe da dinastia chinesa Liao em fuga após sua queda, o Canato Kara-Khitai (Liao Ocidental) estabeleceu-se na Ásia Central, dominando Cara-Kanidas e Corásmios como vassalos. Manteve uma administração relativamente tolerante e sinizada até ser tomado pelo usurpador Kuchlug e conquistado pelos mongóis em 1218." }],
  "Timurid Emirates": [{ from: 1447, to: 1507, text: "Após a morte de Shah Rukh em 1447, o vasto Império Timúrida fragmentou-se em uma série de emirados rivais centrados em Herat, Samarcanda e outras cidades, governados por príncipes da mesma dinastia em constante disputa. Esses emirados sucumbiram à conquista dos uzbeques xaibânidas no início do século XVI, embora um ramo timúrida sobrevivesse na Índia como o Império Mogol." }],
  "Emirate of the White Sheep Turks": [{ from: 1378, to: 1503, text: "O Aq Qoyunlu, ou Turcomanos do Carneiro Branco, foi uma confederação tribal turcomana que construiu um império abrangendo o leste da Anatólia, o Cáucaso, o Iraque e o oeste do Irã, atingindo seu apogeu sob Uzun Hasan no século XV. Enfraquecido por guerras sucessórias, foi derrotado e substituído pela nascente dinastia Safávida entre 1501 e 1503." }],
  "Oirat Confederation": [{ from: 1399, to: 1755, text: "A Confederação Oirata reuniu tribos mongóis ocidentais que, sob líderes como Esen Khan, chegaram a derrotar e capturar o imperador Ming em 1449, projetando grande poder sobre a Mongólia e a Ásia Central. Seu principal Estado sucessor, o Canato Junguar, resistiu por séculos até ser destruído pela dinastia Qing em uma campanha de conquista concluída em 1755." }],
  Ryazan: [{ from: 1129, to: 1521, text: "Riazã foi um dos principados da Rus medieval, situado no rio Oká, conhecido por sua resistência e destruição pelos mongóis em 1237, episódio que marcou o início da invasão de Batu Khan à Rus. Após séculos como vassalo relutante de Moscou, foi definitivamente anexado ao Grão-Ducado de Moscou em 1521." }],
  "Kyivan Rus": [{ from: 882, to: 1240, text: "A Rus de Kiev foi um vasto Estado eslavo oriental fundado por príncipes varegues da dinastia Rurikida, unificando Kiev, Novogárdia e outras cidades ao longo da rota comercial 'dos varegues aos gregos'. Convertida ao cristianismo ortodoxo em 988 sob o príncipe Vladimir, floresceu culturalmente antes de se fragmentar em principados rivais e ser arrasada pela invasão mongol em 1240." }],
  "Caliphate of Córdoba": [{ from: 929, to: 1031, text: "Proclamado por Abderramão III em 929, o Califado de Córdoba transformou Al-Andalus no centro de um brilhante período de esplendor cultural, científico e econômico na Espanha muçulmana, com Córdoba rivalizando com Bagdá e Constantinopla. Minado por guerras civis, o califado desintegrou-se em 1031 em uma miríade de pequenos reinos taifas." }],
  Karkhanids: [{ from: 840, to: 1212, text: "Os Cara-Kanidas foram a primeira dinastia turca a adotar o Islã, formando um canato que dominou a Transoxiana e a bacia do Tarim, com centros em Cachegária, Balasagum, Samarcanda e Bucara. O Estado, frequentemente dividido entre ramos rivais, foi progressivamente absorvido pelos Cara-Khitai e depois pelos Corásmios, desaparecendo no início do século XIII." }],
  "Buwayhid Emirates": [{ from: 934, to: 1062, text: "Os emirados Búwayhidas, de origem persa e fé xiita, conquistaram Bagdá em 945 e passaram a controlar o Califado Abássida, reduzindo os califas sunitas a figuras cerimoniais enquanto governavam o Iraque e grande parte do Irã. A confederação fragmentou-se entre ramos familiares rivais e foi finalmente derrubada pelos turcos seljúcidas em 1062." }],
  "Rajput kingdoms": [{ from: 700, to: 1200, text: "Os reinos rajputes formavam um mosaico de dinastias guerreiras hindus no noroeste da Índia, organizadas em clãs como os Chauhans, Solankis e Paramaras, famosos por seu código de honra militar e disputas constantes entre si. Apesar de oferecerem resistência prolongada às invasões turco-islâmicas, muitos reinos rajputes foram gradualmente subjugados pelo Sultanato de Déli a partir do final do século XII." }],
  "Rajput Kingdoms": [{ from: 700, to: 1200, text: "Os reinos rajputes formavam um mosaico de dinastias guerreiras hindus no noroeste da Índia, organizadas em clãs como os Chauhans, Solankis e Paramaras, famosos por seu código de honra militar e disputas constantes entre si. Apesar de oferecerem resistência prolongada às invasões turco-islâmicas, muitos reinos rajputes foram gradualmente subjugados pelo Sultanato de Déli a partir do final do século XII." }],
  Rajputs: [{ from: 700, to: 1200, text: "Os reinos rajputes formavam um mosaico de dinastias guerreiras hindus no noroeste da Índia, organizadas em clãs como os Chauhans, Solankis e Paramaras, famosos por seu código de honra militar e disputas constantes entre si. Apesar de oferecerem resistência prolongada às invasões turco-islâmicas, muitos reinos rajputes foram gradualmente subjugados pelo Sultanato de Déli a partir do final do século XII." }],
  Sikhs: [{ from: 1799, to: 1849, text: "O Império Sikh foi fundado por Ranjit Singh em 1799 a partir da unificação de misls (confederações militares) sikhs no Punjab, tornando-se um poderoso Estado moderno com exército profissionalizado e capital em Lahore. Após a morte de Ranjit Singh, o império mergulhou em instabilidade sucessória e foi anexado pelos britânicos em 1849, ao final das Guerras Anglo-Sikhs." }],
  "Islamic and Hindu states": [{ from: 1200, to: 1500, text: "Este rótulo representa um período de intensa fragmentação política no subcontinente indiano e na Ásia Central, marcado por um mosaico de sultanatos islâmicos e reinos hindus regionais coexistindo, competindo e frequentemente guerreando entre si. Nenhum poder único dominava toda a região, e alianças e fronteiras mudavam constantemente entre dinastias locais de ambas as tradições religiosas." }],
  "central Asian khanates": [{ from: 1700, to: 1873, text: "Este rótulo agrupa os canatos turco-mongóis da Ásia Central — principalmente Bucara, Cocande e Khiva — que dominaram as rotas de caravanas e os oásis da região entre os séculos XVIII e XIX. Enfraquecidos por rivalidades mútuas, foram progressivamente conquistados ou transformados em protetorados pelo Império Russo em sua expansão para o sul." }],
  "Kingdom of Sukhotai": [{ from: 1238, to: 1438, text: "Fundado em 1238 como o primeiro reino tailandês independente, Sukhothai floresceu sob o rei Ramkhamhaeng, que expandiu seu território, promoveu o budismo Theravada e é tradicionalmente associado à criação do alfabeto tailandês. Gradualmente eclipsado por seu vizinho mais poderoso ao sul, foi incorporado ao Reino de Ayutthaya em 1438." }],
  "Rattanakosin Kingdom": [{ from: 1782, to: 2025, text: "Fundado em 1782 por Rama I com a nova capital em Bangkok, o Reino de Rattanakosin deu continuidade ao Estado siamês sob a dinastia Chakri, modernizando-se para preservar sua independência frente ao colonialismo europeu. Uma revolução em 1932 transformou a monarquia absoluta em constitucional, e a dinastia Chakri permanece à frente da Tailândia até hoje." }],
  "Post-Ming Warlords": [{ from: 1640, to: 1683, text: "No colapso final da dinastia Ming, líderes rebeldes como Li Zicheng e Zhang Xianzhong ergueram exércitos e tomaram vastas regiões da China, enquanto a corte imperial fugia e senhores da guerra regionais disputavam o controle do território. O período de caos culminou na conquista manchu e no estabelecimento da dinastia Qing, com a resistência Ming remanescente sendo eliminada até 1683." }],

  // === Modern colonial administrations / viceroyalties ===
  "French West Africa": [{ from: 1895, to: 1958, text: "Federação de colônias francesas na África Ocidental, formada em 1895 e administrada a partir de Dakar, reunindo territórios como Senegal, Mali, Costa do Marfim e Níger. O sistema colonial impôs trabalho forçado e culturas de exportação, gerando resistências locais que alimentaram os movimentos de independência do pós-guerra. Foi dissolvida em 1958 com a criação da Comunidade Francesa, dando origem a diversos países independentes." }],
  "French Equatorial Africa": [{ from: 1910, to: 1958, text: "Federação colonial francesa que reunia Gabão, Congo Médio, Ubangi-Chari e Chade, administrada a partir de Brazzaville. Explorou intensamente recursos como borracha e madeira através de companhias concessionárias, com condições de trabalho extremamente duras para a população africana. Foi dissolvida em 1958, precedendo a independência de seus territórios em 1960." }],
  "Belgian Congo": [{ from: 1908, to: 1960, text: "Colônia formada em 1908 quando o Estado Livre do Congo, propriedade pessoal do rei Leopoldo II, foi transferido ao governo belga após denúncias internacionais de atrocidades. A exploração de borracha, cobre e diamantes gerou imensa riqueza para a metrópole à custa de trabalho forçado e violência sistemática. Tornou-se independente em 1960 como República do Congo, em meio a uma transição turbulenta." }],
  "Netherlands Indies": [{ from: 1816, to: 1949, text: "As Índias Neerlandesas eram o vasto império colonial holandês no arquipélago indonésio, formalizado após a devolução das possessões pelos britânicos em 1816 e consolidado ao longo do século XIX. A exploração de especiarias, açúcar e petróleo sustentou a economia holandesa através do 'sistema de cultivo' e depois de grandes companhias. A ocupação japonesa (1942-1945) enfraqueceu o domínio colonial, e a independência da Indonésia foi reconhecida em 1949 após anos de guerra." }],
  "Union of South Africa": [{ from: 1910, to: 1961, text: "Domínio britânico criado em 1910 pela união das colônias do Cabo, Natal, Transvaal e Estado Livre de Orange, sob autogoverno da minoria branca. Ao longo de sua existência, institucionalizou a segregação racial que culminaria no apartheid formal após 1948. Tornou-se república independente em 1961, rompendo os laços com a Coroa britânica." }],
  "Cape Colony": [{ from: 1795, to: 1910, text: "Colônia britânica no extremo sul da África, ocupada pelos britânicos em 1795 e definitivamente incorporada ao império em 1814, sucedendo o domínio holandês anterior. Foi palco de tensões entre colonos britânicos, bôeres e povos africanos, incluindo as Guerras de Fronteira e o Grande Trek dos bôeres para o interior. Em 1910 integrou-se à recém-formada União Sul-Africana." }],
  Rhodesia: [{ from: 1890, to: 1980, text: "Território colonizado pela Companhia Britânica da África do Sul de Cecil Rhodes a partir de 1890, tornando-se colônia autônoma da Coroa em 1923. Em 1965 a minoria branca declarou unilateralmente independência para preservar seu domínio político, gerando isolamento internacional e uma longa guerra civil. Após o fim do regime branco, o território tornou-se o Zimbábue independente em 1980." }],
  "Anglo-Egyption Sudan": [{ from: 1899, to: 1956, text: "Condomínio administrado conjuntamente pelo Reino Unido e pelo Egito a partir de 1899, embora na prática o controle britânico fosse dominante. A administração combinou exploração econômica, como o algodão do Gezira, com políticas que aprofundaram divisões entre o norte árabe-muçulmano e o sul africano. Tornou-se independente como Sudão em 1956." }],
  Manchuria: [{ from: 1932, to: 1945, text: "Região nordeste da China transformada pelo Japão no Estado-fantoche de Manchukuo em 1932, após a invasão japonesa de 1931, com o último imperador Puyi colocado como figura nominal no trono. O território foi intensamente industrializado e militarizado para servir aos interesses estratégicos japoneses, com exploração de mão de obra e recursos locais. O regime colapsou em 1945 com a derrota do Japão e a invasão soviética." }],
  "French Indochina": [{ from: 1887, to: 1954, text: "União colonial francesa formada em 1887 reunindo Vietnã, Camboja e, a partir de 1893, Laos, explorada principalmente através de plantações de arroz e borracha. A ocupação japonesa durante a Segunda Guerra Mundial enfraqueceu o controle francês e estimulou movimentos nacionalistas como o Viet Minh. A derrota francesa na Batalha de Dien Bien Phu em 1954 encerrou o domínio colonial, dividindo o Vietnã em dois estados." }],
  "Vice Royalty of New Spain": [{ from: 1535, to: 1821, text: "Vice-reino espanhol estabelecido em 1535 sobre os territórios conquistados do Império Asteca, abrangendo o México atual e partes da América Central e do sudoeste dos Estados Unidos. Tornou-se um dos centros mais ricos do império espanhol graças à mineração de prata, sustentada pelo trabalho indígena e africano escravizado. Alcançou a independência em 1821 após uma longa guerra iniciada em 1810." }],
  "Vice-Royalty of New Spain": [{ from: 1535, to: 1821, text: "Vice-reino espanhol estabelecido em 1535 sobre os territórios conquistados do Império Asteca, abrangendo o México atual e partes da América Central e do sudoeste dos Estados Unidos. Tornou-se um dos centros mais ricos do império espanhol graças à mineração de prata, sustentada pelo trabalho indígena e africano escravizado. Alcançou a independência em 1821 após uma longa guerra iniciada em 1810." }],
  "Vice Royalty of Peru": [{ from: 1542, to: 1824, text: "Vice-reino espanhol criado em 1542 sobre os territórios do antigo Império Inca, tornando-se o principal centro administrativo e econômico da América do Sul espanhola graças às minas de prata de Potosí. Sofreu sucessivas reduções territoriais no século XVIII com a criação dos vice-reinos de Nova Granada e do Rio da Prata. Sua dominação terminou com as batalhas de independência, culminando na Batalha de Ayacucho em 1824." }],
  "Vice-Royalty of Peru": [{ from: 1542, to: 1824, text: "Vice-reino espanhol criado em 1542 sobre os territórios do antigo Império Inca, tornando-se o principal centro administrativo e econômico da América do Sul espanhola graças às minas de prata de Potosí. Sofreu sucessivas reduções territoriais no século XVIII com a criação dos vice-reinos de Nova Granada e do Rio da Prata. Sua dominação terminou com as batalhas de independência, culminando na Batalha de Ayacucho em 1824." }],
  "Vice-Royalty of New Granada": [{ from: 1717, to: 1819, text: "Vice-reino espanhol criado definitivamente em 1739, com sede em Bogotá, abrangendo os atuais territórios da Colômbia, Venezuela, Equador e Panamá. Sua economia baseava-se na mineração de ouro e na agricultura, administrada sob rígido controle da Coroa espanhola. Foi desmantelado pelas campanhas independentistas lideradas por Simón Bolívar, culminando na vitória de Boyacá em 1819." }],
  "Viceroyalty of the Río de la Plata": [{ from: 1776, to: 1814, text: "Vice-reino espanhol criado em 1776 com sede em Buenos Aires, reunindo os territórios que hoje formam Argentina, Uruguai, Paraguai e Bolívia, para reforçar o controle sobre a região frente às ameaças portuguesa e britânica. Buenos Aires tornou-se um importante porto comercial, impulsionando o crescimento econômico da região. A Revolução de Maio de 1810 iniciou o processo que levaria à independência das Províncias Unidas do Rio da Prata." }],
  "Vice-Royalty of Brazil": [{ from: 1720, to: 1815, text: "Fase final do Brasil colonial português, elevado à condição de vice-reino em 1720 e com sede transferida do Salvador para o Rio de Janeiro em 1763, refletindo a importância crescente da mineração de ouro em Minas Gerais. A chegada da família real portuguesa em 1808, fugindo das invasões napoleônicas, transformou profundamente a administração e a economia colonial. O período encerrou-se em 1815 com a elevação do Brasil à condição de Reino Unido a Portugal." }],
  "Portuguese Brazil": [{ from: 1500, to: 1815, text: "Colônia portuguesa na América do Sul, iniciada com a chegada de Pedro Álvares Cabral em 1500 e desenvolvida através do cultivo do pau-brasil, da cana-de-açúcar e, posteriormente, da mineração de ouro e diamantes. A economia dependeu massivamente do trabalho escravo indígena e, sobretudo, africano trazido pelo tráfico transatlântico. O período colonial encerrou-se formalmente em 1815, quando o Brasil foi elevado à categoria de Reino Unido a Portugal e Algarves." }],
  "Rupert's Land": [{ from: 1670, to: 1870, text: "Vasto território concedido pela Coroa britânica à Companhia da Baía de Hudson em 1670, abrangendo toda a bacia hidrográfica que deságua na Baía de Hudson, no atual Canadá. A região foi explorada essencialmente através do comércio de peles com os povos indígenas, sustentando postos comerciais isolados por dois séculos. Foi transferida ao recém-formado Domínio do Canadá em 1870, integrando-se aos Territórios do Noroeste." }],
  Luisiana: [{ from: 1682, to: 1803, text: "Vasto território colonial reclamado pela França em 1682 no vale do rio Mississippi, cedido à Espanha em 1762 e devolvido brevemente à França em 1800. Sua economia baseava-se no comércio de peles, na agricultura de plantação e no controle estratégico da navegação do Mississippi. Foi vendida aos Estados Unidos em 1803, na chamada Compra da Luisiana, dobrando o território do país." }],
  Quebec: [{ from: 1763, to: 1867, text: "Colônia britânica criada em 1763 pelo Tratado de Paris, herdando o território da antiga Nova França após a derrota francesa na Guerra dos Sete Anos. O Ato de Quebec de 1774 preservou o direito civil francês, a religião católica e a língua francesa, garantindo a lealdade da população local à Coroa britânica. Integrou-se à Confederação Canadense em 1867 como uma de suas províncias fundadoras." }],
  "Poland-Llituania": [{ from: 1569, to: 1795, text: "União política formada pela Confederação de Lublin em 1569, unindo o Reino da Polônia e o Grão-Ducado da Lituânia em um dos maiores e mais populosos estados da Europa. Caracterizava-se por um sistema político descentralizado, com uma nobreza poderosa e eleição do monarca. Foi progressivamente desmembrada pelas potências vizinhas nas três Partições da Polônia, desaparecendo do mapa em 1795." }],
  "Polish–Lithuanian Commonwealth": [{ from: 1569, to: 1795, text: "União política formada pela Confederação de Lublin em 1569, unindo o Reino da Polônia e o Grão-Ducado da Lituânia em um dos maiores e mais populosos estados da Europa. Caracterizava-se por um sistema político descentralizado, com uma nobreza poderosa e eleição do monarca. Foi progressivamente desmembrada pelas potências vizinhas nas três Partições da Polônia, desaparecendo do mapa em 1795." }],
  "Sweden–Norway": [{ from: 1814, to: 1905, text: "União dinástica formada em 1814, após a Noruega ser cedida pela Dinamarca à Suécia ao final das guerras napoleônicas, mantendo os dois reinos com constituições e instituições próprias sob um mesmo monarca. A Noruega conservou ampla autonomia interna, incluindo seu próprio parlamento, o Storting, gerando tensões crescentes sobre política externa e representação diplomática. A união foi dissolvida pacificamente em 1905, com a independência plena da Noruega." }],
  "Austria Hungary": [{ from: 1867, to: 1918, text: "Monarquia dual criada pelo Compromisso de 1867, unindo o Império Austríaco e o Reino da Hungria sob a Casa de Habsburgo, com administrações e parlamentos separados mas política externa e defesa comuns. Reunia uma extraordinária diversidade de povos eslavos, magiares, germânicos e romenos, cujas tensões nacionalistas fragilizaram progressivamente o estado. Colapsou em 1918 ao final da Primeira Guerra Mundial, dando origem a diversas nações independentes na Europa Central." }],
  "Western Australia (UK)": [{ from: 1829, to: 1901, text: "Colônia britânica fundada em 1829 na costa oeste do continente australiano, tendo sido a última colônia australiana a receber colonos livres em massa devido ao seu isolamento. A descoberta de ouro na década de 1890 provocou uma corrida populacional que transformou sua economia e sociedade. Em 1901, integrou-se à recém-federada Comunidade da Austrália." }],
  "Queensland (UK)": [{ from: 1859, to: 1901, text: "Colônia britânica criada em 1859 a partir do desmembramento de Nova Gales do Sul, no nordeste do continente australiano. Sua economia desenvolveu-se em torno da pecuária, do açúcar e da mineração, com uso controverso de trabalhadores das ilhas do Pacífico recrutados sob condições exploratórias. Tornou-se um estado da Comunidade da Austrália com a federação de 1901." }],
  "Northern Territory (UK)": [{ from: 1863, to: 1901, text: "Território administrado pela colônia britânica da Austrália do Sul a partir de 1863, cobrindo a vasta região tropical do centro-norte do continente australiano. Pouco povoado por colonos europeus, manteve relações intensas e por vezes violentas com os povos aborígines, além de contato comercial com pescadores asiáticos no norte. Permaneceu sob administração da Austrália do Sul até a federação australiana de 1901." }],
  "South Australia (UK)": [{ from: 1836, to: 1901, text: "Colônia britânica fundada em 1836 como um empreendimento planejado de colonização livre, sem o uso de mão de obra condenada, diferentemente de outras colônias australianas. Desenvolveu-se com base na agricultura, na mineração de cobre e em um pioneirismo institucional, sendo a primeira do mundo a conceder o voto às mulheres em 1894. Integrou-se à Comunidade da Austrália na federação de 1901." }],
  "New South Wales (UK)": [{ from: 1788, to: 1901, text: "Primeira colônia britânica estabelecida na Austrália, fundada em 1788 em Sydney inicialmente como colônia penal para receber condenados britânicos. Ao longo do século XIX expandiu-se enormemente através da pecuária de ovinos e, depois, da corrida do ouro, tornando-se a colônia mais populosa e rica do continente. Foi a base a partir da qual as demais colônias australianas se formaram, unindo-se a elas na federação de 1901." }],
  "Arabia (Nejd)": [{ from: 1902, to: 1932, text: "Núcleo do interior árabe reconquistado pela dinastia Al Saud a partir da tomada de Riade em 1902, liderada por Abdulaziz Ibn Saud, restaurando o poder saudita após décadas de exílio. O emirado expandiu-se através de conquistas sobre rivais como os Rashidi do Ha'il e o Reino do Hejaz, unificando grande parte da Arábia central sob influência do wahhabismo. Em 1932, tornou-se o núcleo do recém-proclamado Reino da Arábia Saudita." }],
  Nejd: [{ from: 1902, to: 1932, text: "Núcleo do interior árabe reconquistado pela dinastia Al Saud a partir da tomada de Riade em 1902, liderada por Abdulaziz Ibn Saud, restaurando o poder saudita após décadas de exílio. O emirado expandiu-se através de conquistas sobre rivais como os Rashidi do Ha'il e o Reino do Hejaz, unificando grande parte da Arábia central sob influência do wahhabismo. Em 1932, tornou-se o núcleo do recém-proclamado Reino da Arábia Saudita." }],
  "Emirate of Bin Shal'an": [{ from: 1908, to: 1932, text: "Pequeno emirado tribal do norte da Arábia, centrado na região do Jauf, governado pela família Al-Sha'lan, líderes da tribo beduína Ruwallah. Sua posição estratégica entre a Síria, a Transjordânia e o interior árabe fazia dele um ator relevante nas disputas regionais durante o declínio otomano e a expansão saudita. Foi absorvido pelo avanço das forças de Ibn Saud no processo de unificação da Arábia Saudita." }],
  Abyssinia: [{ from: 1889, to: 1936, text: "Nome histórico do Império Etíope, que sob o imperador Menelik II expandiu e modernizou o estado, obtendo uma vitória decisiva sobre a Itália na Batalha de Adwa em 1896, um marco raro de resistência africana ao colonialismo europeu. Manteve sua independência ao longo do início do século XX sob o imperador Haile Selassie. Foi invadida e ocupada pela Itália fascista em 1936, sendo incorporada à África Oriental Italiana até 1941." }],
  "Chinese Warlords": [{ from: 1916, to: 1928, text: "Período de fragmentação política na China após a morte de Yuan Shikai em 1916, no qual o poder central colapsou e diversas regiões passaram a ser controladas por generais militares regionais rivais. As disputas entre facções como a Clique de Fengtian, de Zhili e de Anhui geraram guerras constantes e sofrimento para a população civil. O período encerrou-se formalmente com a reunificação nominal do país pelo Kuomintang na Expedição do Norte, concluída em 1928." }],
  "Chinese warlords": [{ from: 1916, to: 1928, text: "Período de fragmentação política na China após a morte de Yuan Shikai em 1916, no qual o poder central colapsou e diversas regiões passaram a ser controladas por generais militares regionais rivais. As disputas entre facções como a Clique de Fengtian, de Zhili e de Anhui geraram guerras constantes e sofrimento para a população civil. O período encerrou-se formalmente com a reunificação nominal do país pelo Kuomintang na Expedição do Norte, concluída em 1928." }],

  // === Ancient/regional peoples and small kingdoms (Middle East, Central/East Asia, Africa, Americas) ===
  "Saka Kingdom": [{ from: -200, to: 400, text: "Os citas Saka, povo nômade de origem irânica oriundo da Ásia Central, invadiram e se estabeleceram no noroeste do subcontinente indiano a partir do século II a.C., fundando reinos indo-citas na Bactriana, Gandara e no oeste da Índia. Governantes saka como os satrapas ocidentais mesclaram tradições estépicas com cultura helenística e indiana, deixando marcas duradouras na numismática e na administração regional." }],
  "Suren Kingdom": [{ from: -247, to: 224, text: "Os Suren foram uma das sete grandes famílias nobres do Império Parta, detentoras hereditárias do direito de coroar o rei e comandar o exército em batalha. Seu domínio semi-autônomo na região da Sistão tornou-se célebre após a vitória sobre os romanos em Carras, em 53 a.C., sob o comando do general Surena." }],
  "Zhangzhung Kingdom": [{ from: -500, to: 625, text: "Zhangzhung foi um antigo reino do oeste e noroeste do planalto tibetano, centrado na região do monte Kailash, e berço da religião bön anterior ao budismo tibetano. Floresceu como potência independente controlando rotas comerciais transhimalaicas até ser conquistado e absorvido pelo emergente Império Tibetano no início do século VII." }],
  "Karasuk culture": [{ from: -1500, to: -800, text: "A cultura Karasuk foi uma sociedade da Idade do Bronze que floresceu nas estepes do sul da Sibéria, na bacia do rio Yenisei, sucedendo a cultura Andronovo. Seus povos eram pastores seminômades conhecidos por metalurgia de bronze sofisticada, incluindo facas, machados e ornamentos de estilo animalístico que influenciaram tradições estépicas posteriores." }],
  "Prot-Altaic pastoralists": [{ from: -3000, to: -1000, text: "Os pastores proto-altaicos designam populações pré-históricas da região dos montes Altai, na fronteira entre Sibéria, Mongólia e Ásia Central, consideradas os ancestrais linguísticos hipotéticos dos povos turcos, mongóis e tungues. Praticavam pastoreio de cavalos e gado, contribuindo para a difusão posterior de línguas e tecnologias equestres pelas estepes eurasiáticas." }],
  "Iranian pastoralists": [{ from: -1000, to: 400, text: "Os pastores nômades de origem irânica, como citas, sármatas e alanos, dominaram as vastas estepes eurasiáticas entre a Europa Oriental e a Ásia Central. Organizados em confederações tribais móveis baseadas na cavalaria, influenciaram profundamente povos vizinhos por meio do comércio, da guerra e da difusão de tecnologias militares." }],
  "Arabian pastoral nomads": [{ from: -3000, to: 600, text: "Os beduínos, povos pastores nômades da Península Arábica, organizavam-se em tribos e clãs baseados no pastoreio de camelos e cabras pelo deserto. Antes da unificação islâmica no século VII, viviam em constante rivalidade e alianças tribais, controlando rotas caravaneiras entre a Arábia, o Levante e o Iêmen." }],
  Cimerians: [{ from: -1200, to: -600, text: "Os cimérios foram um povo nômade indo-europeu que habitou as estepes pônticas ao norte do mar Negro antes da chegada dos citas. Pressionados por estes últimos, migraram e realizaram incursões pela Ásia Menor e pelo Cáucaso, sendo mencionados em fontes assírias e na tradição grega antiga, incluindo Homero." }],
  "N. European Bronze Age cultures": [{ from: -1700, to: -500, text: "As culturas da Idade do Bronze do norte da Europa desenvolveram-se na Escandinávia e na região báltica, conhecidas por seus túmulos monumentais, petróglifos e objetos de bronze ricamente decorados, como os famosos carros rituais e trombetas litúrgicas (lurs). O comércio de âmbar báltico e estanho conectava essas sociedades às redes comerciais da Europa Central e do Mediterrâneo." }],
  "Urnfield cultures": [{ from: -1300, to: -750, text: "A cultura dos Campos de Urnas floresceu na Europa Central durante o Bronze Final, caracterizada pelo rito da cremação e sepultamento das cinzas em urnas de cerâmica organizadas em grandes cemitérios. Considerada um substrato importante para o surgimento posterior dos povos celtas, difundiu-se por uma vasta área entre a Europa Ocidental e os Bálcãs." }],
  Sinic: [{ from: -1046, to: -771, text: "O rótulo 'sínico' refere-se ao mosaico de pequenos estados e principados da China arcaica que compartilhavam a cultura, a escrita e os rituais originários da dinastia Zhou. Esses estados vassalos, nominalmente subordinados ao rei Zhou, mantinham considerável autonomia política e frequentemente disputavam território entre si." }],
  Zhoa: [{ from: -770, to: -256, text: "Os Estados Zhou designam a miríade de reinos e principados chineses que emergiram durante os períodos de Primavera e Outono e dos Reinos Combatentes, quando o poder central da dinastia Zhou Oriental se fragmentou. Esses estados rivais, como Qin, Chu, Qi e Jin, disputavam supremacia militar e territorial até a unificação da China pelo estado de Qin em 221 a.C." }],
  Afanasevo: [{ from: -3300, to: -2500, text: "A cultura Afanasievo foi uma das primeiras sociedades da Idade do Bronze na Sibéria meridional, na bacia do rio Yenisei, associada à expansão para o leste de populações estépicas de ascendência indo-europeia. Praticavam pastoreio de gado, ovelhas e cavalos e são considerados possíveis ancestrais dos futuros habitantes da bacia do Tarim, incluindo os tocários." }],
  Valdivia: [{ from: -3500, to: -1800, text: "A cultura Valdivia floresceu na costa do atual Equador, sendo uma das mais antigas sociedades sedentárias e produtoras de cerâmica das Américas. Seus habitantes viviam da pesca, agricultura incipiente e comércio, sendo famosos por suas figurinas de cerâmica femininas e por técnicas cerâmicas sofisticadas para a época." }],
  Kerma: [{ from: -2500, to: -1500, text: "O Reino de Kerma foi um antigo estado núbio centrado na cidade de mesmo nome, às margens do Nilo, tornando-se um poderoso rival comercial e militar do Egito antigo. Desenvolveu arquitetura monumental própria, como os deffufas de tijolos de barro, até ser conquistado pelo Egito durante o Novo Império, por volta de 1500 a.C." }],
  Namazga: [{ from: -3500, to: -1500, text: "A cultura Namazga floresceu na Ásia Central, na região do atual Turcomenistão, sendo um importante centro urbano e artesanal da Idade do Bronze ligado ao Complexo Arqueológico da Báctria-Margiana. Seus habitantes desenvolveram agricultura irrigada, metalurgia e comércio de longa distância conectando o Irã, a Índia e as estepes eurasiáticas." }],
  "Hurrian Kingdoms": [{ from: -2500, to: -1300, text: "Os reinos hurritas, entre os quais se destacou o poderoso reino de Mitani, dominaram o norte da Mesopotâmia e da Síria durante o segundo milênio a.C. Falantes de uma língua não semita nem indo-europeia, desenvolveram uma sofisticada tradição militar baseada em carros de guerra e mantiveram relações diplomáticas e conflitos com egípcios, hititas e assírios." }],
  "Dapenkeng culture": [{ from: -4000, to: -2500, text: "A cultura Dapenkeng foi a mais antiga cultura neolítica conhecida de Taiwan, associada aos primeiros agricultores e ceramistas da ilha. É considerada o ponto de partida para a expansão dos povos austronésios, que a partir de Taiwan se espalharam pelas ilhas do Sudeste Asiático, Oceania e Madagascar." }],
  "Jōmon": [{ from: -14000, to: -300, text: "O Jōmon foi um longo período pré-histórico do arquipélago japonês, marcado por sociedades de caçadores-coletores-pescadores relativamente sedentárias graças à abundância de recursos marinhos e florestais. Ficaram famosos por produzirem uma das cerâmicas mais antigas do mundo, decorada com cordas entrelaçadas que dão nome ao período." }],
  "Hindu kingdoms": [{ from: 500, to: 1200, text: "O rótulo 'reinos hindus' refere-se ao mosaico fragmentado de dinastias regionais que governavam diferentes partes do subcontinente indiano nesse período, cada uma com sua corte, exército e patronato religioso próprios. Essa fragmentação política convivia com fortes elos culturais e religiosos compartilhados, expressos na arquitetura de templos, na literatura sânscrita e nas tradições hindus." }],
  "Hindu kingdoms and republics": [{ from: -600, to: 200, text: "Este rótulo abrange o conjunto de reinos monárquicos e repúblicas oligárquicas (ganarajyas) que coexistiam no norte da Índia antiga, como os dezesseis grandes Mahajanapadas. Essa diversidade de formas de governo, disputando território e influência entre si, caracterizou o período anterior e paralelo à ascensão dos grandes impérios indianos, como o Máuria." }],
  "minor Hindu kingdoms": [{ from: 1200, to: 1700, text: "Após o declínio dos grandes impérios regionais e o avanço dos sultanatos islâmicos no subcontinente, diversos pequenos reinos hindus locais persistiram em áreas periféricas, como Rajastão, o sul da Índia e regiões montanhosas. Esses reinos mantiveram tradições políticas e religiosas hindus, muitas vezes pagando tributo ou resistindo militarmente aos poderes muçulmanos dominantes." }],
  Tungus: [{ from: -200, to: 1600, text: "Os povos tungues, grupo etnolinguístico originário da Sibéria Oriental e da Manchúria, viviam tradicionalmente da caça, pesca e criação de renas em florestas e estepes do nordeste asiático. Ancestrais dos manchus e de outros povos como os evenques, tiveram papel relevante nas dinâmicas políticas da fronteira entre a China, a Coreia e a estepe mongol." }],
  Inupiaq: [{ from: 1000, to: 1800, text: "Os Inupiaq são um povo inuíte que habita o norte do Alasca, adaptado à vida no Ártico por meio da caça de baleias, focas e caribus. Organizados em comunidades costeiras e do interior, desenvolveram tecnologias especializadas como o umiak e o kayak para a caça marinha em condições climáticas extremas." }],
  Chukchi: [{ from: 1000, to: 1800, text: "Os chukchis são um povo indígena do extremo nordeste da Sibéria, tradicionalmente divididos entre grupos pastores de renas do interior e caçadores marinhos da costa. Resistiram ferozmente à expansão russa para o leste durante os séculos XVII e XVIII, sendo um dos poucos povos siberianos a nunca serem completamente subjugados pela Rússia czarista." }],
  Cree: [{ from: 1000, to: 1800, text: "Os Cree constituem um dos maiores povos indígenas da América do Norte, tradicionalmente distribuídos por vastas áreas do Canadá, entre florestas subárticas e planícies. Viviam da caça, pesca e coleta sazonal, e posteriormente desempenharam papel central no comércio de peles com europeus, atuando como intermediários entre companhias comerciais e outras nações indígenas." }],
  Obiwa: [{ from: 1000, to: 1800, text: "Os ojibwa (ou anishinaabe) são um povo indígena algonquino da região dos Grandes Lagos norte-americanos, tradicionalmente organizados em bandos ligados por laços de parentesco e pela Grande Sociedade da Medicina (Midewiwin). Praticavam caça, pesca, coleta de arroz selvagem e produção de açúcar de bordo, além de manter extensas redes comerciais e diplomáticas com povos vizinhos." }],
  Oromo: [{ from: 1500, to: 1900, text: "Os oromo constituem o maior grupo etnolinguístico do Chifre da África, tradicionalmente organizados no sistema gadaa, uma estrutura política e social baseada em classes etárias com rotação de lideranças. A partir do século XVI, expandiram-se amplamente pelo planalto etíope e regiões vizinhas, tornando-se um dos povos mais numerosos e influentes da Etiópia moderna." }],
  Arabs: [{ from: 600, to: 1500, text: "Este rótulo representa as populações árabes de determinada região antes ou à margem de um Estado centralizado específico, geralmente organizadas em tribos, clãs e confederações locais. Compartilhavam língua, costumes e, após o século VII, a religião islâmica, mas mantinham autonomia política considerável em relação a impérios e califados vizinhos." }],
  "Malaysian Islamic states": [{ from: 1400, to: 1800, text: "Os sultanatos islâmicos malaios surgiram no Sudeste Asiático marítimo a partir do século XV, com a conversão de portos comerciais como Malaca ao islamismo, difundindo a nova fé por toda a região arquipelágica. Esses estados prosperaram com o comércio de especiarias e produtos de luxo, disputando influência entre si e, posteriormente, com as potências coloniais europeias." }],
  Ifat: [{ from: 1285, to: 1415, text: "O Sultanato de Ifat foi um estado muçulmano medieval situado no Chifre da África, na região do atual leste da Etiópia e Djibuti, controlando importantes rotas comerciais entre o interior etíope e o mar Vermelho. Rival histórico dos reinos cristãos etíopes, foi derrotado e sucedido pelo Sultanato de Adal após conflitos prolongados no início do século XV." }],
  "T'atsaot'ine": [{ from: 1700, to: 1900, text: "Os T'atsaot'ine, também conhecidos como Yellowknives, são um povo indígena dene (atabascano) do norte do Canadá, tradicionalmente estabelecido na região do Grande Lago dos Escravos. Viviam da caça de caribus e da pesca, e seu nome, que remete a ferramentas de cobre, reflete seu papel histórico no comércio desse metal com povos vizinhos." }],
  Athabascan: [{ from: -1000, to: 1800, text: "Os povos de língua atabascana formam um vasto grupo etnolinguístico do subártico norte-americano, distribuído desde o interior do Alasca e noroeste do Canadá até partes do sudoeste dos Estados Unidos, no caso dos navajo e apache. Tradicionalmente organizados em pequenos bandos de caçadores-coletores, adaptaram-se a ambientes extremamente diversos ao longo de sua expansão histórica." }],
  Papous: [{ from: 500, to: 1800, text: "Os papuas são os povos indígenas da ilha da Nova Guiné, caracterizados por uma diversidade linguística extraordinária, com centenas de línguas distintas faladas por pequenos grupos organizados em aldeias autônomas. Praticavam agricultura de subsistência, especialmente o cultivo de inhame e taro nas terras altas, além de caça e coleta, mantendo pouco contato com potências externas até a era colonial." }],
  "Berber Tribes": [{ from: -1000, to: 700, text: "As tribos berberes, povos indígenas do norte da África, organizavam-se em confederações tribais que dominavam desde o litoral mediterrâneo até as franjas do Saara, antes da conquista árabe-islâmica da região. Praticavam agricultura, pastoreio e comércio caravaneiro, e resistiram ou se aliaram alternadamente a fenícios, romanos, vândalos e bizantinos ao longo dos séculos." }],
  "Tuareg Nomadic Tribes": [{ from: 700, to: 1900, text: "Os tuaregues são um povo berbere nômade do Saara central, tradicionalmente organizados em confederações tribais hierárquicas dedicadas ao pastoreio de camelos e ao controle das rotas caravaneiras transaarianas de sal, ouro e escravos. Conhecidos por sua escrita tifinagh e pelo uso do véu masculino (tagelmust), mantiveram considerável autonomia frente aos impérios do Sahel e às potências coloniais até o século XIX." }],
  Touareg: [{ from: 700, to: 1900, text: "Os tuaregues, povo berbere nômade do Saara central, organizavam-se em confederações hierárquicas de clãs guerreiros e vassalos dedicados ao pastoreio de camelos e ao controle das rotas caravaneiras transaarianas. Sua língua, o tamachek, e a escrita tifinagh, assim como o uso característico do véu masculino, marcam uma identidade cultural distinta mantida até os dias atuais." }],

  // === Late Roman fragments, Persian world, Anatolia, Balkans (ancient) ===
  "Rome (Maximian)": [{ from: 286, to: 305, text: "Sob a Tetrarquia instituída por Diocleciano, Maximiano governou como Augusto do Ocidente, controlando a Itália, a África e a Hispânia. Sua principal missão foi conter revoltas internas e invasões bárbaras no Reno, dividindo o peso administrativo e militar do vasto Império Romano. Abdicou em 305 junto com Diocleciano, mas retornou ao poder brevemente antes de morrer em 310." }],
  "Rome (Constantinus)": [{ from: 293, to: 306, text: "Constâncio Cloro governou como César e depois Augusto do Ocidente dentro do sistema tetrárquico, administrando a Gália, a Britânia e parte da Hispânia. Destacou-se por reconquistar a Britânia e conter incursões francas e alamanas nas fronteiras renanas. Sua morte em York, em 306, levou suas tropas a aclamarem seu filho Constantino como novo imperador, evento que abriria caminho para a reunificação do império." }],
  "Rome (Galerius)": [{ from: 293, to: 311, text: "Galério atuou como César e depois Augusto do Oriente na Tetrarquia, governando os Bálcãs, a Ilíria e parte da Ásia Menor. Foi um comandante militar de destaque, célebre por sua vitória decisiva sobre o Império Sassânida em 298. Ficou também associado às últimas e mais duras perseguições aos cristãos, antes de emitir, pouco antes de morrer, um edito de tolerância religiosa." }],
  Parthia: [{ from: -247, to: 224, text: "O Império Parta, fundado pelos arsácidas na região da antiga Pártia, tornou-se a grande potência rival de Roma no Oriente. Controlava as rotas comerciais da Rota da Seda e manteve conflitos constantes com os romanos pela Armênia e Mesopotâmia. Enfraquecido por guerras civis, foi derrubado em 224 pelos sassânidas, que fundaram um novo império persa." }],
  "Sasanian dependencies": [{ from: 224, to: 651, text: "Diversos reinos e territórios vassalos, como principados árabes, caucasianos e da Ásia Central, pagavam tributo e forneciam tropas ao Império Sassânida em troca de autonomia interna. Esses dependentes serviam como zonas-tampão frente a romanos, bizantinos e nômades das estepes. O sistema de vassalagem persistiu até o colapso sassânida diante da conquista árabe-muçulmana no século VII." }],
  Cappadocia: [{ from: -300, to: 17, text: "A Capadócia foi um reino da Anatólia central formado após a fragmentação do império de Alexandre, governado por uma dinastia de origem persa. Tornou-se reino cliente de Roma a partir do século I a.C., mantendo autonomia sob supervisão romana. Em 17 d.C., o imperador Tibério anexou definitivamente o território, transformando-o em província romana." }],
  Atropatene: [{ from: -321, to: 226, text: "Atropatene foi um reino helenístico fundado pelo sátrapa persa Atropates no noroeste do atual Irã, região que herdou seu nome, origem do topônimo Azerbaijão. Manteve forte identidade zoroastrista e relativa independência entre os impérios selêucida, parta e romano. Foi absorvido pelo Império Sassânida no início do século III, tornando-se uma de suas principais províncias." }],
  Dacia: [{ from: -82, to: 106, text: "O reino da Dácia, unificado por Burebista e depois fortalecido sob Decébalo, ocupava o território da atual Romênia, rico em ouro e minérios. Sua resistência aos romanos culminou nas guerras dácicas de Trajano, que resultaram na conquista e anexação da região em 106 d.C. A vitória foi imortalizada na Coluna de Trajano em Roma." }],
  Daces: [{ from: -82, to: 106, text: "Os dácios eram um povo trácio da Europa Central e Oriental, organizados em tribos guerreiras e conhecidos por suas fortalezas nas montanhas dos Cárpatos. Sob líderes como Burebista e Decébalo, formaram um reino poderoso que desafiou o poder romano por décadas. Foram finalmente subjugados por Trajano em 106 d.C., e parte de sua população foi romanizada, dando origem ao povo romeno." }],
  Illyrians: [{ from: -1000, to: 9, text: "Os ilírios eram um conjunto de povos indo-europeus que habitavam a costa e o interior dos Bálcãs ocidentais, organizados em tribos e pequenos reinos guerreiros e piratas. Entraram repetidamente em conflito com Roma, especialmente durante as Guerras Ilírias dos séculos III e II a.C. A resistência final foi esmagada em 9 d.C., após a grande revolta de Baton, quando a região foi definitivamente incorporada ao domínio romano." }],
  Celtiberians: [{ from: -300, to: -133, text: "Os celtiberos eram povos de cultura mista celta e ibérica que habitavam o planalto central da Península Ibérica. Ficaram famosos por sua feroz resistência à expansão romana, sobretudo na defesa de cidades como Numância. Sua derrota final em 133 a.C., após um longo cerco liderado por Cipião Emiliano, marcou a submissão da região ao poder de Roma." }],
  Franks: [{ from: 250, to: 481, text: "Os francos eram uma confederação de tribos germânicas surgida ao longo do baixo Reno no século III, que passou a pressionar e se estabelecer nas fronteiras romanas da Gália. Serviram tanto como invasores quanto como aliados militares de Roma ao longo dos séculos seguintes. Com o declínio do poder romano no Ocidente, consolidaram-se como o povo dominante da Gália, base sobre a qual Clóvis fundaria o reino franco." }],
  Burgunds: [{ from: 250, to: 534, text: "Os burgúndios eram um povo germânico oriundo da região do Báltico que migrou para o oeste, alcançando o Reno e depois a Gália oriental. Estabeleceram um reino que sobreviveu a uma derrota devastadora contra os hunos em 436, reorganizando-se na região que hoje leva seu nome, a Borgonha. Em 534, seu reino foi conquistado e absorvido pelo reino franco." }],
  "Kingdom of Syphax": [{ from: -213, to: -202, text: "O reino de Sífax reunia os massessílios, um dos principais grupos numidas do norte da África, na região correspondente à atual Argélia ocidental. Durante a Segunda Guerra Púnica, Sífax aliou-se a Cartago contra seu rival Massinissa, apoiado por Roma. Derrotado na Batalha dos Grandes Campos em 203 a.C. e capturado logo depois, perdeu seu reino, que foi anexado por Massinissa com apoio romano." }],
  Mauretania: [{ from: -225, to: 40, text: "A Mauretânia era um antigo reino berbere do noroeste africano, correspondente ao atual Marrocos e parte da Argélia, conhecido por sua riqueza agrícola e produção de púrpura. Manteve relações de aliança e depois de vassalagem com Roma, especialmente sob o rei Juba II. Foi anexada como território romano em 40 d.C., após o assassinato de seu último rei, Ptolomeu, por ordem do imperador Calígula." }],
  Maan: [{ from: -100, to: 300, text: "Maan era um pequeno reino árabe pré-islâmico da região do Levante e da Arábia, integrado às redes comerciais que ligavam a Arábia ao Mediterrâneo. Como outros pequenos principados árabes da época, dependia do controle de rotas de caravanas e de alianças com potências vizinhas, como Roma e os partas. Sua história é conhecida principalmente por referências esparsas em fontes epigráficas e clássicas." }],
  Alans: [{ from: 50, to: 500, text: "Os alanos eram um povo nômade de origem sármata e irânica, oriundo das estepes ao norte do Cáucaso e do Mar Negro. Pressionados pela expansão dos hunos no século IV, migraram para o oeste, atravessando o Reno em 406 junto com vândalos e suevos. Parte deles se estabeleceu na Gália e na Hispânia, sendo gradualmente assimilada pelas populações locais e por outros povos germânicos." }],
  Sarmates: [{ from: -300, to: 400, text: "Os sármatas eram um povo nômade irânico das estepes pônticas, que sucedeu os citas como potência dominante da região a partir do século III a.C. Organizados em confederações tribais como os iázigas e roxolanos, mantiveram frequentes conflitos e trocas comerciais com o Império Romano ao longo do Danúbio. Seu domínio declinou com as invasões góticas e hunas do século IV, que os empurraram para o interior da Europa." }],
  Saces: [{ from: -700, to: 100, text: "Os saces eram um ramo dos citas, povos nômades irânicos das estepes da Ásia Central, conhecidos por sua cavalaria e habilidade com o arco. Migraram e fundaram reinos na Báctria, no Sistão e no noroeste da Índia, formando o que ficou conhecido como os reinos indo-citas. Foram gradualmente absorvidos ou substituídos por outros povos, como os kushans, no início da era comum." }],
  Kushites: [{ from: -1070, to: 350, text: "Os cuchitas eram o povo do reino de Cuxe, civilização núbia situada ao sul do Egito, ao longo do rio Nilo, com capitais sucessivas em Napata e depois Méroe. Chegaram a conquistar e governar o próprio Egito como a XXV dinastia, no século VIII a.C. O reino floresceu por séculos graças ao comércio e à metalurgia do ferro, até declinar e ser destruído por volta de 350 d.C. pelo reino de Axum." }],
  Yuezhi: [{ from: -700, to: -30, text: "Os yuezhi eram um povo nômade indo-europeu da Ásia Central, originalmente estabelecido na região do atual noroeste da China. Expulsos de suas terras pelos xiongnu no século II a.C., migraram para o oeste até a Báctria, onde subjugaram os reinos greco-báctrios remanescentes. Uma de suas cinco tribos, os kushans, viria a unificá-los e fundar o poderoso Império Kushan." }],
  "Nan-Yue": [{ from: -204, to: -111, text: "Nam Việt, ou Nanyue, foi um reino fundado por um antigo general chinês no sul da China e norte do atual Vietnã, após a fragmentação da dinastia Qin. Mesclou elementos da cultura chinesa Han com tradições locais das populações Việt. Foi conquistado e anexado pela dinastia Han em 111 a.C., dando início a um longo período de dominação chinesa sobre o território vietnamita." }],
  "Min-Yue": [{ from: -334, to: -110, text: "Minyue foi um reino antigo do sudeste da China, na região correspondente ao atual Fujian, formado por descendentes do estado de Yue após sua fragmentação. Manteve cultura própria, distinta da chinesa central, e relações ora de aliança ora de conflito com a dinastia Han. Foi conquistado e sua população deslocada pelos Han em 110 a.C., pondo fim à sua autonomia." }],
  "Anatolian tribes": [{ from: -2000, to: -600, text: "As tribos anatólicas eram os povos indígenas pré-helênicos que habitavam o interior da Ásia Menor central e oriental, herdeiros de tradições que remontam aos hititas e outras civilizações da Idade do Bronze. Viviam em comunidades tribais e pequenos reinos antes da chegada de colonos gregos ao litoral e da expansão do poder persa. Gradualmente foram incorporados às esferas de influência grega, lídia e persa que disputavam o controle da região." }],
  Bedouins: [{ from: -1000, to: 630, text: "Os beduínos eram povos árabes nômades que habitavam os desertos da Arábia, organizados em clãs e tribos dedicados ao pastoreio de camelos e cabras. Serviam frequentemente como guias e guerreiros das caravanas que atravessavam a península, além de manterem relações comerciais e de conflito com impérios vizinhos como Roma, Pártia e os reinos sul-arábicos. Sua cultura tribal e tradições orais formariam mais tarde a base social sobre a qual o Islã se expandiria." }],
  Qataban: [{ from: -400, to: 200, text: "Qataban foi um antigo reino do sul da Arábia, na região do atual Iêmen, que prosperou graças ao controle de trechos da Rota do Incenso. Rivalizou por séculos com o reino de Sabá e com Hadramaute pelo domínio do comércio de mirra e incenso. Perdeu gradualmente território e influência, sendo finalmente absorvido pelos reinos vizinhos por volta do século II ou III d.C." }],
  Vazimba: [{ from: -500, to: 1500, text: "Os vazimba são considerados, segundo a tradição oral malgaxe, os primeiros habitantes de Madagascar, anteriores à chegada dos grupos austronésios e africanos que deram origem ao povo malgaxe atual. Viviam dispersos em pequenas comunidades, associadas na memória popular a florestas e lugares sagrados. Foram gradualmente absorvidos, expulsos ou assimilados pelos povos recém-chegados, restando de sua presença sobretudo lendas e locais de culto ancestral." }],

  // === Steppe/Central Asian/Chinese dynasties (early medieval) ===
  "Southern Xiongnu": [{ from: 48, to: 304, text: "Ramo dos xiongnu que se submeteu à dinastia Han em 48 d.C. e se estabeleceu como povo vassalo nas fronteiras do norte da China, em contraste com os xiongnu do norte, que permaneceram independentes e hostis. Progressivamente sinizados, seus líderes acabaram aproveitando o enfraquecimento da dinastia Jin para fundar o estado de Han Zhao no início do século IV." }],
  "Han Zhao": [{ from: 304, to: 329, text: "Também chamado Zhao Anterior, foi um estado fundado por xiongnu sinizados liderados por Liu Yuan em 304, durante o caótico período dos Dezesseis Reinos. Suas forças saquearam as capitais chinesas Luoyang (311) e Chang'an (316), derrubando efetivamente a dinastia Jin Ocidental, até ser destruído pelo rival Zhao Posterior em 329." }],
  Jin: [{ from: 265, to: 420, text: "Dinastia chinesa que reunificou brevemente o país em 280 após o fim do período dos Três Reinos. Perdeu o controle do norte da China para invasores nômades no início do século IV, sobrevivendo apenas no sul como Jin Oriental até ser substituída em 420." }],
  "Jin Empire": [{ from: 265, to: 420, text: "Império chinês fundado em 265 pela família Sima, que pôs fim à era dos Três Reinos e reunificou a China em 280. A invasão de povos nômades do norte forçou a corte a se refugiar ao sul do rio Yangtzé em 317, iniciando um longo período de divisão entre norte e sul." }],
  Ruanruan: [{ from: 330, to: 555, text: "O Canato Ruanruan (Rouran) foi uma confederação nômade de origem proto-mongol que dominou as estepes da Mongólia entre os séculos IV e VI, rivalizando com a dinastia Toba Wei ao sul. Foi derrotado e desmantelado em 552-555 por seus antigos vassalos ferreiros, os turcos Göktürk, que fundaram em seu lugar o primeiro grande império turco das estepes." }],
  "Toba Wei": [{ from: 386, to: 534, text: "A dinastia Wei do Norte foi fundada pelo povo Xianbei Tuoba (Toba), que unificou o norte da China em 439 após séculos de fragmentação. Promoveu ativamente a sinização de sua elite e o budismo, patrocinando grandes complexos rupestres como Yungang e Longmen, antes de se dividir em dois estados rivais em 534-535." }],
  "Tufan Empire": [{ from: 618, to: 842, text: "Nome usado pelas fontes chinesas para o Império Tibetano, potência que se expandiu a partir do planalto tibetano e rivalizou diretamente com a dinastia Tang pelo controle da Ásia Central e das rotas comerciais. Chegou a saquear a capital Tang, Chang'an, em 763, mantendo relações marcadas por guerras e tratados de paz até seu colapso interno em meados do século IX." }],
  "Western Gokturk Khaganate": [{ from: 603, to: 657, text: "Divisão ocidental do Império Göktürk, formada pela cisão de 603, que controlou a Ásia Central e boa parte da Rota da Seda entre os mares Cáspio e a China. Enfraquecido por lutas internas, foi conquistado pela dinastia Tang em 657, que absorveu temporariamente seu território." }],
  "Tibetan Empire": [{ from: 618, to: 842, text: "Fundado por Songtsen Gampo no início do século VII, unificou o planalto tibetano e transformou-o em uma das grandes potências militares da Ásia, disputando território com a China Tang, os árabes e os turcos. Introduziu o budismo e uma escrita própria antes de fragmentar-se em principados rivais após 842." }],
  Tibetans: [{ from: 618, to: 842, text: "Povo do planalto tibetano que, sob a dinastia Yarlung, construiu um império expansivo entre os séculos VII e IX, chegando a ocupar Chang'an em 763 e a controlar rotas estratégicas da Ásia Central. A fragmentação política após 842 encerrou a fase imperial, mas deixou um legado cultural e religioso duradouro." }],
  "Oghuz Turks": [{ from: 750, to: 1055, text: "Confederação turca das estepes da Ásia Central que formou o Estado Yabgu Oguz próximo ao mar de Aral. Deles descendem os seljúcidas e, mais tarde, os otomanos, que migraram para oeste e sul a partir do século XI transformando o mapa político do Oriente Médio." }],
  Oghuz: [{ from: 750, to: 1055, text: "Povo turco nômade organizado em tribos sob a liderança de um yabgu, dominando as estepes entre o mar Cáspio e o rio Sir Dária. Sua fragmentação e migração deram origem às dinastias seljúcida e, indiretamente, otomana, que redesenharam a Anatólia e o mundo islâmico." }],
  Khitans: [{ from: 907, to: 1125, text: "Povo de origem mongol-tungúsica das estepes da Manchúria que, sob Yelü Abaoji, fundou a dinastia Liao em 907, dominando o norte da China, a Manchúria e parte da Mongólia. Combinando administração dual para súditos nômades e sedentários, foi finalmente derrubado pelos jurchen em 1125, embora remanescentes tenham fundado o Cara-Catai na Ásia Central." }],
  Uyghurs: [{ from: 744, to: 1209, text: "Povo turco que derrubou o Canato Göktürk e fundou seu próprio Canato Uigur nas estepes mongóis em 744, chegando a auxiliar a dinastia Tang durante a rebelião de An Lushan. Após o colapso do canato em 840, migraram para o Turquestão Oriental (atual Xinjiang), onde estabeleceram o próspero Reino de Qocho, submetido pacificamente aos mongóis em 1209." }],
  Ouighurs: [{ from: 744, to: 1209, text: "Confederação turca que substituiu os Göktürk no poder das estepes mongóis em 744, mantendo estreitas relações comerciais e políticas com a China Tang. Expulsos pelos Quirguizes em 840, reassentaram-se em Turfan e no Turquestão Oriental, onde floresceram como reino sedentário budista e comerciante até se tornarem vassalos mongóis." }],
  Karluks: [{ from: 766, to: 940, text: "Confederação turca da Ásia Central que, em aliança com os árabes, teve papel decisivo na derrota das forças chinesas Tang na batalha do rio Talas em 751. Estabeleceram o Estado Yabgu Carluque a partir de 766 e, no século X, sua elite converteu-se ao islã, dando origem à dinastia Cara-Kanida." }],
  Kurykans: [{ from: 600, to: 1200, text: "Antigo povo turco das margens do lago Baikal, na Sibéria, mencionado nas inscrições de Orkhon como aliados e súditos ocasionais dos canatos turcos das estepes. Considerados ancestrais dos iacutos atuais, foram gradualmente absorvidos ou deslocados por migrações mongóis e outros povos turcos ao longo da Idade Média." }],
  "Turcik tribes": [{ from: -200, to: 552, text: "Rótulo genérico para as diversas tribos turcas nômades que habitavam as estepes eurasiáticas antes da formação dos grandes canatos. Viviam de pastoreio e guerra, movendo-se entre a Sibéria, a Mongólia e a Ásia Central, até se unificarem sob a liderança dos Göktürk em 552." }],
  Xia: [{ from: -2070, to: -1600, text: "Tradicionalmente considerada a primeira dinastia chinesa, segundo a historiografia clássica fundada pelo lendário Yu, o Grande, controlador das enchentes do rio Amarelo. Sua existência histórica ainda é debatida por arqueólogos, mas marca o início da narrativa dinástica chinesa, antes de ser sucedida pela dinastia Shang." }],
  "Khanate of Sibir": [{ from: 1468, to: 1598, text: "Canato turco-mongol siberiano centrado próximo à atual Tobolsk, herdeiro da fragmentação da Horda Dourada. Foi conquistado pelos cossacos russos liderados por Yermak a partir de 1582, processo concluído em 1598, abrindo caminho para a expansão russa pela Sibéria, região que herdou seu nome." }],
  "Nogai Horde": [{ from: 1440, to: 1634, text: "Confederação turco-mongol das estepes entre os rios Volga e Ural, formada a partir da fragmentação da Horda Dourada sob a liderança do clã Mangit. Manteve-se como potência nômade influente no comércio e na política da região do Cáspio até ser derrotada e absorvida pelos calmucos no século XVII." }],
  Saffarids: [{ from: 861, to: 1003, text: "Dinastia persa fundada pelo ex-artesão Ya'qub ibn al-Layth no Sistão, no leste do Irã, sendo uma das primeiras potências iranianas a se afirmar após a conquista árabe. Chegou a desafiar diretamente o califado abássida antes de perder território para os samânidas e, mais tarde, os gaznévidas." }],
  "Aghlabid Emirate": [{ from: 800, to: 909, text: "Dinastia árabe que governou a Ifríquia, atual Tunísia, como vassala nominal do califado abássida a partir de 800. Promoveu a conquista da Sicília a partir de 827, antes de ser derrubada pelos fatímidas ismaelitas em 909." }],
  "Idrisid Caliphate": [{ from: 788, to: 974, text: "Primeiro Estado islâmico independente do Marrocos, fundado em 788 por Idris ibn Abdallah, descendente de Ali e neto de Hassan ibn Ali, fugido das perseguições abássidas. Fundou a cidade de Fez e islamizou profundamente a região antes de fragmentar-se e ser finalmente absorvido por rivais no fim do século X." }],
  "Watassid Morocco": [{ from: 1472, to: 1554, text: "Dinastia berbere que sucedeu os merínidas no governo do Marrocos a partir de 1472, mantendo a capital em Fez. Enfrentou pressão crescente de portugueses e espanhóis na costa atlântica, até ser derrubada pelos xerifes saadianos em 1554." }],
  "Buyid Emirate": [{ from: 934, to: 1062, text: "Dinastia persa xiita que, a partir de 934, conquistou o Iraque e partes do Irã, controlando Bagdá e mantendo o califa abássida como figura nominal sob tutela política. Seu domínio declinou com disputas internas até serem substituídos pelos turcos seljúcidas em 1062." }],
  "Bulgar Khanate": [{ from: 681, to: 864, text: "Primeiro Império Búlgaro, fundado em 681 por Asparukh às margens do baixo Danúbio após migração das estepes pônticas, impondo-se ao Império Bizantino. Governando sobre uma população eslava majoritária, seus canes pagãos mantiveram o Estado até a conversão ao cristianismo em 864, que marcou uma nova fase eslavizada do reino." }],
  Mongols: [{ from: 1130, to: 1206, text: "Antes da unificação imperial, os mongóis formavam um mosaico de tribos nômades rivais nas estepes da Mongólia, organizadas em confederações instáveis como a Khamag Mongol. Séculos de disputas internas e alianças mutáveis terminaram em 1206, quando Temujin uniu as tribos sob seu comando e foi proclamado Gêngis Khan." }],

  // === India / Southeast Asia ===
  Vakataka: [{ from: 250, to: 500, text: "Os Vakataka foram uma dinastia que dominou o Decã central na Índia entre os séculos III e VI, mantendo estreitas alianças matrimoniais com os Gupta do norte. Foram grandes mecenas das artes, patrocinando a escavação e pintura das grutas budistas de Ajanta, um dos maiores tesouros artísticos da Índia antiga." }],
  "Chalukya Empire": [{ from: 543, to: 753, text: "O Império Chalukya, com capital em Badami, unificou grande parte do Decã e do sul da Índia entre os séculos VI e VIII, enfrentando Pallavas e o imperador Harsha-vardhana. Promoveu a arquitetura em pedra dravídica e nagara, deixando templos notáveis em Badami, Aihole e Pattadakal." }],
  Chalukyas: [{ from: 543, to: 1189, text: "Os Chalukyas formaram uma das principais dinastias do Decã, governando em diferentes fases entre os séculos VI e XII a partir de capitais como Badami e Kalyani. Rivalizaram com Pallavas, Rashtrakutas e Cholas pelo controle do sul da Índia, deixando um rico legado de templos e inscrições." }],
  "Western Chalukyas": [{ from: 973, to: 1189, text: "Os Chalukyas Ocidentais, com capital em Kalyani, restauraram o poder chalukya no Decã a partir do século X, após um período de domínio Rashtrakuta. Governaram até o final do século XII, quando foram suplantados por antigos vassalos, os Hoysalas e os Kalachuris." }],
  "Vedic Aryans": [{ from: -1500, to: -500, text: "Os arianos védicos foram povos indo-europeus que migraram para o subcontinente indiano a partir de cerca de 1500 a.C., trazendo a língua sânscrita e os hinos que formaram os Vedas. Sua fusão com populações locais lançou as bases da civilização hindu clássica, incluindo o sistema de castas e os primeiros reinos do norte da Índia." }],
  Palas: [{ from: 750, to: 1161, text: "A dinastia Pala governou Bengala e Bihar entre os séculos VIII e XII, sendo a última grande potência budista da Índia. Fundaram e sustentaram importantes universidades monásticas, como Vikramashila, e ampliaram Nalanda, espalhando o budismo pelo Tibete e pelo Sudeste Asiático." }],
  Kanauj: [{ from: 606, to: 1194, text: "Kanauj foi uma cidade e reino do norte da Índia que se tornou capital imperial sob Harshavardhana no século VII. Nos séculos seguintes tornou-se o prêmio disputado no chamado 'triângulo de Kanauj', guerra tríplice entre Palas, Pratiharas e Rashtrakutas pelo domínio do norte da Índia." }],
  Bengal: [{ from: -300, to: 1204, text: "Bengala é a região histórica do leste do subcontinente indiano, conhecida desde a Antiguidade por sua agricultura fértil de arroz e comércio marítimo. Foi berço de reinos como o dos Pala, grandes patronos budistas, antes de ser conquistada pelos sultanatos turco-afegãos no início do século XIII." }],
  Rajastan: [{ from: 600, to: 1200, text: "O Rajastão, no noroeste da Índia, é a terra histórica dos clãs guerreiros rajputes, que desde o início da Idade Média ergueram fortalezas e pequenos reinos rivais nesta região árida. Sua cultura guerreira e código de honra os tornaram símbolo da resistência hindu às invasões muçulmanas." }],
  Rajputana: [{ from: 700, to: 1300, text: "Rajputana era o nome histórico dado ao conjunto de principados governados pelos clãs rajputes no noroeste da Índia. Cada reino, como Mewar, Marwar e Amber, mantinha sua própria dinastia guerreira, unidas por laços de casta, honra militar e rivalidades constantes entre si." }],
  Bundelkhand: [{ from: 831, to: 1315, text: "Bundelkhand, região do centro-norte da Índia entre o Rajastão e Bengala, foi o coração do reino rajpute dos Chandela entre os séculos IX e XIII. Os Chandela ficaram famosos por construir os magníficos templos de Khajuraho, decorados com esculturas elaboradas." }],
  "Kingdom of Sind": [{ from: 489, to: 712, text: "O Reino do Sinde, na região que hoje corresponde ao sul do Paquistão, foi um antigo reino hindu-budista às margens do rio Indo. Em 712, foi conquistado pelo general omíada Muhammad bin Qasim, marcando uma das primeiras grandes expansões árabo-islâmicas ao subcontinente indiano." }],
  "Maitraka Kingdom": [{ from: 475, to: 776, text: "O Reino Maitraka governou a região de Gujarat, no oeste da Índia, a partir de sua capital em Vallabhi, após o declínio do Império Gupta. Vallabhi tornou-se um importante centro de aprendizado budista, rivalizando com Nalanda, até ser destruída por invasões árabes no século VIII." }],
  Burmese: [{ from: 849, to: 1885, text: "Os birmaneses construíram uma sucessão de reinos no vale do rio Irauádi, começando pelo Império de Pagan no século IX, seguido por Ava, Toungoo e Konbaung. Essa civilização budista theravada dominou o atual Mianmar até a conquista britânica completa em 1885." }],
  "Burmese kingdoms": [{ from: 1044, to: 1885, text: "Os reinos birmaneses sucederam-se ao longo de quase um milênio: o Império de Pagan, fundado por Anawrahta em 1044, unificou pela primeira vez a Birmânia sob o budismo theravada. Após seu colapso vieram Ava, Toungoo e Konbaung, até a anexação britânica em 1885 encerrar a monarquia birmanesa." }],
  Ava: [{ from: 1364, to: 1555, text: "O Reino de Ava sucedeu o Império de Pagan como principal potência birmanesa, com capital fundada em 1364 no centro do país. Enfraquecido por guerras constantes contra os shan e os mons, foi conquistado pela dinastia Toungoo em 1555." }],
  "Shan states": [{ from: 1287, to: 1885, text: "Os principados Shan, no planalto leste da Birmânia, surgiram após o colapso do Império de Pagan em 1287 e eram tradicionalmente governados por chefes locais chamados sawbwas. Mantiveram considerável autonomia política por séculos, até serem incorporados ao domínio britânico em 1885." }],
  Siam: [{ from: 1238, to: 1939, text: "Siam foi o nome histórico do reino tailandês, desde a fundação de Sukhothai em 1238 até a mudança oficial do nome para Tailândia em 1939. Ao longo desse período sucederam-se os reinos de Sukhothai, Ayutthaya e Bangkok (Rattanakosin), únicos no Sudeste Asiático a escapar da colonização europeia." }],
  Thailand: [{ from: 1939, to: 2025, text: "A Tailândia é o nome adotado em 1939 pelo antigo reino de Siam, mantendo a monarquia constitucional centrada em Bangkok. É a única nação do Sudeste Asiático continental que nunca foi formalmente colonizada por potências europeias." }],
  "Thai Kingdoms": [{ from: 1238, to: 1767, text: "Os reinos tailandeses compreendem o conjunto de estados que floresceram na bacia do rio Chao Phraya e arredores, como Sukhothai, Lan Na e Ayutthaya, entre os séculos XIII e XVIII. Essas monarquias budistas theravada rivalizaram entre si e com khmers e birmaneses pelo domínio da região." }],
  Lavo: [{ from: 648, to: 1388, text: "Lavo, atual Lopburi, foi um antigo reino mon-khmer no centro da Tailândia, ponte cultural entre o mundo mon e o khmer do Camboja. Floresceu por séculos como centro religioso budista e hindu antes de ser absorvido pelo crescente reino de Ayutthaya no século XIV." }],
  "Mon-Khmer": [{ from: -600, to: 1500, text: "Mon-Khmer é o rótulo para os povos falantes de línguas da família austroasiática que habitaram o Sudeste Asiático continental desde a Antiguidade, incluindo mons, khmers e diversos grupos menores. Foram responsáveis por reinos pioneiros como Dvaravati, Lavo e o próprio Império Khmer de Angkor." }],
  Malays: [{ from: 200, to: 1500, text: "Os malaios são um povo austronésio do Sudeste Asiático marítimo, historicamente ligados ao comércio, à navegação e à difusão do Islã pelo arquipélago a partir do século XIII. Formaram importantes talassocracias, como Srivijaya e o Sultanato de Malaca." }],
  Malay: [{ from: 200, to: 1500, text: "Os malaios são um povo austronésio do Sudeste Asiático marítimo, historicamente ligados ao comércio, à navegação e à difusão do Islã pelo arquipélago a partir do século XIII. Formaram importantes talassocracias, como Srivijaya e o Sultanato de Malaca." }],
  Malaya: [{ from: 1826, to: 1957, text: "Malaya foi o nome histórico da região peninsular da Malásia, sob domínio britânico desde o estabelecimento dos Assentamentos do Estreito em 1826. Tornou-se independente em 1957, formando a base do que viria a ser a moderna Federação da Malásia." }],
  "Papua New Guinea": [{ from: 1884, to: 1975, text: "A Papua-Nova Guiné, na metade oriental da ilha da Nova Guiné, foi dividida entre administração britânica/australiana e alemã a partir de 1884. Alcançou a independência em 1975, tornando-se uma nação marcada por extraordinária diversidade linguística e cultural." }],
  Papuans: [{ from: -40000, to: 1975, text: "Os papuas são os povos indígenas da Nova Guiné, descendentes de uma das mais antigas migrações humanas fora da África, presentes na ilha há mais de 40 mil anos. Desenvolveram centenas de línguas e culturas distintas, adaptadas às terras altas e às regiões costeiras da ilha." }],
  Papuan: [{ from: -40000, to: 1975, text: "Os papuas são os povos indígenas da Nova Guiné, descendentes de uma das mais antigas migrações humanas fora da África, presentes na ilha há mais de 40 mil anos. Desenvolveram centenas de línguas e culturas distintas, adaptadas às terras altas e às regiões costeiras da ilha." }],
  Papou: [{ from: -40000, to: 1975, text: "Os papuas são os povos indígenas da Nova Guiné, descendentes de uma das mais antigas migrações humanas fora da África, presentes na ilha há mais de 40 mil anos. Desenvolveram centenas de línguas e culturas distintas, adaptadas às terras altas e às regiões costeiras da ilha." }],
  "Papuan neolithic farmers": [{ from: -7000, to: -2000, text: "Os agricultores neolíticos papuas das terras altas da Nova Guiné desenvolveram, de forma independente, uma das primeiras agriculturas do mundo, cultivando taro, inhame e cana-de-açúcar há cerca de 7.000 anos. O sítio arqueológico de Kuk Swamp comprova esse pioneirismo agrícola isolado do restante do mundo." }],

  // === Africa: regional kingdoms, colonial administrations, modern nations ===
  Botswana: [{ from: 1966, to: 2025, text: "O Botsuana tornou-se independente do Reino Unido em 1966, transformando-se em um dos países mais estáveis e prósperos da África graças à descoberta de diamantes e a décadas de governo democrático ininterrupto. O país é frequentemente citado como exemplo de boa governança e gestão responsável de recursos naturais no continente." }],
  Kenya: [{ from: 1963, to: 2025, text: "O Quênia conquistou a independência do Reino Unido em 1963, sob a liderança de Jomo Kenyatta, líder nacionalista que havia enfrentado a repressão colonial durante a revolta Mau Mau. Desde então, o país se consolidou como um dos principais polos econômicos e políticos da África Oriental." }],
  "Central African Republic": [{ from: 1960, to: 2025, text: "A República Centro-Africana tornou-se independente da França em 1960, mas sua história pós-colonial foi marcada por instabilidade política, golpes de Estado e conflitos armados, incluindo o notório regime de Jean-Bédel Bokassa nos anos 1970. Apesar de rica em recursos como diamantes e urânio, o país permanece entre os mais pobres do mundo." }],
  "Madagascar (France)": [{ from: 1897, to: 1960, text: "Madagascar foi anexada pela França em 1896, após a conquista do Reino Merina, tornando-se colônia formal em 1897. Sob domínio colonial, a ilha foi explorada economicamente e viu revoltas nacionalistas, como a sangrenta insurreição de 1947, até alcançar a independência em 1960." }],
  Somalia: [{ from: 1960, to: 2025, text: "A Somália moderna nasceu em 1960 da união entre a ex-Somalilândia Britânica e a ex-Somália Italiana, formando um Estado independente. Após décadas de instabilidade, o país mergulhou em guerra civil a partir de 1991, com o colapso do governo central." }],
  Darfur: [{ from: 1603, to: 1916, text: "O Sultanato de Darfur foi um reino islâmico independente no oeste do atual Sudão, fundado pela dinastia Keira no início do século XVII e importante nas rotas comerciais transaarianas. Manteve sua autonomia até ser conquistado e anexado ao Sudão anglo-egípcio em 1916, após a derrota e morte do sultão Ali Dinar." }],
  Luba: [{ from: 1585, to: 1889, text: "O Império Luba foi um dos mais poderosos reinos da savana da África Central, formado no século XVI na região do atual sudeste da República Democrática do Congo, com um sofisticado sistema político baseado na sacralidade da realeza. Prosperou pelo controle de rotas comerciais de cobre, ferro e sal antes de declinar sob pressão de incursões esclavagistas árabe-suaílis e da colonização europeia no final do século XIX." }],
  "Hausa States": [{ from: 1000, to: 1808, text: "Os Estados Hauçás formavam uma rede de cidades-estado independentes no norte da atual Nigéria e Níger, como Kano, Katsina e Zaria, prósperas graças ao comércio transaariano e à produção artesanal. No início do século XIX, foram conquistados pela jihad fulani de Usman dan Fodio, que os unificou sob o Califado de Sokoto." }],
  "Mesopotamia (GB)": [{ from: 1920, to: 1932, text: "Após a Primeira Guerra Mundial e o colapso do Império Otomano, a Mesopotâmia foi colocada sob mandato britânico pela Liga das Nações em 1920, ano em que enfrentou uma grande revolta árabe. A administração britânica conduziu o território à criação do Reino do Iraque, que obteve independência formal em 1932." }],
  "Italian Somaliland": [{ from: 1889, to: 1960, text: "A Somalilândia Italiana foi estabelecida como protetorado a partir de 1889, servindo de base para as ambições imperiais italianas no Chifre da África. Após a Segunda Guerra Mundial, passou a ser administrada sob tutela italiana da ONU até sua independência em 1960, quando se uniu à Somalilândia Britânica para formar a Somália." }],
  "French Cameroons": [{ from: 1916, to: 1960, text: "Após a derrota alemã na Primeira Guerra Mundial, os Camarões foram divididos entre França e Reino Unido, cabendo à França a maior parte do território sob mandato da Liga das Nações e depois tutela da ONU. A região francesa alcançou a independência em 1960, tornando-se a República dos Camarões." }],
  "Angola (Portugal)": [{ from: 1575, to: 1975, text: "Angola foi colonizada por Portugal a partir de 1575, tornando-se um dos pilares do comércio transatlântico de escravos e, depois, uma das colônias mais valiosas do império português na África. O domínio colonial só terminou em 1975, após uma longa guerra de independência, dando lugar imediato a uma guerra civil interna." }],
  "Mozambique (Portugal)": [{ from: 1505, to: 1975, text: "Moçambique foi colonizado por Portugal a partir do início do século XVI, servindo como entreposto estratégico nas rotas comerciais do Oceano Índico e, mais tarde, como fonte de mão de obra e matérias-primas. O território permaneceu sob domínio português até 1975, quando alcançou a independência após uma guerra de libertação liderada pela FRELIMO." }],
  "Northern Rhodesia": [{ from: 1911, to: 1964, text: "A Rodésia do Norte foi formada em 1911 pela fusão de territórios administrados pela British South Africa Company, tornando-se depois protetorado britânico direto, com economia baseada na exploração de cobre. Em 1964, o território conquistou a independência como Zâmbia, sob a liderança de Kenneth Kaunda." }],
  Adal: [{ from: 1415, to: 1577, text: "O Sultanato de Adal foi um poderoso Estado muçulmano do Chifre da África, centrado na região da atual Somalilândia/Etiópia, e rival histórico dos reinos cristãos etíopes. Atingiu seu auge no século XVI sob o imame Ahmad ibn Ibrahim al-Ghazi, conhecido como Ahmad Gragn, que quase conquistou a Etiópia cristã antes de ser derrotado com apoio português." }],
  Senegal: [{ from: 1960, to: 2025, text: "O Senegal tornou-se independente da França em 1960, inicialmente unido ao Mali na efêmera Federação do Mali, sob a liderança do poeta e estadista Léopold Sédar Senghor. Desde então, o país se destacou como uma das democracias mais estáveis da África Ocidental." }],
  Air: [{ from: 1449, to: 1906, text: "O Sultanato de Air, centrado na cidade de Agadez, foi um reino tuaregue fundado em meados do século XV no deserto do Saara, atuando como importante entreposto nas rotas caravaneiras transaarianas. Manteve sua autonomia por séculos até ser incorporado ao império colonial francês no início do século XX." }],
  Funj: [{ from: 1504, to: 1821, text: "O Sultanato de Funj, também conhecido como Sultanato de Sennar, foi fundado em 1504 e tornou-se o principal poder islâmico no Sudão após o declínio dos reinos cristãos núbios. O sultanato controlou o comércio ao longo do Nilo Azul até ser conquistado pelas forças egípcias de Muhammad Ali em 1821." }],
  Kaarta: [{ from: 1753, to: 1854, text: "O reino bambara de Kaarta foi fundado em meados do século XVIII no oeste africano, na região do atual Mali, como Estado rival do vizinho reino de Segu, com quem travou guerras recorrentes pelo controle da região. Kaarta foi finalmente conquistado em 1854 pelo Califado Tucular de El Hadj Umar Tall." }],
  "Portuguese East Africa": [{ from: 1505, to: 1975, text: "Portuguese East Africa era o nome pelo qual Moçambique era conhecido sob domínio colonial português, servindo como entreposto estratégico no comércio do Oceano Índico. A colônia permaneceu sob controle de Lisboa até 1975, quando a independência foi conquistada após anos de luta armada liderada pela FRELIMO." }],
  "Kanem-Bornu": [{ from: 800, to: 1893, text: "O império de Kanem-Bornu foi um dos Estados mais duradouros da história africana, formado a partir do século IX na região do Lago Chade e islamizado ainda na Idade Média, prosperando por séculos graças ao comércio transaariano de escravos, sal e ouro. O império entrou em declínio no século XIX e foi finalmente destruído pelas invasões do conquistador sudanês Rabih az-Zubayr em 1893." }],
  Transvaal: [{ from: 1852, to: 1902, text: "A República Sul-Africana, ou Transvaal, foi um Estado bôer independente reconhecido pela Grã-Bretanha em 1852, com sua economia transformada pela descoberta de ouro em Witwatersrand na década de 1880. O Transvaal foi anexado pelo Império Britânico em 1902, após sua derrota na Segunda Guerra dos Bôeres." }],
  "Sultanate of Utetera": [{ from: 1860, to: 1893, text: "O Sultanato de Utetera foi um pequeno Estado do interior da África Central, na região do Congo, ligado às redes de comércio de escravos e marfim controladas por mercadores árabe-suaílis no século XIX. Como outros sultanatos da região, foi eliminado com a expansão do domínio colonial belga no Congo ao final do século." }],
  "Sultinate of Zanzibar": [{ from: 1856, to: 1964, text: "O Sultanato de Zanzibar, fundado em 1856 como ramo independente do império omanense, tornou-se um dos mais ricos e influentes Estados comerciais da costa suaíli, controlando o comércio de cravo-da-índia, marfim e escravos no Oceano Índico. Transformado em protetorado britânico em 1890, o sultanato foi derrubado em 1964 por uma revolução que abriu caminho à formação da Tanzânia." }],
  "German E. Africa (Tanganyika)": [{ from: 1885, to: 1919, text: "A África Oriental Alemã foi estabelecida em 1885 pela Companhia Alemã da África Oriental e formalizada como colônia do Império Alemão, correspondendo em grande parte ao atual Tanganica. A resistência local, como a rebelião Maji Maji (1905-1907), foi violentamente reprimida antes de o território ser tomado pelos britânicos ao fim da Primeira Guerra Mundial." }],
  Kamerun: [{ from: 1884, to: 1916, text: "Kamerun foi estabelecida como colônia do Império Alemão em 1884, após tratados com chefes locais na costa, expandindo-se para o interior por meio de campanhas militares e da exploração de recursos como borracha e cacau. Com a derrota alemã na Primeira Guerra Mundial, o território foi ocupado por tropas franco-britânicas e dividido entre as duas potências em 1916." }],
  "German South-West Africa": [{ from: 1884, to: 1915, text: "A África do Sudoeste Alemã foi proclamada colônia do Império Alemão em 1884, correspondendo à atual Namíbia. Entre 1904 e 1908, as forças coloniais alemãs perpetraram o genocídio dos povos herero e nama em resposta às suas revoltas, um dos primeiros genocídios do século XX, antes de o território ser conquistado pelas forças sul-africanas em 1915." }],
  "British Protectorate": [{ from: 1880, to: 1960, text: "Protetorado britânico era o rótulo genérico dado a territórios sobre os quais o Reino Unido exercia controle informal sobre política externa e defesa, mantendo, em teoria, governantes e instituições locais no poder. Esse modelo de dominação indireta foi amplamente utilizado pelo império britânico, sobretudo na África e no Oriente Médio, entre o final do século XIX e meados do XX." }],
  "British East Africa": [{ from: 1895, to: 1920, text: "O Protetorado da África Oriental Britânica foi estabelecido em 1895 sobre o território que corresponde ao atual Quênia, após a coroa britânica assumir o controle da Companhia Imperial Britânica da África Oriental. Em 1920, a maior parte do protetorado foi reorganizada como a colônia do Quênia." }],
  "German Empire": [{ from: 1871, to: 1918, text: "O Império Alemão, unificado em 1871 sob a liderança da Prússia, entrou tardiamente na corrida imperialista europeia, adquirindo colônias na África, no Pacífico e na China a partir da década de 1880 sob Bismarck e, depois, o Kaiser Guilherme II. Suas possessões coloniais foram perdidas após a derrota na Primeira Guerra Mundial, junto com o colapso do próprio império em 1918." }],
  "British Somaliland": [{ from: 1884, to: 1960, text: "A Somalilândia Britânica foi estabelecida como protetorado em 1884, na região norte do atual território somali, servindo principalmente como fonte de suprimentos para a colônia britânica de Áden. Enfrentou décadas de resistência liderada pelo movimento derviche de Mohammed Abdullah Hassan antes de conquistar a independência em 1960, unindo-se dias depois à Somália Italiana para formar a Somália." }],
  "Zaire (Belgium)": [{ from: 1908, to: 1960, text: "Zaire foi um dos nomes usados na transição para a independência do Congo Belga, proclamada em 30 de junho de 1960, encerrando décadas de exploração brutal sob domínio belga, iniciado em 1908 quando o território deixou de ser propriedade pessoal do rei Leopoldo II. A independência foi imediatamente seguida por uma grave crise política conhecida como Crise do Congo." }],
  "Libya (IT)": [{ from: 1911, to: 1943, text: "A Líbia foi conquistada pela Itália em 1911 após a guerra ítalo-turca, sendo colonizada de forma particularmente violenta durante o regime fascista de Mussolini, que promoveu campanhas de repressão contra a resistência líbia, como a liderada por Omar Mukhtar, e um extenso programa de colonização agrícola italiana. O domínio italiano terminou em 1943 com a derrota das forças do Eixo no Norte da África durante a Segunda Guerra Mundial." }],
  "Algeria (France)": [{ from: 1830, to: 1962, text: "A Argélia foi invadida pela França em 1830 e progressivamente incorporada como parte integrante do território francês, recebendo um grande contingente de colonos europeus. A colonização terminou em 1962, após a sangrenta Guerra da Independência Argelina, que custou centenas de milhares de vidas." }],
  "Ethiopia (Italy)": [{ from: 1936, to: 1941, text: "A Etiópia foi invadida e ocupada pela Itália fascista em 1936, após a Segunda Guerra Ítalo-Etíope, sendo incorporada à África Oriental Italiana apesar da resistência do imperador Haile Selassie, que apelou em vão à Liga das Nações. A ocupação terminou em 1941, quando forças britânicas e etíopes libertaram o país durante a Segunda Guerra Mundial." }],
  "Cyraneica (UK Lybia)": [{ from: 1943, to: 1951, text: "Após a derrota das forças ítalo-alemãs no Norte da África, a região da Cirenaica passou a ser administrada pelo Reino Unido a partir de 1943. Essa administração militar britânica perdurou até 1951, quando a região se uniu à Tripolitânia e ao Fazã para formar o Reino Unido da Líbia independente." }],
  "Fezzan (Frech Lybia)": [{ from: 1943, to: 1951, text: "Após a campanha do Norte da África na Segunda Guerra Mundial, a região do Fazã, no sul da Líbia, ficou sob administração militar francesa a partir de 1943. Esse controle francês durou até 1951, quando o Fazã se uniu à Cirenaica e à Tripolitânia na formação do Reino Unido da Líbia independente." }],
  Hejaz: [{ from: 1916, to: 1925, text: "O Reino do Hejaz foi proclamado em 1916 pelo xerife Hussein bin Ali, líder da Revolta Árabe contra o Império Otomano durante a Primeira Guerra Mundial, com apoio britânico, tendo Meca e Medina como seus principais centros. O reino foi conquistado em 1925 pelas forças de Ibn Saud, sendo incorporado ao que se tornaria a Arábia Saudita." }],
  Segu: [{ from: 1712, to: 1861, text: "O Império de Segu foi um poderoso reino bambara fundado no início do século XVIII às margens do rio Níger, na região do atual Mali, conhecido por seu exército organizado e sua resistência à islamização. O império foi conquistado em 1861 pelas forças do Califado Tucular de El Hadj Umar Tall." }],
  "Tukular Caliphate": [{ from: 1861, to: 1893, text: "O Califado Tucular foi fundado em meados do século XIX por El Hadj Umar Tall, líder religioso que conduziu uma jihad que conquistou vastos territórios do oeste africano, incluindo os antigos reinos bambaras de Segu e Kaarta. O califado enfrentou resistência interna e externa até ser progressivamente conquistado pelas forças coloniais francesas nas décadas de 1880 e 1890." }],
  Mandes: [{ from: 1235, to: 1600, text: "Os povos mande, ou mandingas, formam um dos principais grupos etnolinguísticos da África Ocidental, historicamente associados à fundação e expansão do Império do Mali entre os séculos XIII e XVI, um dos maiores e mais ricos Estados da África medieval. Sua influência cultural, linguística e comercial se estende até hoje por países como Mali, Guiné e Costa do Marfim." }],
  Azandes: [{ from: 1700, to: 1900, text: "O povo azande é um dos principais grupos etnolinguísticos da África Central, tradicionalmente estabelecido nas regiões de fronteira entre o atual Sudão do Sul, a República Democrática do Congo e a República Centro-Africana. Organizados historicamente em reinos guerreiros liderados por dinastias como a Avongara, os azandes resistiram por muito tempo às incursões esclavagistas árabes e, depois, ao domínio colonial europeu no final do século XIX." }],
  Cushites: [{ from: -3000, to: 1900, text: "Os povos cuxitas constituem um dos principais grupos etnolinguísticos do Chifre da África, incluindo somalis, oromos e afares, com presença na região que remonta a milênios. Historicamente pastores e agricultores, os cuxitas construíram importantes reinos e sultanatos ao longo dos séculos e mantiveram intensas trocas culturais e comerciais com o mundo árabe e com os povos semíticos da Etiópia." }],
  Malagasy: [{ from: -200, to: 1896, text: "O povo malgaxe de Madagascar resulta da fusão entre migrantes austronésios, que colonizaram a ilha há cerca de dois mil anos vindos do Sudeste Asiático, e populações de origem africana bantu, além de influências árabes. Essa singular mistura deu origem a uma cultura e língua únicas no continente africano, consolidadas politicamente sobretudo pelo Reino Merina antes da conquista colonial francesa em 1896." }],
  Mascat: [{ from: 1650, to: 1861, text: "Mascate, capital de Omã, foi o centro de um dos maiores impérios marítimos do Oceano Índico, floresceu sobretudo entre os séculos XVII e XIX sob a dinastia Al Said, controlando rotas comerciais que se estendiam até a costa da África Oriental. A partir de Mascate, os omanenses expandiram sua influência até Zanzibar, que chegou a ser capital do sultanato entre 1832 e 1861, ano em que os dois territórios se separaram definitivamente." }],

  // === Americas: archaeological cultures & indigenous peoples ===
  "Patagonian shellfish and marine mammal hunters": [{ from: -6000, to: 1520, text: "Povos indígenas da costa patagônica, no extremo sul da América do Sul, que subsistiam principalmente da coleta de moluscos e da caça de lobos-marinhos, focas e outros mamíferos marinhos, além de aves costeiras. Usavam pequenas embarcações e abrigos temporários, deslocando-se ao longo do litoral conforme a disponibilidade sazonal de recursos marinhos." }],
  "Plain-Pottery culture": [{ from: 100, to: 400, text: "Cultura arqueológica da Idade do Ferro na região báltica (atuais Lituânia e Bielorrússia), identificada por seus vasos cerâmicos lisos, sem decoração incisa ou pintada. Seus povos viviam em pequenas aldeias fortificadas, praticando agricultura, pecuária e metalurgia incipiente do ferro." }],
  "Shellfish gatherers": [{ from: -8000, to: 1500, text: "Rótulo genérico para povos costeiros que baseavam sua subsistência principalmente na coleta de moluscos e mariscos em manguezais, estuários e praias rochosas. Deixaram como marca arqueológica característica grandes sambaquis ou concheiros, acumulados ao longo de gerações de exploração dos recursos litorâneos." }],
  "Laurel complex": [{ from: -200, to: 800, text: "Complexo arqueológico do subártico canadense e região dos Grandes Lagos, associado a caçadores-coletores da floresta boreal. Caracteriza-se por cerâmica decorada distintiva e por redes de troca de cobre nativo extraído da região do Lago Superior." }],
  "Point Peninsula": [{ from: -200, to: 900, text: "Complexo arqueológico da tradição Woodland no nordeste da América do Norte, ao longo do vale do rio São Lourenço e região dos Grandes Lagos. Seus povos combinavam caça, pesca e coleta com o uso crescente de cerâmica e participavam de redes regionais de troca de bens cerimoniais." }],
  "Swift Creek Culture": [{ from: 100, to: 800, text: "Cultura arqueológica do sudeste da atual região dos Estados Unidos, notável por sua cerâmica estampada com desenhos elaborados aplicados com paletas entalhadas. Construíam montes cerimoniais e mantinham redes de trocas de longa distância com outras sociedades da tradição Woodland." }],
  "Brushed Pottery culture": [{ from: -100, to: 400, text: "Cultura báltica da Idade do Ferro caracterizada pela produção de cerâmica de superfície escovada ou áspera, obtida ao esfregar a peça ainda úmida com feixes de gravetos. Seus povos praticavam agricultura de subsistência e criação de gado em pequenos povoados fortificados." }],
  "Bell-shaped burials culture": [{ from: 100, to: 400, text: "Cultura pré-histórica da região báltica marcada por sepultamentos característicos em covas escavadas em formato de sino, frequentemente reunidos em necrópoles. Associa-se a comunidades agropastoris da Idade do Ferro que também produziam cerâmica e trabalhavam metais." }],
  "Marksville Culture": [{ from: -100, to: 400, text: "Cultura arqueológica do baixo vale do rio Mississippi, ligada à ampla rede de intercâmbio da tradição Hopewell. Seus povos ergueram montes cerimoniais e funerários e produziram cerâmica decorada com motivos estampados e incisos característicos." }],
  "Andean states and chiefdoms": [{ from: 200, to: 1470, text: "Rótulo que reúne o mosaico de pequenos reinos, senhorios e cacicados que floresceram nos Andes fora ou entre os grandes impérios regionais, como Wari e Inca. Combinavam agricultura em terraços, pastoreio de camelídeos e comércio inter-regional, com organizações políticas que variavam de simples chefias a confederações mais complexas." }],
  "Paleo-Inuit": [{ from: -2500, to: 1500, text: "Povos paleo-esquimós que ocuparam o Ártico norte-americano e a Groenlândia antes da chegada dos ancestrais diretos dos inuítes modernos, incluindo as tradições Pré-Dorset e Dorset. Viviam da caça de focas, morsas e caribus, adaptando-se a um ambiente extremamente frio com ferramentas de pedra, osso e marfim." }],
  "Late Jomon culture": [{ from: -2000, to: -1000, text: "Fase tardia do período Jomon no arquipélago japonês, marcada por maior sedentarismo, aldeias mais estáveis e complexidade social crescente entre caçadores-coletores-pescadores. Produziam cerâmica elaborada com decoração em cordas e desenvolveram práticas rituais e funerárias mais sofisticadas." }],
  "Mesoamerican city-states and chiefdoms": [{ from: 900, to: 1519, text: "Rótulo genérico para o conjunto de pequenas cidades-estado e cacicados mesoamericanos que coexistiram à margem dos grandes impérios, como o asteca e os reinos maias. Baseavam-se na agricultura de milho, feijão e abóbora, no comércio regional e em estruturas políticas locais lideradas por governantes hereditários." }],
  Apache: [{ from: 1500, to: 1850, text: "Povo indígena de língua atabascana do sudoeste norte-americano, organizado em bandos móveis dedicados à caça, coleta e incursões. Conhecido por sua notável mobilidade e adaptabilidade em terrenos áridos, além da forte resistência à expansão espanhola, mexicana e depois estadunidense." }],
  Shoshoni: [{ from: 1500, to: 1850, text: "Povo indígena da Grande Bacia e dos planaltos do oeste norte-americano, tradicionalmente organizado em pequenos grupos familiares de caçadores-coletores adaptados a ambientes semiáridos. Após a introdução do cavalo, alguns grupos shoshone passaram a caçar bisões nas planícies, ampliando seu território e mobilidade." }],
  "Naskapi Innu": [{ from: 1500, to: 1900, text: "Os naskapi, parte do povo Innu, são indígenas caçadores do interior do Labrador e do norte de Quebec, no Canadá, cuja subsistência dependia fortemente do caribu migratório. Viviam em pequenos grupos nômades adaptados ao rigoroso clima subártico, utilizando tendas de pele e trenós para deslocamento sazonal." }],
  Assiniboin: [{ from: 1500, to: 1850, text: "Povo indígena das planícies norte-americanas, aparentado linguisticamente aos sioux, tradicionalmente organizado em bandos caçadores de bisões. Viviam em tendas de couro (tipis) facilmente transportáveis e mantinham amplas redes de comércio e alianças com povos vizinhos das planícies." }],
  "Maya states": [{ from: 250, to: 900, text: "Rótulo genérico para os diversos reinos e cidades-estado maias que floresceram na Mesoamérica, cada um governado por uma dinastia própria e frequentemente em conflito ou aliança com vizinhos. Compartilhavam escrita hieroglífica, calendário sofisticado, arquitetura monumental em pirâmides e uma economia baseada no cultivo de milho." }],
  "Adena Culture": [{ from: -1000, to: -200, text: "Cultura pré-histórica do vale do rio Ohio, na América do Norte, conhecida por seus grandes montes funerários e cerimoniais de terra. Antecessora direta da cultura Hopewell, praticava horticultura incipiente, produzia artefatos de pedra polida e mantinha complexos rituais funerários." }],
  "Milograd culture": [{ from: -700, to: 100, text: "Cultura arqueológica da Idade do Ferro localizada na região do atual sul da Bielorrússia e norte da Ucrânia. Seus povos viviam em povoados fortificados (gorodishches), praticavam agricultura e pecuária, e produziam cerâmica característica com decoração simples." }],
  Natchez: [{ from: 700, to: 1731, text: "Povo indígena do sudeste norte-americano, na região do atual Mississippi, herdeiro das tradições Mississippianas de construção de montes. Organizava-se em uma sociedade fortemente hierárquica centrada na figura do Grande Sol, governante de origem divina, com camadas sociais rigidamente definidas." }],
  Pomo: [{ from: 1000, to: 1850, text: "Povo indígena do norte da Califórnia, tradicionalmente organizado em pequenas tribos autônomas de caçadores-coletores-pescadores. Ficou célebre por sua cestaria extremamente refinada, utilizada tanto no cotidiano quanto em cerimônias e trocas com povos vizinhos." }],
  Cherookee: [{ from: 1000, to: 1838, text: "Os cherokee, um dos maiores povos indígenas do sudeste da América do Norte, descendem de tradições agrícolas ligadas à cultura Mississippiana. Viviam em aldeias organizadas em torno de casas de conselho, praticando agricultura de milho, feijão e abóbora complementada pela caça." }],
  Tlinoit: [{ from: -500, to: 1867, text: "Os tlingit, povo indígena da costa noroeste do Pacífico (Alasca e Colúmbia Britânica), desenvolveram uma sociedade hierárquica organizada em clãs, com fartura de recursos marinhos, especialmente salmão. São conhecidos por seus totens esculpidos, grandes casas de madeira de cedro e pela tradição cerimonial do potlatch." }],
  "Dutch Brazil": [{ from: 1630, to: 1654, text: "O Brasil Holandês foi o território do nordeste açucareiro brasileiro, principalmente em Pernambuco, ocupado pela Companhia das Índias Ocidentais Holandesa. Sob administração de figuras como Maurício de Nassau, a colônia combinou exploração açucareira, comércio atlântico e certo grau de tolerância religiosa, até ser reconquistada pelos portugueses." }],
  "Archaic Amerindian hunter-gatherers": [{ from: -8000, to: -2000, text: "Povos indígenas americanos do período Arcaico pós-glacial, que se adaptaram a ambientes em transformação através da caça de pequena e média fauna, pesca e coleta intensiva de plantas silvestres. Antecederam a adoção generalizada da agricultura, desenvolvendo ferramentas de pedra polida e maior sedentarismo sazonal." }],
  "Mesoamerican hunter-gatherers and maïze farmers": [{ from: -7000, to: -2000, text: "Povos da Mesoamérica em transição entre a caça-coleta tradicional e o cultivo incipiente do milho, feijão e abóbora. Esse processo gradual de domesticação de plantas lançou as bases para o posterior surgimento das aldeias agrícolas e civilizações mesoamericanas." }],
  Anasazi: [{ from: 100, to: 1300, text: "Os ancestrais puebloanos, povo indígena do sudoeste norte-americano, construíram grandes complexos de pedra e adobe como os de Chaco Canyon e Mesa Verde, incluindo moradias em penhascos. Praticavam agricultura de milho, feijão e abóbora em ambiente árido, com elaborados sistemas de irrigação e redes de estradas cerimoniais." }],
  Mogollon: [{ from: 200, to: 1450, text: "Cultura indígena pré-histórica do sudoeste norte-americano, na região do atual Novo México e Arizona, que combinava agricultura de milho com caça e coleta. Ficou famosa pela cerâmica Mimbres, decorada com desenhos geométricos e figurativos de grande refinamento artístico." }],
  "El Paraiso": [{ from: -2000, to: -1500, text: "Sítio arqueológico e cultura da costa central do Peru, um dos maiores complexos monumentais das Américas construídos antes da introdução da cerâmica. Seus habitantes combinavam pesca marinha abundante com cultivo incipiente de algodão e outras plantas, erguendo grandes estruturas de pedra e adobe de caráter cerimonial." }],
  "Chinchorro culture": [{ from: -7000, to: -1500, text: "Cultura pré-histórica da costa do atual norte do Chile e sul do Peru, cuja economia se baseava na pesca, na caça marinha e na coleta litorânea. Ficou mundialmente famosa por praticar as múmias artificiais mais antigas conhecidas, elaboradas ritualisticamente muito antes das múmias egípcias." }],
  "Tasmanian hunter-gatherers": [{ from: -8000, to: 1800, text: "Povos aborígenes caçadores-coletores isolados na ilha da Tasmânia, na Oceania, separados do continente australiano pela elevação do nível do mar ao fim da última glaciação. Subsistiam da caça de fauna nativa, da pesca e da coleta de mariscos e plantas silvestres, desenvolvendo tecnologias e costumes distintos dos povos aborígenes continentais." }],
  "Catacomb culture": [{ from: -2800, to: -1900, text: "Cultura arqueológica da Idade do Bronze das estepes pônticas, na região do atual sul da Rússia e Ucrânia, sucessora da cultura Yamnaya. Seus povos eram pastores seminômades que enterravam seus mortos em câmaras subterrâneas do tipo catacumba, sob túmulos em forma de montículo (kurgan)." }],
};

function nearestPeriod(periods: EraSummary[], year: number): EraSummary {
  let best = periods[0];
  let bestDist = Infinity;
  for (const p of periods) {
    const dist = year < p.from ? p.from - year : year > p.to ? year - p.to : 0;
    if (dist < bestDist) {
      bestDist = dist;
      best = p;
    }
  }
  return best;
}

// Returns the era-appropriate summary for a territory at a given year,
// or null if the territory has no curated summary. `name` must be the
// original GeoJSON NAME/SUBJECTO (not the translated display name).
export function summaryFor(name: string, year: number): string | null {
  const periods = TERRITORY_SUMMARIES[name];
  if (!periods || periods.length === 0) return null;
  const containing = periods.find((p) => year >= p.from && year <= p.to);
  return (containing ?? nearestPeriod(periods, year)).text;
}
